-- ============================================================================
-- MySQL 8 ERP demo seed  (container: mysql8, database: analyzerdb, user: root)
-- Entry procedure for static analysis:  ERP_USP_RUN_CYCLE  (erp_usp_run_cycle)
-- ----------------------------------------------------------------------------
-- Theme            : ERP order-to-cash + manufacturing + finance
-- Deep call chain  : run_cycle -> process_all_orders -> process_order
--                    -> allocate_inventory -> reserve_stock -> plan_production
--                    -> explode_bom -> issue_materials -> generate_invoice
--                    -> apply_payment -> update_ledger -> reconcile_account
--                    -> revalue_currency -> post_gl   (depth ~14, >= 8 required)
-- Idempotent       : every table uses CREATE TABLE IF NOT EXISTS; every view /
--                    trigger / event / routine is DROP ... IF EXISTS then CREATE.
--                    Data is TRUNCATE'd then reseeded. Safe to re-run.
-- DELIMITER        : $$ wraps all trigger / event / routine bodies.
-- ----------------------------------------------------------------------------
-- Feature matrix covered (MySQL 8 supported subset):
--   transactions (START TRANSACTION/COMMIT/ROLLBACK, SAVEPOINT/ROLLBACK TO),
--   DECLARE ... HANDLER (EXIT/CONTINUE, SQLEXCEPTION + NOT FOUND), RESIGNAL,
--   triggers (BEFORE/AFTER INSERT/UPDATE/DELETE), views, events (CREATE EVENT),
--   dynamic SQL (PREPARE/EXECUTE/DEALLOCATE), IF/ELSEIF/ELSE, CASE,
--   loops (WHILE, REPEAT/UNTIL, LOOP/LEAVE), cursors, subqueries + correlated
--   subqueries, CTEs incl. WITH RECURSIVE, all joins (INNER/LEFT/RIGHT/CROSS/
--   self; FULL emulated via UNION), temporary tables, window functions,
--   INSERT ... ON DUPLICATE KEY UPDATE (upsert), JSON columns/functions,
--   generated columns, AUTO_INCREMENT, session (@var) vs local (DECLARE) scope,
--   ROW_COUNT()/FOUND_ROWS()/LAST_INSERT_ID(), GET DIAGNOSTICS, IFNULL/COALESCE.
-- ----------------------------------------------------------------------------
-- N/A in MySQL (documented, not attempted): packages, routine overloading,
--   materialized views (simulated with erp_mv_customer_sales + erp_usp_refresh_mv),
--   sequences (< 8.0; replaced by AUTO_INCREMENT and the erp_docnum counter).
-- ============================================================================

CREATE DATABASE IF NOT EXISTS analyzerdb;
USE analyzerdb;

-- Recursion depth cap for stored routines (self-recursion in erp_usp_bom_explode_rec
-- and mutual recursion erp_usp_ping <-> erp_usp_pong). Range 0..255; default is 0
-- which forbids recursion, so we raise it here.
SET @@session.max_sp_recursion_depth = 255;

SET FOREIGN_KEY_CHECKS = 0;

-- ============================================================================
-- TABLES  (~25 erp_* tables with PK / FK / indexes, JSON + generated columns)
-- ============================================================================
CREATE TABLE IF NOT EXISTS erp_product_category (
    category_id  INT PRIMARY KEY,
    category_name VARCHAR(80) NOT NULL,
    parent_category_id INT NULL,
    INDEX ix_cat_parent (parent_category_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_customer (
    customer_id  INT AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(120) NOT NULL,
    credit_limit DECIMAL(18,2) DEFAULT 0,
    country      CHAR(2) DEFAULT 'US',
    active       TINYINT DEFAULT 1,
    created_ts   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX ix_cust_active (active)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_product (
    product_id  INT AUTO_INCREMENT PRIMARY KEY,
    sku         VARCHAR(40) NOT NULL,
    category_id INT,
    std_cost    DECIMAL(18,4) DEFAULT 0,
    list_price  DECIMAL(18,4) DEFAULT 0,
    attributes  JSON NULL,
    margin_pct  DECIMAL(9,4) AS (CASE WHEN list_price = 0 THEN 0
                    ELSE ROUND((list_price - std_cost) / list_price, 4) END) STORED,
    active      TINYINT DEFAULT 1,
    UNIQUE KEY uq_prod_sku (sku),
    INDEX ix_prod_cat (category_id),
    CONSTRAINT fk_prod_cat FOREIGN KEY (category_id) REFERENCES erp_product_category (category_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_warehouse (
    warehouse_id INT PRIMARY KEY,
    code         VARCHAR(20) NOT NULL,
    region       VARCHAR(40)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_bin (
    bin_id       INT PRIMARY KEY,
    warehouse_id INT,
    bin_code     VARCHAR(20),
    INDEX ix_bin_wh (warehouse_id),
    CONSTRAINT fk_bin_wh FOREIGN KEY (warehouse_id) REFERENCES erp_warehouse (warehouse_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_stock_level (
    product_id   INT NOT NULL,
    warehouse_id INT NOT NULL,
    bin_id       INT NULL,
    qty_on_hand  DECIMAL(18,4) DEFAULT 0,
    qty_reserved DECIMAL(18,4) DEFAULT 0,
    qty_available DECIMAL(18,4) AS (qty_on_hand - qty_reserved) VIRTUAL,
    PRIMARY KEY (product_id, warehouse_id),
    INDEX ix_stock_wh (warehouse_id),
    CONSTRAINT fk_stock_prod FOREIGN KEY (product_id) REFERENCES erp_product (product_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_stock_move (
    move_id      INT AUTO_INCREMENT PRIMARY KEY,
    product_id   INT,
    warehouse_id INT,
    move_type    VARCHAR(12),
    qty          DECIMAL(18,4),
    ref_doc      VARCHAR(40),
    moved_ts     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX ix_move_prod (product_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_order (
    order_id     INT AUTO_INCREMENT PRIMARY KEY,
    customer_id  INT,
    total_amount DECIMAL(18,2) DEFAULT 0,
    status       VARCHAR(20) DEFAULT 'NEW',
    order_ts     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX ix_order_cust (customer_id),
    INDEX ix_order_status (status),
    CONSTRAINT fk_order_cust FOREIGN KEY (customer_id) REFERENCES erp_customer (customer_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_order_line (
    line_id     INT AUTO_INCREMENT PRIMARY KEY,
    order_id    INT,
    product_id  INT,
    qty         DECIMAL(18,4) DEFAULT 1,
    unit_price  DECIMAL(18,4) DEFAULT 0,
    line_amount DECIMAL(18,2) DEFAULT 0,
    INDEX ix_line_order (order_id),
    INDEX ix_line_prod (product_id),
    CONSTRAINT fk_line_order FOREIGN KEY (order_id) REFERENCES erp_order (order_id),
    CONSTRAINT fk_line_prod  FOREIGN KEY (product_id) REFERENCES erp_product (product_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_invoice (
    invoice_id   INT AUTO_INCREMENT PRIMARY KEY,
    order_id     INT,
    customer_id  INT,
    doc_number   BIGINT,
    gross_amount DECIMAL(18,2) DEFAULT 0,
    net_amount   DECIMAL(18,2) DEFAULT 0,
    currency     CHAR(3) DEFAULT 'USD',
    status       VARCHAR(12) DEFAULT 'OPEN',
    INDEX ix_inv_cust (customer_id),
    INDEX ix_inv_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_invoice_line (
    invoice_line_id INT AUTO_INCREMENT PRIMARY KEY,
    invoice_id  INT,
    product_id  INT,
    qty         DECIMAL(18,4),
    amount      DECIMAL(18,2),
    INDEX ix_invl_inv (invoice_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_payment (
    payment_id  INT AUTO_INCREMENT PRIMARY KEY,
    customer_id INT,
    amount      DECIMAL(18,2),
    currency    CHAR(3) DEFAULT 'USD',
    pay_status  VARCHAR(12) DEFAULT 'NEW',
    paid_ts     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX ix_pay_cust (customer_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_payment_alloc (
    alloc_id   INT AUTO_INCREMENT PRIMARY KEY,
    payment_id INT,
    invoice_id INT,
    amount     DECIMAL(18,2),
    INDEX ix_alloc_pay (payment_id),
    INDEX ix_alloc_inv (invoice_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_shipment (
    shipment_id INT AUTO_INCREMENT PRIMARY KEY,
    order_id    INT,
    doc_number  BIGINT,
    ship_status VARCHAR(12) DEFAULT 'NEW',
    UNIQUE KEY uq_ship_order (order_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_gl_account (
    gl_account_id INT PRIMARY KEY,
    account_name  VARCHAR(80),
    account_type  VARCHAR(20)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_gl_journal (
    gl_journal_id INT PRIMARY KEY,
    journal_date  DATE,
    posted        TINYINT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_gl_entry (
    gl_entry_id   INT AUTO_INCREMENT PRIMARY KEY,
    gl_journal_id INT,
    gl_account_id INT,
    debit         DECIMAL(18,2) DEFAULT 0,
    credit        DECIMAL(18,2) DEFAULT 0,
    memo          VARCHAR(120),
    INDEX ix_ge_journal (gl_journal_id),
    INDEX ix_ge_account (gl_account_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_bom (
    bom_id       INT AUTO_INCREMENT PRIMARY KEY,
    parent_id    INT,
    component_id INT,
    qty_per      DECIMAL(18,4) DEFAULT 1,
    INDEX ix_bom_parent (parent_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_work_order (
    work_order_id INT AUTO_INCREMENT PRIMARY KEY,
    product_id    INT,
    planned_qty   DECIMAL(18,4) DEFAULT 0,
    wo_status     VARCHAR(12) DEFAULT 'PLANNED',
    UNIQUE KEY uq_wo_prod (product_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_employee (
    employee_id INT PRIMARY KEY,
    manager_id  INT NULL,
    full_name   VARCHAR(80),
    INDEX ix_emp_mgr (manager_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_discount (
    discount_id INT AUTO_INCREMENT PRIMARY KEY,
    min_qty     INT,
    rate        DECIMAL(6,4)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_tax_rate (
    tax_id         INT AUTO_INCREMENT PRIMARY KEY,
    country        CHAR(2),
    rate           DECIMAL(6,4),
    effective_from DATE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_fx_rate (
    fx_id     INT AUTO_INCREMENT PRIMARY KEY,
    from_ccy  CHAR(3),
    to_ccy    CHAR(3),
    rate      DECIMAL(18,8),
    rate_date DATE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_docnum (
    doc_type    VARCHAR(20) PRIMARY KEY,
    last_number BIGINT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_period (
    period_code VARCHAR(7) PRIMARY KEY,
    closed      TINYINT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_stats (
    stat_key   VARCHAR(40) PRIMARY KEY,
    stat_value INT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_counter (
    bucket VARCHAR(20) PRIMARY KEY,
    tick   INT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_mv_customer_sales (
    customer_id INT PRIMARY KEY,
    order_count INT DEFAULT 0,
    total_sales DECIMAL(18,2) DEFAULT 0,
    refreshed_ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_audit_log (
    audit_id  INT AUTO_INCREMENT PRIMARY KEY,
    entity    VARCHAR(60),
    entity_id INT,
    action    VARCHAR(30),
    detail    VARCHAR(400),
    logged_ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS erp_audit_archive (
    archive_id INT AUTO_INCREMENT PRIMARY KEY,
    audit_id   INT,
    entity     VARCHAR(60),
    detail     VARCHAR(400),
    archived_ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

