-- ============================================================================
-- VIEWS
-- ============================================================================
CREATE OR REPLACE VIEW erp_v_order_summary AS
SELECT o.order_id, o.customer_id, c.name AS customer_name, o.status,
       IFNULL(SUM(ol.line_amount),0) AS lines_total, COUNT(ol.line_id) AS line_count
  FROM erp_order o
  JOIN erp_customer c ON c.customer_id = o.customer_id
  LEFT JOIN erp_order_line ol ON ol.order_id = o.order_id
 GROUP BY o.order_id, o.customer_id, c.name, o.status;

CREATE OR REPLACE VIEW erp_v_stock_status AS
SELECT sl.product_id, p.sku, sl.warehouse_id, sl.qty_on_hand, sl.qty_reserved,
       (sl.qty_on_hand - sl.qty_reserved) AS qty_available
  FROM erp_stock_level sl
  JOIN erp_product p ON p.product_id = sl.product_id;

CREATE OR REPLACE VIEW erp_v_ar_aging AS
SELECT i.customer_id, c.name AS customer_name,
       SUM(CASE WHEN i.status = 'OPEN' THEN i.gross_amount ELSE 0 END) AS open_amount,
       SUM(CASE WHEN i.status = 'PAID' THEN i.gross_amount ELSE 0 END) AS paid_amount
  FROM erp_invoice i
  JOIN erp_customer c ON c.customer_id = i.customer_id
 GROUP BY i.customer_id, c.name;

