DELIMITER $$

-- ============================================================================
-- TRIGGERS  (BEFORE/AFTER INSERT/UPDATE/DELETE)
-- ============================================================================
CREATE TRIGGER trg_order_line_bi
BEFORE INSERT ON erp_order_line
FOR EACH ROW
BEGIN
  IF NEW.line_amount IS NULL OR NEW.line_amount = 0 THEN
    SET NEW.line_amount = IFNULL(NEW.qty,0) * IFNULL(NEW.unit_price,0);
  END IF;
END$$

CREATE TRIGGER trg_order_line_au
AFTER UPDATE ON erp_order_line
FOR EACH ROW
BEGIN
  IF NEW.line_amount <> OLD.line_amount THEN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ORDER_LINE', NEW.line_id, 'UPDATE',
            CONCAT('amt ', CAST(OLD.line_amount AS CHAR), ' -> ', CAST(NEW.line_amount AS CHAR)));
  END IF;
END$$

CREATE TRIGGER trg_order_ad
AFTER DELETE ON erp_order
FOR EACH ROW
BEGIN
  INSERT INTO erp_audit_log (entity, entity_id, action, detail)
  VALUES ('ORDER', OLD.order_id, 'DELETE', CONCAT('deleted status ', OLD.status));
END$$

CREATE TRIGGER trg_invoice_bu
BEFORE UPDATE ON erp_invoice
FOR EACH ROW
BEGIN
  IF NEW.net_amount = 0 THEN
    SET NEW.net_amount = NEW.gross_amount;
  END IF;
END$$

CREATE TRIGGER trg_audit_ai
AFTER INSERT ON erp_audit_log
FOR EACH ROW
BEGIN
  IF NEW.action = 'ERROR' THEN
    INSERT INTO erp_audit_archive (audit_id, entity, detail)
    VALUES (NEW.audit_id, NEW.entity, NEW.detail);
  END IF;
END$$

-- ============================================================================
-- EVENTS  (scheduled maintenance; CREATE EVENT)
-- ============================================================================
CREATE EVENT ev_refresh_customer_sales
ON SCHEDULE EVERY 1 DAY
DO
BEGIN
  CALL erp_usp_refresh_mv();
END$$

CREATE EVENT ev_archive_audit
ON SCHEDULE EVERY 1 WEEK
DO
BEGIN
  INSERT INTO erp_audit_archive (audit_id, entity, detail)
  SELECT audit_id, entity, detail FROM erp_audit_log
   WHERE logged_ts < (NOW() - INTERVAL 30 DAY);
END$$

-- ============================================================================
-- FUNCTIONS
-- ============================================================================
CREATE FUNCTION erp_fn_discount_rate(p_qty INT) RETURNS DECIMAL(6,4)
READS SQL DATA DETERMINISTIC
BEGIN
  DECLARE v_rate DECIMAL(6,4) DEFAULT 0;
  SELECT rate INTO v_rate FROM erp_discount WHERE min_qty <= p_qty ORDER BY min_qty DESC LIMIT 1;
  RETURN IFNULL(v_rate, 0);
END$$

CREATE FUNCTION erp_fn_line_amount(p_qty DECIMAL(18,4), p_price DECIMAL(18,4)) RETURNS DECIMAL(18,2)
DETERMINISTIC
BEGIN
  DECLARE v_gross DECIMAL(18,2);
  DECLARE v_disc  DECIMAL(6,4);
  SET v_disc = erp_fn_discount_rate(CAST(p_qty AS SIGNED));
  SET v_gross = IFNULL(p_qty,0) * IFNULL(p_price,0);
  RETURN ROUND(v_gross * (1 - v_disc), 2);
END$$

CREATE FUNCTION erp_fn_order_total(p_order_id INT) RETURNS DECIMAL(18,2)
READS SQL DATA
BEGIN
  DECLARE v_total DECIMAL(18,2) DEFAULT 0;
  SELECT IFNULL(SUM(erp_fn_line_amount(qty, unit_price)),0) INTO v_total
    FROM erp_order_line WHERE order_id = p_order_id;
  RETURN v_total;
END$$

CREATE FUNCTION erp_fn_tax_amount(p_amount DECIMAL(18,2), p_country CHAR(2)) RETURNS DECIMAL(18,2)
READS SQL DATA DETERMINISTIC
BEGIN
  DECLARE v_rate DECIMAL(6,4) DEFAULT 0;
  SELECT rate INTO v_rate FROM erp_tax_rate WHERE country = p_country ORDER BY effective_from DESC LIMIT 1;
  RETURN ROUND(p_amount * IFNULL(v_rate,0), 2);
END$$

CREATE FUNCTION erp_fn_fx_rate(p_from CHAR(3), p_to CHAR(3)) RETURNS DECIMAL(18,8)
READS SQL DATA DETERMINISTIC
BEGIN
  DECLARE v_rate DECIMAL(18,8);
  IF p_from = p_to THEN
    RETURN 1.0;
  END IF;
  SELECT rate INTO v_rate FROM erp_fx_rate WHERE from_ccy = p_from AND to_ccy = p_to
   ORDER BY rate_date DESC LIMIT 1;
  RETURN IFNULL(v_rate, 1.0);
END$$

CREATE FUNCTION erp_fn_customer_credit(p_customer_id INT) RETURNS DECIMAL(18,2)
READS SQL DATA
BEGIN
  DECLARE v_limit DECIMAL(18,2) DEFAULT 0;
  DECLARE v_open  DECIMAL(18,2) DEFAULT 0;
  SELECT credit_limit INTO v_limit FROM erp_customer WHERE customer_id = p_customer_id;
  SELECT IFNULL(SUM(gross_amount),0) INTO v_open FROM erp_invoice
   WHERE customer_id = p_customer_id AND status = 'OPEN';
  RETURN IFNULL(v_limit,0) - v_open;
END$$

CREATE FUNCTION erp_fn_available_qty(p_product_id INT, p_warehouse_id INT) RETURNS DECIMAL(18,4)
READS SQL DATA
BEGIN
  DECLARE v_qty DECIMAL(18,4) DEFAULT 0;
  SELECT IFNULL(SUM(qty_on_hand - qty_reserved),0) INTO v_qty
    FROM erp_stock_level WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id;
  RETURN v_qty;
END$$

CREATE FUNCTION erp_fn_next_docnum(p_doc_type VARCHAR(20)) RETURNS BIGINT
MODIFIES SQL DATA
BEGIN
  DECLARE v_next BIGINT;
  UPDATE erp_docnum SET last_number = last_number + 1 WHERE doc_type = p_doc_type;
  SELECT last_number INTO v_next FROM erp_docnum WHERE doc_type = p_doc_type;
  RETURN IFNULL(v_next, 1);
END$$

CREATE FUNCTION erp_fn_margin(p_price DECIMAL(18,4), p_cost DECIMAL(18,4)) RETURNS DECIMAL(18,4)
DETERMINISTIC
BEGIN
  IF IFNULL(p_price,0) = 0 THEN
    RETURN 0;
  END IF;
  RETURN ROUND((p_price - IFNULL(p_cost,0)) / p_price, 4);
END$$

CREATE FUNCTION erp_fn_json_tag(p_product_id INT) RETURNS VARCHAR(60)
READS SQL DATA
BEGIN
  DECLARE v_tag VARCHAR(60);
  SELECT JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag')) INTO v_tag
    FROM erp_product WHERE product_id = p_product_id LIMIT 1;
  RETURN IFNULL(v_tag, 'none');
END$$

-- ============================================================================
-- PROCEDURES  (deep call chain + full feature-matrix padding blocks)
-- ============================================================================
-- ---------------------------------------------------------------- erp_usp_audit_log  [procedure]
CREATE PROCEDURE erp_usp_audit_log(IN p_entity VARCHAR(60), IN p_entity_id INT, IN p_action VARCHAR(30), IN p_detail VARCHAR(400))
BEGIN
  INSERT INTO erp_audit_log (entity, entity_id, action, detail)
  VALUES (p_entity, p_entity_id, p_action, p_detail);
END$$

-- ---------------------------------------------------------------- erp_usp_post_gl  [procedure]
CREATE PROCEDURE erp_usp_post_gl(IN p_journal_id INT, IN p_amount DECIMAL(18,2))
BEGIN
  DECLARE v_seq INT DEFAULT 0;
  INSERT INTO erp_gl_entry (gl_journal_id, gl_account_id, debit, credit, memo)
  VALUES (p_journal_id, 4000, p_amount, 0, CONCAT('post ', CAST(p_amount AS CHAR))),
         (p_journal_id, 2000, 0, p_amount, CONCAT('post ', CAST(p_amount AS CHAR)));
  SELECT ROW_COUNT() INTO v_seq;
  CALL erp_usp_audit_log('GL', p_journal_id, 'POST', CONCAT('lines ', CAST(v_seq AS CHAR)));

  -- cte block 301: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_301 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_301 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_301 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_301 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 302: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_302 VARCHAR(10);
    DECLARE v_amt_302 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_302 FROM erp_order;
    SET v_band_302 = CASE
        WHEN v_amt_302 >= 10000 THEN 'HIGH'
        WHEN v_amt_302 >= 1000  THEN 'MED'
        WHEN v_amt_302 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_302, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 303: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_303 INT DEFAULT 0;
    DECLARE v_j_303 INT DEFAULT 0;
    DECLARE v_rc_303 INT DEFAULT 0;
    REPEAT
      SET v_i_303 = v_i_303 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R303'), v_i_303)
        ON DUPLICATE KEY UPDATE tick = v_i_303;
    UNTIL v_i_303 >= 3 END REPEAT;
    WHILE v_j_303 < 3 DO
      SET v_j_303 = v_j_303 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_303 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_303 + v_j_303, 'ITER',
            CONCAT('i ', CAST(v_i_303 AS CHAR), ' j ', CAST(v_j_303 AS CHAR),
                   ' diag ', CAST(v_rc_303 AS CHAR)));
  END;

  -- analytics block 304: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_304 INT DEFAULT 0;
    DECLARE v_amt_304 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_304 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_304 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_304, v_amt_304, v_avg_304, v_max_304
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_304 = v_amt_304 + erp_fn_tax_amount(v_amt_304, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_304, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_304 AS CHAR), ' avg ', CAST(v_avg_304 AS CHAR),
                   ' max ', CAST(v_max_304 AS CHAR)));
  END;

  -- reconcile block 305: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_305 INT DEFAULT 0;
    DECLARE v_pid_305 INT;
    DECLARE v_oh_305 DECIMAL(18,4);
    DECLARE v_av_305 DECIMAL(18,4);
    DECLARE cur_305 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_305 = 1;
    OPEN cur_305;
    rl_305: LOOP
      FETCH cur_305 INTO v_pid_305, v_oh_305;
      IF v_fin_305 = 1 THEN LEAVE rl_305; END IF;
      SET v_av_305 = erp_fn_available_qty(v_pid_305, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_305, 1, 'RECON', CAST(v_oh_305 - v_av_305 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_305 AS CHAR));
    END LOOP;
    CLOSE cur_305;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_305,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_305,0) AS CHAR)));
  END;

  -- dynamic-sql block 306: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_306 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_306 VARCHAR(64) DEFAULT 'status';
    SET @dsql_306 = CONCAT('SELECT COUNT(*) INTO @dcnt_306 FROM ', v_tbl_306,
                          ' WHERE ', v_col_306, ' = ?');
    SET @dparm_306 = 'NEW';
    PREPARE pst_306 FROM @dsql_306;
    EXECUTE pst_306 USING @dparm_306;
    DEALLOCATE PREPARE pst_306;
    SET @dupd_306 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_306 = 100;
    PREPARE pud_306 FROM @dupd_306;
    EXECUTE pud_306 USING @doid_306;
    DEALLOCATE PREPARE pud_306;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_306,0), 'COUNT',
            CONCAT('tbl ', v_tbl_306, ' col ', v_col_306));
  END;

  -- recursive block 307: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_307 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_307 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_307;
  END;

  -- reprice block 308: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_308 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_308;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_308, 'UPDATE', CONCAT('rows ', CAST(v_rows_308 AS CHAR)));
  END;

  -- validation block 309: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_309 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_309
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_309 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_309, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_309 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_309, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 310: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_310 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_310 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_310 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_310 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_310 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_310 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_310 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_310 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_310 AS CHAR), ' cr ', CAST(v_cr_310 AS CHAR),
                   ' dr ', CAST(v_dr_310 AS CHAR), ' tot ', CAST(v_tot_310 AS CHAR)));
  END;

  -- invoice rollup block 311: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_311 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_311 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_311
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_311
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_311 AS CHAR), ' paid ', CAST(v_paid_311 AS CHAR)));
  END;

  -- gl reconciliation block 312: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_312 INT DEFAULT 0;
    DECLARE v_acct_312 INT;
    DECLARE v_dr_312 DECIMAL(18,2);
    DECLARE v_cr_312 DECIMAL(18,2);
    DECLARE gcur_312 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_312 = 1;
    OPEN gcur_312;
    gl_312: LOOP
      FETCH gcur_312 INTO v_acct_312, v_dr_312, v_cr_312;
      IF v_gfin_312 = 1 THEN LEAVE gl_312; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_312, 'BALANCE',
              CONCAT('net ', CAST(v_dr_312 - v_cr_312 AS CHAR)));
    END LOOP;
    CLOSE gcur_312;
  END;

  -- transaction block 313: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_313;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_313;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 313, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 314: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_314;
    CREATE TEMPORARY TABLE tmp_agg_314 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_314 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_314 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_314;
  END;

  -- upsert block 315: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_315 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_315, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_315, 'MERGE', CONCAT('stock topped for ', CAST(v_key_315 AS CHAR)));
  END;

  -- json block 316: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_316 JSON;
    DECLARE v_sku_316 VARCHAR(40);
    DECLARE v_tag_316 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_316, v_sku_316, v_tag_316
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_316,''), ' tag ', IFNULL(v_tag_316,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_316, 'tag', v_tag_316) AS CHAR)));
  END;

  -- cte block 317: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_317 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_317 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_317 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_317 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 318: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_318 VARCHAR(10);
    DECLARE v_amt_318 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_318 FROM erp_order;
    SET v_band_318 = CASE
        WHEN v_amt_318 >= 10000 THEN 'HIGH'
        WHEN v_amt_318 >= 1000  THEN 'MED'
        WHEN v_amt_318 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_318, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 319: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_319 INT DEFAULT 0;
    DECLARE v_j_319 INT DEFAULT 0;
    DECLARE v_rc_319 INT DEFAULT 0;
    REPEAT
      SET v_i_319 = v_i_319 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R319'), v_i_319)
        ON DUPLICATE KEY UPDATE tick = v_i_319;
    UNTIL v_i_319 >= 3 END REPEAT;
    WHILE v_j_319 < 3 DO
      SET v_j_319 = v_j_319 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_319 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_319 + v_j_319, 'ITER',
            CONCAT('i ', CAST(v_i_319 AS CHAR), ' j ', CAST(v_j_319 AS CHAR),
                   ' diag ', CAST(v_rc_319 AS CHAR)));
  END;

  -- analytics block 320: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_320 INT DEFAULT 0;
    DECLARE v_amt_320 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_320 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_320 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_320, v_amt_320, v_avg_320, v_max_320
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_320 = v_amt_320 + erp_fn_tax_amount(v_amt_320, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_320, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_320 AS CHAR), ' avg ', CAST(v_avg_320 AS CHAR),
                   ' max ', CAST(v_max_320 AS CHAR)));
  END;

  -- reconcile block 321: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_321 INT DEFAULT 0;
    DECLARE v_pid_321 INT;
    DECLARE v_oh_321 DECIMAL(18,4);
    DECLARE v_av_321 DECIMAL(18,4);
    DECLARE cur_321 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_321 = 1;
    OPEN cur_321;
    rl_321: LOOP
      FETCH cur_321 INTO v_pid_321, v_oh_321;
      IF v_fin_321 = 1 THEN LEAVE rl_321; END IF;
      SET v_av_321 = erp_fn_available_qty(v_pid_321, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_321, 1, 'RECON', CAST(v_oh_321 - v_av_321 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_321 AS CHAR));
    END LOOP;
    CLOSE cur_321;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_321,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_321,0) AS CHAR)));
  END;

  -- dynamic-sql block 322: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_322 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_322 VARCHAR(64) DEFAULT 'status';
    SET @dsql_322 = CONCAT('SELECT COUNT(*) INTO @dcnt_322 FROM ', v_tbl_322,
                          ' WHERE ', v_col_322, ' = ?');
    SET @dparm_322 = 'NEW';
    PREPARE pst_322 FROM @dsql_322;
    EXECUTE pst_322 USING @dparm_322;
    DEALLOCATE PREPARE pst_322;
    SET @dupd_322 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_322 = 100;
    PREPARE pud_322 FROM @dupd_322;
    EXECUTE pud_322 USING @doid_322;
    DEALLOCATE PREPARE pud_322;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_322,0), 'COUNT',
            CONCAT('tbl ', v_tbl_322, ' col ', v_col_322));
  END;

  -- recursive block 323: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_323 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_323 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_323;
  END;

  -- reprice block 324: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_324 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_324;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_324, 'UPDATE', CONCAT('rows ', CAST(v_rows_324 AS CHAR)));
  END;

  -- validation block 325: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_325 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_325
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_325 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_325, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_325 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_325, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 326: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_326 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_326 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_326 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_326 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_326 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_326 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_326 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_326 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_326 AS CHAR), ' cr ', CAST(v_cr_326 AS CHAR),
                   ' dr ', CAST(v_dr_326 AS CHAR), ' tot ', CAST(v_tot_326 AS CHAR)));
  END;

  -- invoice rollup block 327: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_327 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_327 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_327
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_327
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_327 AS CHAR), ' paid ', CAST(v_paid_327 AS CHAR)));
  END;

  -- gl reconciliation block 328: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_328 INT DEFAULT 0;
    DECLARE v_acct_328 INT;
    DECLARE v_dr_328 DECIMAL(18,2);
    DECLARE v_cr_328 DECIMAL(18,2);
    DECLARE gcur_328 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_328 = 1;
    OPEN gcur_328;
    gl_328: LOOP
      FETCH gcur_328 INTO v_acct_328, v_dr_328, v_cr_328;
      IF v_gfin_328 = 1 THEN LEAVE gl_328; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_328, 'BALANCE',
              CONCAT('net ', CAST(v_dr_328 - v_cr_328 AS CHAR)));
    END LOOP;
    CLOSE gcur_328;
  END;

  -- transaction block 329: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_329;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_329;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 329, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 330: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_330;
    CREATE TEMPORARY TABLE tmp_agg_330 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_330 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_330 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_330;
  END;

  -- upsert block 331: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_331 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_331, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_331, 'MERGE', CONCAT('stock topped for ', CAST(v_key_331 AS CHAR)));
  END;

  -- json block 332: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_332 JSON;
    DECLARE v_sku_332 VARCHAR(40);
    DECLARE v_tag_332 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_332, v_sku_332, v_tag_332
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_332,''), ' tag ', IFNULL(v_tag_332,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_332, 'tag', v_tag_332) AS CHAR)));
  END;

  -- cte block 333: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_333 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_333 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_333 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_333 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_check_credit  [procedure]
CREATE PROCEDURE erp_usp_check_credit(IN p_customer_id INT, OUT p_ok INT)
BEGIN
  DECLARE v_avail DECIMAL(18,2) DEFAULT 0;
  SET v_avail = erp_fn_customer_credit(p_customer_id);
  IF v_avail >= 0 THEN
    SET p_ok = 1;
  ELSE
    SET p_ok = 0;
  END IF;
  CALL erp_usp_audit_log('CREDIT', p_customer_id, 'CHECK', CONCAT('avail ', CAST(v_avail AS CHAR)));

  -- case block 334: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_334 VARCHAR(10);
    DECLARE v_amt_334 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_334 FROM erp_order;
    SET v_band_334 = CASE
        WHEN v_amt_334 >= 10000 THEN 'HIGH'
        WHEN v_amt_334 >= 1000  THEN 'MED'
        WHEN v_amt_334 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_334, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 335: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_335 INT DEFAULT 0;
    DECLARE v_j_335 INT DEFAULT 0;
    DECLARE v_rc_335 INT DEFAULT 0;
    REPEAT
      SET v_i_335 = v_i_335 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R335'), v_i_335)
        ON DUPLICATE KEY UPDATE tick = v_i_335;
    UNTIL v_i_335 >= 3 END REPEAT;
    WHILE v_j_335 < 3 DO
      SET v_j_335 = v_j_335 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_335 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_335 + v_j_335, 'ITER',
            CONCAT('i ', CAST(v_i_335 AS CHAR), ' j ', CAST(v_j_335 AS CHAR),
                   ' diag ', CAST(v_rc_335 AS CHAR)));
  END;

  -- analytics block 336: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_336 INT DEFAULT 0;
    DECLARE v_amt_336 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_336 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_336 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_336, v_amt_336, v_avg_336, v_max_336
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_336 = v_amt_336 + erp_fn_tax_amount(v_amt_336, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_336, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_336 AS CHAR), ' avg ', CAST(v_avg_336 AS CHAR),
                   ' max ', CAST(v_max_336 AS CHAR)));
  END;

  -- reconcile block 337: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_337 INT DEFAULT 0;
    DECLARE v_pid_337 INT;
    DECLARE v_oh_337 DECIMAL(18,4);
    DECLARE v_av_337 DECIMAL(18,4);
    DECLARE cur_337 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_337 = 1;
    OPEN cur_337;
    rl_337: LOOP
      FETCH cur_337 INTO v_pid_337, v_oh_337;
      IF v_fin_337 = 1 THEN LEAVE rl_337; END IF;
      SET v_av_337 = erp_fn_available_qty(v_pid_337, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_337, 1, 'RECON', CAST(v_oh_337 - v_av_337 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_337 AS CHAR));
    END LOOP;
    CLOSE cur_337;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_337,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_337,0) AS CHAR)));
  END;

  -- dynamic-sql block 338: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_338 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_338 VARCHAR(64) DEFAULT 'status';
    SET @dsql_338 = CONCAT('SELECT COUNT(*) INTO @dcnt_338 FROM ', v_tbl_338,
                          ' WHERE ', v_col_338, ' = ?');
    SET @dparm_338 = 'NEW';
    PREPARE pst_338 FROM @dsql_338;
    EXECUTE pst_338 USING @dparm_338;
    DEALLOCATE PREPARE pst_338;
    SET @dupd_338 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_338 = 100;
    PREPARE pud_338 FROM @dupd_338;
    EXECUTE pud_338 USING @doid_338;
    DEALLOCATE PREPARE pud_338;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_338,0), 'COUNT',
            CONCAT('tbl ', v_tbl_338, ' col ', v_col_338));
  END;

  -- recursive block 339: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_339 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_339 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_339;
  END;

  -- reprice block 340: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_340 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_340;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_340, 'UPDATE', CONCAT('rows ', CAST(v_rows_340 AS CHAR)));
  END;

  -- validation block 341: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_341 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_341
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_341 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_341, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_341 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_341, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 342: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_342 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_342 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_342 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_342 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_342 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_342 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_342 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_342 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_342 AS CHAR), ' cr ', CAST(v_cr_342 AS CHAR),
                   ' dr ', CAST(v_dr_342 AS CHAR), ' tot ', CAST(v_tot_342 AS CHAR)));
  END;

  -- invoice rollup block 343: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_343 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_343 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_343
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_343
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_343 AS CHAR), ' paid ', CAST(v_paid_343 AS CHAR)));
  END;

  -- gl reconciliation block 344: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_344 INT DEFAULT 0;
    DECLARE v_acct_344 INT;
    DECLARE v_dr_344 DECIMAL(18,2);
    DECLARE v_cr_344 DECIMAL(18,2);
    DECLARE gcur_344 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_344 = 1;
    OPEN gcur_344;
    gl_344: LOOP
      FETCH gcur_344 INTO v_acct_344, v_dr_344, v_cr_344;
      IF v_gfin_344 = 1 THEN LEAVE gl_344; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_344, 'BALANCE',
              CONCAT('net ', CAST(v_dr_344 - v_cr_344 AS CHAR)));
    END LOOP;
    CLOSE gcur_344;
  END;

  -- transaction block 345: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_345;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_345;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 345, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 346: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_346;
    CREATE TEMPORARY TABLE tmp_agg_346 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_346 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_346 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_346;
  END;

  -- upsert block 347: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_347 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_347, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_347, 'MERGE', CONCAT('stock topped for ', CAST(v_key_347 AS CHAR)));
  END;

  -- json block 348: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_348 JSON;
    DECLARE v_sku_348 VARCHAR(40);
    DECLARE v_tag_348 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_348, v_sku_348, v_tag_348
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_348,''), ' tag ', IFNULL(v_tag_348,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_348, 'tag', v_tag_348) AS CHAR)));
  END;

  -- cte block 349: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_349 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_349 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_349 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_349 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 350: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_350 VARCHAR(10);
    DECLARE v_amt_350 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_350 FROM erp_order;
    SET v_band_350 = CASE
        WHEN v_amt_350 >= 10000 THEN 'HIGH'
        WHEN v_amt_350 >= 1000  THEN 'MED'
        WHEN v_amt_350 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_350, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 351: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_351 INT DEFAULT 0;
    DECLARE v_j_351 INT DEFAULT 0;
    DECLARE v_rc_351 INT DEFAULT 0;
    REPEAT
      SET v_i_351 = v_i_351 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R351'), v_i_351)
        ON DUPLICATE KEY UPDATE tick = v_i_351;
    UNTIL v_i_351 >= 3 END REPEAT;
    WHILE v_j_351 < 3 DO
      SET v_j_351 = v_j_351 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_351 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_351 + v_j_351, 'ITER',
            CONCAT('i ', CAST(v_i_351 AS CHAR), ' j ', CAST(v_j_351 AS CHAR),
                   ' diag ', CAST(v_rc_351 AS CHAR)));
  END;

  -- analytics block 352: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_352 INT DEFAULT 0;
    DECLARE v_amt_352 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_352 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_352 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_352, v_amt_352, v_avg_352, v_max_352
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_352 = v_amt_352 + erp_fn_tax_amount(v_amt_352, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_352, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_352 AS CHAR), ' avg ', CAST(v_avg_352 AS CHAR),
                   ' max ', CAST(v_max_352 AS CHAR)));
  END;

  -- reconcile block 353: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_353 INT DEFAULT 0;
    DECLARE v_pid_353 INT;
    DECLARE v_oh_353 DECIMAL(18,4);
    DECLARE v_av_353 DECIMAL(18,4);
    DECLARE cur_353 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_353 = 1;
    OPEN cur_353;
    rl_353: LOOP
      FETCH cur_353 INTO v_pid_353, v_oh_353;
      IF v_fin_353 = 1 THEN LEAVE rl_353; END IF;
      SET v_av_353 = erp_fn_available_qty(v_pid_353, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_353, 1, 'RECON', CAST(v_oh_353 - v_av_353 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_353 AS CHAR));
    END LOOP;
    CLOSE cur_353;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_353,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_353,0) AS CHAR)));
  END;

  -- dynamic-sql block 354: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_354 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_354 VARCHAR(64) DEFAULT 'status';
    SET @dsql_354 = CONCAT('SELECT COUNT(*) INTO @dcnt_354 FROM ', v_tbl_354,
                          ' WHERE ', v_col_354, ' = ?');
    SET @dparm_354 = 'NEW';
    PREPARE pst_354 FROM @dsql_354;
    EXECUTE pst_354 USING @dparm_354;
    DEALLOCATE PREPARE pst_354;
    SET @dupd_354 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_354 = 100;
    PREPARE pud_354 FROM @dupd_354;
    EXECUTE pud_354 USING @doid_354;
    DEALLOCATE PREPARE pud_354;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_354,0), 'COUNT',
            CONCAT('tbl ', v_tbl_354, ' col ', v_col_354));
  END;

  -- recursive block 355: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_355 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_355 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_355;
  END;

  -- reprice block 356: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_356 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_356;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_356, 'UPDATE', CONCAT('rows ', CAST(v_rows_356 AS CHAR)));
  END;

  -- validation block 357: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_357 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_357
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_357 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_357, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_357 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_357, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 358: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_358 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_358 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_358 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_358 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_358 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_358 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_358 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_358 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_358 AS CHAR), ' cr ', CAST(v_cr_358 AS CHAR),
                   ' dr ', CAST(v_dr_358 AS CHAR), ' tot ', CAST(v_tot_358 AS CHAR)));
  END;

  -- invoice rollup block 359: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_359 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_359 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_359
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_359
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_359 AS CHAR), ' paid ', CAST(v_paid_359 AS CHAR)));
  END;

  -- gl reconciliation block 360: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_360 INT DEFAULT 0;
    DECLARE v_acct_360 INT;
    DECLARE v_dr_360 DECIMAL(18,2);
    DECLARE v_cr_360 DECIMAL(18,2);
    DECLARE gcur_360 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_360 = 1;
    OPEN gcur_360;
    gl_360: LOOP
      FETCH gcur_360 INTO v_acct_360, v_dr_360, v_cr_360;
      IF v_gfin_360 = 1 THEN LEAVE gl_360; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_360, 'BALANCE',
              CONCAT('net ', CAST(v_dr_360 - v_cr_360 AS CHAR)));
    END LOOP;
    CLOSE gcur_360;
  END;

  -- transaction block 361: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_361;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_361;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 361, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 362: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_362;
    CREATE TEMPORARY TABLE tmp_agg_362 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_362 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_362 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_362;
  END;

  -- upsert block 363: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_363 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_363, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_363, 'MERGE', CONCAT('stock topped for ', CAST(v_key_363 AS CHAR)));
  END;

  -- json block 364: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_364 JSON;
    DECLARE v_sku_364 VARCHAR(40);
    DECLARE v_tag_364 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_364, v_sku_364, v_tag_364
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_364,''), ' tag ', IFNULL(v_tag_364,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_364, 'tag', v_tag_364) AS CHAR)));
  END;

  -- cte block 365: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_365 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_365 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_365 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_365 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 366: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_366 VARCHAR(10);
    DECLARE v_amt_366 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_366 FROM erp_order;
    SET v_band_366 = CASE
        WHEN v_amt_366 >= 10000 THEN 'HIGH'
        WHEN v_amt_366 >= 1000  THEN 'MED'
        WHEN v_amt_366 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_366, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_ship_order  [procedure]
CREATE PROCEDURE erp_usp_ship_order(IN p_order_id INT)
BEGIN
  DECLARE v_doc BIGINT;
  SET v_doc = erp_fn_next_docnum('SHIP');
  UPDATE erp_order SET status = 'SHIPPED' WHERE order_id = p_order_id;
  INSERT INTO erp_shipment (order_id, doc_number, ship_status)
  VALUES (p_order_id, v_doc, 'SHIPPED')
  ON DUPLICATE KEY UPDATE ship_status = 'SHIPPED';
  CALL erp_usp_audit_log('SHIP', p_order_id, 'SHIP', CONCAT('doc ', CAST(v_doc AS CHAR)));

  -- repeat/while block 367: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_367 INT DEFAULT 0;
    DECLARE v_j_367 INT DEFAULT 0;
    DECLARE v_rc_367 INT DEFAULT 0;
    REPEAT
      SET v_i_367 = v_i_367 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R367'), v_i_367)
        ON DUPLICATE KEY UPDATE tick = v_i_367;
    UNTIL v_i_367 >= 3 END REPEAT;
    WHILE v_j_367 < 3 DO
      SET v_j_367 = v_j_367 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_367 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_367 + v_j_367, 'ITER',
            CONCAT('i ', CAST(v_i_367 AS CHAR), ' j ', CAST(v_j_367 AS CHAR),
                   ' diag ', CAST(v_rc_367 AS CHAR)));
  END;

  -- analytics block 368: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_368 INT DEFAULT 0;
    DECLARE v_amt_368 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_368 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_368 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_368, v_amt_368, v_avg_368, v_max_368
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_368 = v_amt_368 + erp_fn_tax_amount(v_amt_368, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_368, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_368 AS CHAR), ' avg ', CAST(v_avg_368 AS CHAR),
                   ' max ', CAST(v_max_368 AS CHAR)));
  END;

  -- reconcile block 369: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_369 INT DEFAULT 0;
    DECLARE v_pid_369 INT;
    DECLARE v_oh_369 DECIMAL(18,4);
    DECLARE v_av_369 DECIMAL(18,4);
    DECLARE cur_369 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_369 = 1;
    OPEN cur_369;
    rl_369: LOOP
      FETCH cur_369 INTO v_pid_369, v_oh_369;
      IF v_fin_369 = 1 THEN LEAVE rl_369; END IF;
      SET v_av_369 = erp_fn_available_qty(v_pid_369, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_369, 1, 'RECON', CAST(v_oh_369 - v_av_369 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_369 AS CHAR));
    END LOOP;
    CLOSE cur_369;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_369,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_369,0) AS CHAR)));
  END;

  -- dynamic-sql block 370: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_370 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_370 VARCHAR(64) DEFAULT 'status';
    SET @dsql_370 = CONCAT('SELECT COUNT(*) INTO @dcnt_370 FROM ', v_tbl_370,
                          ' WHERE ', v_col_370, ' = ?');
    SET @dparm_370 = 'NEW';
    PREPARE pst_370 FROM @dsql_370;
    EXECUTE pst_370 USING @dparm_370;
    DEALLOCATE PREPARE pst_370;
    SET @dupd_370 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_370 = 100;
    PREPARE pud_370 FROM @dupd_370;
    EXECUTE pud_370 USING @doid_370;
    DEALLOCATE PREPARE pud_370;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_370,0), 'COUNT',
            CONCAT('tbl ', v_tbl_370, ' col ', v_col_370));
  END;

  -- recursive block 371: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_371 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_371 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_371;
  END;

  -- reprice block 372: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_372 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_372;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_372, 'UPDATE', CONCAT('rows ', CAST(v_rows_372 AS CHAR)));
  END;

  -- validation block 373: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_373 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_373
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_373 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_373, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_373 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_373, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 374: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_374 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_374 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_374 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_374 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_374 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_374 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_374 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_374 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_374 AS CHAR), ' cr ', CAST(v_cr_374 AS CHAR),
                   ' dr ', CAST(v_dr_374 AS CHAR), ' tot ', CAST(v_tot_374 AS CHAR)));
  END;

  -- invoice rollup block 375: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_375 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_375 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_375
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_375
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_375 AS CHAR), ' paid ', CAST(v_paid_375 AS CHAR)));
  END;

  -- gl reconciliation block 376: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_376 INT DEFAULT 0;
    DECLARE v_acct_376 INT;
    DECLARE v_dr_376 DECIMAL(18,2);
    DECLARE v_cr_376 DECIMAL(18,2);
    DECLARE gcur_376 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_376 = 1;
    OPEN gcur_376;
    gl_376: LOOP
      FETCH gcur_376 INTO v_acct_376, v_dr_376, v_cr_376;
      IF v_gfin_376 = 1 THEN LEAVE gl_376; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_376, 'BALANCE',
              CONCAT('net ', CAST(v_dr_376 - v_cr_376 AS CHAR)));
    END LOOP;
    CLOSE gcur_376;
  END;

  -- transaction block 377: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_377;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_377;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 377, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 378: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_378;
    CREATE TEMPORARY TABLE tmp_agg_378 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_378 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_378 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_378;
  END;

  -- upsert block 379: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_379 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_379, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_379, 'MERGE', CONCAT('stock topped for ', CAST(v_key_379 AS CHAR)));
  END;

  -- json block 380: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_380 JSON;
    DECLARE v_sku_380 VARCHAR(40);
    DECLARE v_tag_380 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_380, v_sku_380, v_tag_380
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_380,''), ' tag ', IFNULL(v_tag_380,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_380, 'tag', v_tag_380) AS CHAR)));
  END;

  -- cte block 381: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_381 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_381 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_381 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_381 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 382: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_382 VARCHAR(10);
    DECLARE v_amt_382 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_382 FROM erp_order;
    SET v_band_382 = CASE
        WHEN v_amt_382 >= 10000 THEN 'HIGH'
        WHEN v_amt_382 >= 1000  THEN 'MED'
        WHEN v_amt_382 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_382, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 383: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_383 INT DEFAULT 0;
    DECLARE v_j_383 INT DEFAULT 0;
    DECLARE v_rc_383 INT DEFAULT 0;
    REPEAT
      SET v_i_383 = v_i_383 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R383'), v_i_383)
        ON DUPLICATE KEY UPDATE tick = v_i_383;
    UNTIL v_i_383 >= 3 END REPEAT;
    WHILE v_j_383 < 3 DO
      SET v_j_383 = v_j_383 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_383 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_383 + v_j_383, 'ITER',
            CONCAT('i ', CAST(v_i_383 AS CHAR), ' j ', CAST(v_j_383 AS CHAR),
                   ' diag ', CAST(v_rc_383 AS CHAR)));
  END;

