      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_391
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_391 AS CHAR), ' paid ', CAST(v_paid_391 AS CHAR)));
  END;

  -- gl reconciliation block 392: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_392 INT DEFAULT 0;
    DECLARE v_acct_392 INT;
    DECLARE v_dr_392 DECIMAL(18,2);
    DECLARE v_cr_392 DECIMAL(18,2);
    DECLARE gcur_392 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_392 = 1;
    OPEN gcur_392;
    gl_392: LOOP
      FETCH gcur_392 INTO v_acct_392, v_dr_392, v_cr_392;
      IF v_gfin_392 = 1 THEN LEAVE gl_392; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_392, 'BALANCE',
              CONCAT('net ', CAST(v_dr_392 - v_cr_392 AS CHAR)));
    END LOOP;
    CLOSE gcur_392;
  END;

  -- transaction block 393: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_393;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_393;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 393, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 394: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_394;
    CREATE TEMPORARY TABLE tmp_agg_394 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_394 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_394 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_394;
  END;

  -- upsert block 395: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_395 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_395, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_395, 'MERGE', CONCAT('stock topped for ', CAST(v_key_395 AS CHAR)));
  END;

  -- json block 396: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_396 JSON;
    DECLARE v_sku_396 VARCHAR(40);
    DECLARE v_tag_396 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_396, v_sku_396, v_tag_396
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_396,''), ' tag ', IFNULL(v_tag_396,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_396, 'tag', v_tag_396) AS CHAR)));
  END;

  -- cte block 397: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_397 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_397 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_397 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_397 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 398: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_398 VARCHAR(10);
    DECLARE v_amt_398 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_398 FROM erp_order;
    SET v_band_398 = CASE
        WHEN v_amt_398 >= 10000 THEN 'HIGH'
        WHEN v_amt_398 >= 1000  THEN 'MED'
        WHEN v_amt_398 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_398, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 399: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_399 INT DEFAULT 0;
    DECLARE v_j_399 INT DEFAULT 0;
    DECLARE v_rc_399 INT DEFAULT 0;
    REPEAT
      SET v_i_399 = v_i_399 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R399'), v_i_399)
        ON DUPLICATE KEY UPDATE tick = v_i_399;
    UNTIL v_i_399 >= 3 END REPEAT;
    WHILE v_j_399 < 3 DO
      SET v_j_399 = v_j_399 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_399 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_399 + v_j_399, 'ITER',
            CONCAT('i ', CAST(v_i_399 AS CHAR), ' j ', CAST(v_j_399 AS CHAR),
                   ' diag ', CAST(v_rc_399 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_revalue_currency  [procedure]
CREATE PROCEDURE erp_usp_revalue_currency(IN p_ccy CHAR(3))
BEGIN
  DECLARE v_rate DECIMAL(18,8) DEFAULT 1;
  DECLARE v_jid INT DEFAULT 9100;
  SET v_rate = erp_fn_fx_rate(p_ccy, 'USD');
  UPDATE erp_invoice SET net_amount = ROUND(gross_amount * v_rate, 2)
   WHERE currency = p_ccy;
  CALL erp_usp_post_gl(v_jid, 0);
  CALL erp_usp_audit_log('FX', v_jid, 'REVALUE', CONCAT('ccy ', p_ccy, ' rate ', CAST(v_rate AS CHAR)));

  -- analytics block 400: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_400 INT DEFAULT 0;
    DECLARE v_amt_400 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_400 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_400 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_400, v_amt_400, v_avg_400, v_max_400
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_400 = v_amt_400 + erp_fn_tax_amount(v_amt_400, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_400, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_400 AS CHAR), ' avg ', CAST(v_avg_400 AS CHAR),
                   ' max ', CAST(v_max_400 AS CHAR)));
  END;

  -- reconcile block 401: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_401 INT DEFAULT 0;
    DECLARE v_pid_401 INT;
    DECLARE v_oh_401 DECIMAL(18,4);
    DECLARE v_av_401 DECIMAL(18,4);
    DECLARE cur_401 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_401 = 1;
    OPEN cur_401;
    rl_401: LOOP
      FETCH cur_401 INTO v_pid_401, v_oh_401;
      IF v_fin_401 = 1 THEN LEAVE rl_401; END IF;
      SET v_av_401 = erp_fn_available_qty(v_pid_401, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_401, 1, 'RECON', CAST(v_oh_401 - v_av_401 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_401 AS CHAR));
    END LOOP;
    CLOSE cur_401;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_401,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_401,0) AS CHAR)));
  END;

  -- dynamic-sql block 402: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_402 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_402 VARCHAR(64) DEFAULT 'status';
    SET @dsql_402 = CONCAT('SELECT COUNT(*) INTO @dcnt_402 FROM ', v_tbl_402,
                          ' WHERE ', v_col_402, ' = ?');
    SET @dparm_402 = 'NEW';
    PREPARE pst_402 FROM @dsql_402;
    EXECUTE pst_402 USING @dparm_402;
    DEALLOCATE PREPARE pst_402;
    SET @dupd_402 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_402 = 100;
    PREPARE pud_402 FROM @dupd_402;
    EXECUTE pud_402 USING @doid_402;
    DEALLOCATE PREPARE pud_402;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_402,0), 'COUNT',
            CONCAT('tbl ', v_tbl_402, ' col ', v_col_402));
  END;

  -- recursive block 403: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_403 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_403 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_403;
  END;

  -- reprice block 404: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_404 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_404;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_404, 'UPDATE', CONCAT('rows ', CAST(v_rows_404 AS CHAR)));
  END;

  -- validation block 405: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_405 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_405
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_405 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_405, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_405 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_405, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 406: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_406 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_406 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_406 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_406 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_406 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_406 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_406 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_406 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_406 AS CHAR), ' cr ', CAST(v_cr_406 AS CHAR),
                   ' dr ', CAST(v_dr_406 AS CHAR), ' tot ', CAST(v_tot_406 AS CHAR)));
  END;

  -- invoice rollup block 407: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_407 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_407 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_407
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_407
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_407 AS CHAR), ' paid ', CAST(v_paid_407 AS CHAR)));
  END;

  -- gl reconciliation block 408: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_408 INT DEFAULT 0;
    DECLARE v_acct_408 INT;
    DECLARE v_dr_408 DECIMAL(18,2);
    DECLARE v_cr_408 DECIMAL(18,2);
    DECLARE gcur_408 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_408 = 1;
    OPEN gcur_408;
    gl_408: LOOP
      FETCH gcur_408 INTO v_acct_408, v_dr_408, v_cr_408;
      IF v_gfin_408 = 1 THEN LEAVE gl_408; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_408, 'BALANCE',
              CONCAT('net ', CAST(v_dr_408 - v_cr_408 AS CHAR)));
    END LOOP;
    CLOSE gcur_408;
  END;

  -- transaction block 409: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_409;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_409;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 409, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 410: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_410;
    CREATE TEMPORARY TABLE tmp_agg_410 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_410 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_410 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_410;
  END;

  -- upsert block 411: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_411 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_411, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_411, 'MERGE', CONCAT('stock topped for ', CAST(v_key_411 AS CHAR)));
  END;

  -- json block 412: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_412 JSON;
    DECLARE v_sku_412 VARCHAR(40);
    DECLARE v_tag_412 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_412, v_sku_412, v_tag_412
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_412,''), ' tag ', IFNULL(v_tag_412,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_412, 'tag', v_tag_412) AS CHAR)));
  END;

  -- cte block 413: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_413 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_413 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_413 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_413 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 414: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_414 VARCHAR(10);
    DECLARE v_amt_414 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_414 FROM erp_order;
    SET v_band_414 = CASE
        WHEN v_amt_414 >= 10000 THEN 'HIGH'
        WHEN v_amt_414 >= 1000  THEN 'MED'
        WHEN v_amt_414 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_414, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 415: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_415 INT DEFAULT 0;
    DECLARE v_j_415 INT DEFAULT 0;
    DECLARE v_rc_415 INT DEFAULT 0;
    REPEAT
      SET v_i_415 = v_i_415 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R415'), v_i_415)
        ON DUPLICATE KEY UPDATE tick = v_i_415;
    UNTIL v_i_415 >= 3 END REPEAT;
    WHILE v_j_415 < 3 DO
      SET v_j_415 = v_j_415 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_415 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_415 + v_j_415, 'ITER',
            CONCAT('i ', CAST(v_i_415 AS CHAR), ' j ', CAST(v_j_415 AS CHAR),
                   ' diag ', CAST(v_rc_415 AS CHAR)));
  END;

  -- analytics block 416: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_416 INT DEFAULT 0;
    DECLARE v_amt_416 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_416 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_416 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_416, v_amt_416, v_avg_416, v_max_416
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_416 = v_amt_416 + erp_fn_tax_amount(v_amt_416, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_416, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_416 AS CHAR), ' avg ', CAST(v_avg_416 AS CHAR),
                   ' max ', CAST(v_max_416 AS CHAR)));
  END;

  -- reconcile block 417: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_417 INT DEFAULT 0;
    DECLARE v_pid_417 INT;
    DECLARE v_oh_417 DECIMAL(18,4);
    DECLARE v_av_417 DECIMAL(18,4);
    DECLARE cur_417 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_417 = 1;
    OPEN cur_417;
    rl_417: LOOP
      FETCH cur_417 INTO v_pid_417, v_oh_417;
      IF v_fin_417 = 1 THEN LEAVE rl_417; END IF;
      SET v_av_417 = erp_fn_available_qty(v_pid_417, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_417, 1, 'RECON', CAST(v_oh_417 - v_av_417 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_417 AS CHAR));
    END LOOP;
    CLOSE cur_417;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_417,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_417,0) AS CHAR)));
  END;

  -- dynamic-sql block 418: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_418 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_418 VARCHAR(64) DEFAULT 'status';
    SET @dsql_418 = CONCAT('SELECT COUNT(*) INTO @dcnt_418 FROM ', v_tbl_418,
                          ' WHERE ', v_col_418, ' = ?');
    SET @dparm_418 = 'NEW';
    PREPARE pst_418 FROM @dsql_418;
    EXECUTE pst_418 USING @dparm_418;
    DEALLOCATE PREPARE pst_418;
    SET @dupd_418 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_418 = 100;
    PREPARE pud_418 FROM @dupd_418;
    EXECUTE pud_418 USING @doid_418;
    DEALLOCATE PREPARE pud_418;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_418,0), 'COUNT',
            CONCAT('tbl ', v_tbl_418, ' col ', v_col_418));
  END;

  -- recursive block 419: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_419 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_419 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_419;
  END;

  -- reprice block 420: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_420 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_420;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_420, 'UPDATE', CONCAT('rows ', CAST(v_rows_420 AS CHAR)));
  END;

  -- validation block 421: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_421 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_421
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_421 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_421, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_421 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_421, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 422: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_422 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_422 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_422 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_422 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_422 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_422 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_422 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_422 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_422 AS CHAR), ' cr ', CAST(v_cr_422 AS CHAR),
                   ' dr ', CAST(v_dr_422 AS CHAR), ' tot ', CAST(v_tot_422 AS CHAR)));
  END;

  -- invoice rollup block 423: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_423 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_423 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_423
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_423
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_423 AS CHAR), ' paid ', CAST(v_paid_423 AS CHAR)));
  END;

  -- gl reconciliation block 424: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_424 INT DEFAULT 0;
    DECLARE v_acct_424 INT;
    DECLARE v_dr_424 DECIMAL(18,2);
    DECLARE v_cr_424 DECIMAL(18,2);
    DECLARE gcur_424 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_424 = 1;
    OPEN gcur_424;
    gl_424: LOOP
      FETCH gcur_424 INTO v_acct_424, v_dr_424, v_cr_424;
      IF v_gfin_424 = 1 THEN LEAVE gl_424; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_424, 'BALANCE',
              CONCAT('net ', CAST(v_dr_424 - v_cr_424 AS CHAR)));
    END LOOP;
    CLOSE gcur_424;
  END;

  -- transaction block 425: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_425;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_425;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 425, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 426: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_426;
    CREATE TEMPORARY TABLE tmp_agg_426 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_426 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_426 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_426;
  END;

  -- upsert block 427: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_427 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_427, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_427, 'MERGE', CONCAT('stock topped for ', CAST(v_key_427 AS CHAR)));
  END;

  -- json block 428: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_428 JSON;
    DECLARE v_sku_428 VARCHAR(40);
    DECLARE v_tag_428 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_428, v_sku_428, v_tag_428
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_428,''), ' tag ', IFNULL(v_tag_428,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_428, 'tag', v_tag_428) AS CHAR)));
  END;

  -- cte block 429: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_429 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_429 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_429 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_429 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 430: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_430 VARCHAR(10);
    DECLARE v_amt_430 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_430 FROM erp_order;
    SET v_band_430 = CASE
        WHEN v_amt_430 >= 10000 THEN 'HIGH'
        WHEN v_amt_430 >= 1000  THEN 'MED'
        WHEN v_amt_430 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_430, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 431: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_431 INT DEFAULT 0;
    DECLARE v_j_431 INT DEFAULT 0;
    DECLARE v_rc_431 INT DEFAULT 0;
    REPEAT
      SET v_i_431 = v_i_431 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R431'), v_i_431)
        ON DUPLICATE KEY UPDATE tick = v_i_431;
    UNTIL v_i_431 >= 3 END REPEAT;
    WHILE v_j_431 < 3 DO
      SET v_j_431 = v_j_431 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_431 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_431 + v_j_431, 'ITER',
            CONCAT('i ', CAST(v_i_431 AS CHAR), ' j ', CAST(v_j_431 AS CHAR),
                   ' diag ', CAST(v_rc_431 AS CHAR)));
  END;

  -- analytics block 432: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_432 INT DEFAULT 0;
    DECLARE v_amt_432 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_432 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_432 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_432, v_amt_432, v_avg_432, v_max_432
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_432 = v_amt_432 + erp_fn_tax_amount(v_amt_432, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_432, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_432 AS CHAR), ' avg ', CAST(v_avg_432 AS CHAR),
                   ' max ', CAST(v_max_432 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_reconcile_account  [procedure]
CREATE PROCEDURE erp_usp_reconcile_account(IN p_account_id INT)
BEGIN
  DECLARE v_net DECIMAL(18,2) DEFAULT 0;
  SELECT IFNULL(SUM(debit),0) - IFNULL(SUM(credit),0) INTO v_net
    FROM erp_gl_entry WHERE gl_account_id = p_account_id;
  CALL erp_usp_revalue_currency('EUR');
  CALL erp_usp_audit_log('RECON', p_account_id, 'ACCOUNT', CONCAT('net ', CAST(v_net AS CHAR)));

  -- reconcile block 433: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_433 INT DEFAULT 0;
    DECLARE v_pid_433 INT;
    DECLARE v_oh_433 DECIMAL(18,4);
    DECLARE v_av_433 DECIMAL(18,4);
    DECLARE cur_433 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_433 = 1;
    OPEN cur_433;
    rl_433: LOOP
      FETCH cur_433 INTO v_pid_433, v_oh_433;
      IF v_fin_433 = 1 THEN LEAVE rl_433; END IF;
      SET v_av_433 = erp_fn_available_qty(v_pid_433, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_433, 1, 'RECON', CAST(v_oh_433 - v_av_433 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_433 AS CHAR));
    END LOOP;
    CLOSE cur_433;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_433,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_433,0) AS CHAR)));
  END;

  -- dynamic-sql block 434: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_434 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_434 VARCHAR(64) DEFAULT 'status';
    SET @dsql_434 = CONCAT('SELECT COUNT(*) INTO @dcnt_434 FROM ', v_tbl_434,
                          ' WHERE ', v_col_434, ' = ?');
    SET @dparm_434 = 'NEW';
    PREPARE pst_434 FROM @dsql_434;
    EXECUTE pst_434 USING @dparm_434;
    DEALLOCATE PREPARE pst_434;
    SET @dupd_434 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_434 = 100;
    PREPARE pud_434 FROM @dupd_434;
    EXECUTE pud_434 USING @doid_434;
    DEALLOCATE PREPARE pud_434;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_434,0), 'COUNT',
            CONCAT('tbl ', v_tbl_434, ' col ', v_col_434));
  END;

  -- recursive block 435: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_435 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_435 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_435;
  END;

  -- reprice block 436: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_436 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_436;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_436, 'UPDATE', CONCAT('rows ', CAST(v_rows_436 AS CHAR)));
  END;

  -- validation block 437: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_437 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_437
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_437 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_437, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_437 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_437, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 438: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_438 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_438 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_438 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_438 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_438 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_438 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_438 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_438 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_438 AS CHAR), ' cr ', CAST(v_cr_438 AS CHAR),
                   ' dr ', CAST(v_dr_438 AS CHAR), ' tot ', CAST(v_tot_438 AS CHAR)));
  END;

  -- invoice rollup block 439: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_439 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_439 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_439
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_439
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_439 AS CHAR), ' paid ', CAST(v_paid_439 AS CHAR)));
  END;

  -- gl reconciliation block 440: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_440 INT DEFAULT 0;
    DECLARE v_acct_440 INT;
    DECLARE v_dr_440 DECIMAL(18,2);
    DECLARE v_cr_440 DECIMAL(18,2);
    DECLARE gcur_440 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_440 = 1;
    OPEN gcur_440;
    gl_440: LOOP
      FETCH gcur_440 INTO v_acct_440, v_dr_440, v_cr_440;
      IF v_gfin_440 = 1 THEN LEAVE gl_440; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_440, 'BALANCE',
              CONCAT('net ', CAST(v_dr_440 - v_cr_440 AS CHAR)));
    END LOOP;
    CLOSE gcur_440;
  END;

  -- transaction block 441: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_441;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_441;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 441, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 442: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_442;
    CREATE TEMPORARY TABLE tmp_agg_442 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_442 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_442 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_442;
  END;

  -- upsert block 443: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_443 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_443, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_443, 'MERGE', CONCAT('stock topped for ', CAST(v_key_443 AS CHAR)));
  END;

  -- json block 444: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_444 JSON;
    DECLARE v_sku_444 VARCHAR(40);
    DECLARE v_tag_444 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_444, v_sku_444, v_tag_444
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_444,''), ' tag ', IFNULL(v_tag_444,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_444, 'tag', v_tag_444) AS CHAR)));
  END;

  -- cte block 445: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_445 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_445 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_445 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_445 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 446: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_446 VARCHAR(10);
    DECLARE v_amt_446 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_446 FROM erp_order;
    SET v_band_446 = CASE
        WHEN v_amt_446 >= 10000 THEN 'HIGH'
        WHEN v_amt_446 >= 1000  THEN 'MED'
        WHEN v_amt_446 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_446, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 447: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_447 INT DEFAULT 0;
    DECLARE v_j_447 INT DEFAULT 0;
    DECLARE v_rc_447 INT DEFAULT 0;
    REPEAT
      SET v_i_447 = v_i_447 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R447'), v_i_447)
        ON DUPLICATE KEY UPDATE tick = v_i_447;
    UNTIL v_i_447 >= 3 END REPEAT;
    WHILE v_j_447 < 3 DO
      SET v_j_447 = v_j_447 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_447 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_447 + v_j_447, 'ITER',
            CONCAT('i ', CAST(v_i_447 AS CHAR), ' j ', CAST(v_j_447 AS CHAR),
                   ' diag ', CAST(v_rc_447 AS CHAR)));
  END;

  -- analytics block 448: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_448 INT DEFAULT 0;
    DECLARE v_amt_448 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_448 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_448 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_448, v_amt_448, v_avg_448, v_max_448
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_448 = v_amt_448 + erp_fn_tax_amount(v_amt_448, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_448, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_448 AS CHAR), ' avg ', CAST(v_avg_448 AS CHAR),
                   ' max ', CAST(v_max_448 AS CHAR)));
  END;

  -- reconcile block 449: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_449 INT DEFAULT 0;
    DECLARE v_pid_449 INT;
    DECLARE v_oh_449 DECIMAL(18,4);
    DECLARE v_av_449 DECIMAL(18,4);
    DECLARE cur_449 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_449 = 1;
    OPEN cur_449;
    rl_449: LOOP
      FETCH cur_449 INTO v_pid_449, v_oh_449;
      IF v_fin_449 = 1 THEN LEAVE rl_449; END IF;
      SET v_av_449 = erp_fn_available_qty(v_pid_449, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_449, 1, 'RECON', CAST(v_oh_449 - v_av_449 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_449 AS CHAR));
    END LOOP;
    CLOSE cur_449;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_449,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_449,0) AS CHAR)));
  END;

  -- dynamic-sql block 450: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_450 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_450 VARCHAR(64) DEFAULT 'status';
    SET @dsql_450 = CONCAT('SELECT COUNT(*) INTO @dcnt_450 FROM ', v_tbl_450,
                          ' WHERE ', v_col_450, ' = ?');
    SET @dparm_450 = 'NEW';
    PREPARE pst_450 FROM @dsql_450;
    EXECUTE pst_450 USING @dparm_450;
    DEALLOCATE PREPARE pst_450;
    SET @dupd_450 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_450 = 100;
    PREPARE pud_450 FROM @dupd_450;
    EXECUTE pud_450 USING @doid_450;
    DEALLOCATE PREPARE pud_450;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_450,0), 'COUNT',
            CONCAT('tbl ', v_tbl_450, ' col ', v_col_450));
  END;

  -- recursive block 451: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_451 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_451 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_451;
  END;

  -- reprice block 452: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_452 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_452;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_452, 'UPDATE', CONCAT('rows ', CAST(v_rows_452 AS CHAR)));
  END;

  -- validation block 453: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_453 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_453
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_453 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_453, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_453 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_453, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 454: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_454 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_454 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_454 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_454 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_454 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_454 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_454 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_454 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_454 AS CHAR), ' cr ', CAST(v_cr_454 AS CHAR),
                   ' dr ', CAST(v_dr_454 AS CHAR), ' tot ', CAST(v_tot_454 AS CHAR)));
  END;

  -- invoice rollup block 455: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_455 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_455 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_455
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_455
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_455 AS CHAR), ' paid ', CAST(v_paid_455 AS CHAR)));
  END;

  -- gl reconciliation block 456: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_456 INT DEFAULT 0;
    DECLARE v_acct_456 INT;
    DECLARE v_dr_456 DECIMAL(18,2);
    DECLARE v_cr_456 DECIMAL(18,2);
    DECLARE gcur_456 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_456 = 1;
    OPEN gcur_456;
    gl_456: LOOP
      FETCH gcur_456 INTO v_acct_456, v_dr_456, v_cr_456;
      IF v_gfin_456 = 1 THEN LEAVE gl_456; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_456, 'BALANCE',
              CONCAT('net ', CAST(v_dr_456 - v_cr_456 AS CHAR)));
    END LOOP;
    CLOSE gcur_456;
  END;

