  -- temp-table block 458: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_458;
    CREATE TEMPORARY TABLE tmp_agg_458 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
