  -- analytics block 464: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_464 INT DEFAULT 0;
    DECLARE v_amt_464 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_464 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_464 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_464, v_amt_464, v_avg_464, v_max_464
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_464 = v_amt_464 + erp_fn_tax_amount(v_amt_464, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_464, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_464 AS CHAR), ' avg ', CAST(v_avg_464 AS CHAR),
                   ' max ', CAST(v_max_464 AS CHAR)));
  END;

  -- reconcile block 465: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_465 INT DEFAULT 0;
    DECLARE v_pid_465 INT;
    DECLARE v_oh_465 DECIMAL(18,4);
    DECLARE v_av_465 DECIMAL(18,4);
    DECLARE cur_465 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_465 = 1;
    OPEN cur_465;
    rl_465: LOOP
      FETCH cur_465 INTO v_pid_465, v_oh_465;
      IF v_fin_465 = 1 THEN LEAVE rl_465; END IF;
      SET v_av_465 = erp_fn_available_qty(v_pid_465, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_465, 1, 'RECON', CAST(v_oh_465 - v_av_465 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_465 AS CHAR));
    END LOOP;
    CLOSE cur_465;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_465,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_465,0) AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_update_ledger  [procedure]
CREATE PROCEDURE erp_usp_update_ledger(IN p_journal_id INT)
BEGIN
  DECLARE v_amt DECIMAL(18,2) DEFAULT 0;
  SELECT IFNULL(SUM(debit),0) INTO v_amt FROM erp_gl_entry WHERE gl_journal_id = p_journal_id;
  UPDATE erp_gl_journal SET posted = 1 WHERE gl_journal_id = p_journal_id;
  CALL erp_usp_post_gl(p_journal_id, v_amt);
  CALL erp_usp_reconcile_account(4000);
  CALL erp_usp_audit_log('LEDGER', p_journal_id, 'UPDATE', CONCAT('amt ', CAST(v_amt AS CHAR)));

  -- dynamic-sql block 466: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_466 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_466 VARCHAR(64) DEFAULT 'status';
    SET @dsql_466 = CONCAT('SELECT COUNT(*) INTO @dcnt_466 FROM ', v_tbl_466,
                          ' WHERE ', v_col_466, ' = ?');
    SET @dparm_466 = 'NEW';
    PREPARE pst_466 FROM @dsql_466;
    EXECUTE pst_466 USING @dparm_466;
    DEALLOCATE PREPARE pst_466;
    SET @dupd_466 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_466 = 100;
    PREPARE pud_466 FROM @dupd_466;
    EXECUTE pud_466 USING @doid_466;
    DEALLOCATE PREPARE pud_466;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_466,0), 'COUNT',
            CONCAT('tbl ', v_tbl_466, ' col ', v_col_466));
  END;

  -- recursive block 467: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_467 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_467 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_467;
  END;

  -- reprice block 468: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_468 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_468;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_468, 'UPDATE', CONCAT('rows ', CAST(v_rows_468 AS CHAR)));
  END;

  -- validation block 469: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_469 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_469
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_469 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_469, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_469 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_469, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 470: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_470 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_470 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_470 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_470 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_470 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_470 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_470 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_470 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_470 AS CHAR), ' cr ', CAST(v_cr_470 AS CHAR),
                   ' dr ', CAST(v_dr_470 AS CHAR), ' tot ', CAST(v_tot_470 AS CHAR)));
  END;

  -- invoice rollup block 471: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_471 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_471 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_471
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_471
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_471 AS CHAR), ' paid ', CAST(v_paid_471 AS CHAR)));
  END;

  -- gl reconciliation block 472: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_472 INT DEFAULT 0;
    DECLARE v_acct_472 INT;
    DECLARE v_dr_472 DECIMAL(18,2);
    DECLARE v_cr_472 DECIMAL(18,2);
    DECLARE gcur_472 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_472 = 1;
    OPEN gcur_472;
    gl_472: LOOP
      FETCH gcur_472 INTO v_acct_472, v_dr_472, v_cr_472;
      IF v_gfin_472 = 1 THEN LEAVE gl_472; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_472, 'BALANCE',
              CONCAT('net ', CAST(v_dr_472 - v_cr_472 AS CHAR)));
    END LOOP;
    CLOSE gcur_472;
  END;

  -- transaction block 473: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_473;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_473;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 473, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 474: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_474;
    CREATE TEMPORARY TABLE tmp_agg_474 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_474 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_474 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_474;
  END;

  -- upsert block 475: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_475 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_475, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_475, 'MERGE', CONCAT('stock topped for ', CAST(v_key_475 AS CHAR)));
  END;

  -- json block 476: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_476 JSON;
    DECLARE v_sku_476 VARCHAR(40);
    DECLARE v_tag_476 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_476, v_sku_476, v_tag_476
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_476,''), ' tag ', IFNULL(v_tag_476,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_476, 'tag', v_tag_476) AS CHAR)));
  END;

  -- cte block 477: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_477 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_477 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_477 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_477 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 478: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_478 VARCHAR(10);
    DECLARE v_amt_478 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_478 FROM erp_order;
    SET v_band_478 = CASE
        WHEN v_amt_478 >= 10000 THEN 'HIGH'
        WHEN v_amt_478 >= 1000  THEN 'MED'
        WHEN v_amt_478 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_478, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 479: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_479 INT DEFAULT 0;
    DECLARE v_j_479 INT DEFAULT 0;
    DECLARE v_rc_479 INT DEFAULT 0;
    REPEAT
      SET v_i_479 = v_i_479 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R479'), v_i_479)
        ON DUPLICATE KEY UPDATE tick = v_i_479;
    UNTIL v_i_479 >= 3 END REPEAT;
    WHILE v_j_479 < 3 DO
      SET v_j_479 = v_j_479 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_479 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_479 + v_j_479, 'ITER',
            CONCAT('i ', CAST(v_i_479 AS CHAR), ' j ', CAST(v_j_479 AS CHAR),
                   ' diag ', CAST(v_rc_479 AS CHAR)));
  END;

  -- analytics block 480: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_480 INT DEFAULT 0;
    DECLARE v_amt_480 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_480 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_480 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_480, v_amt_480, v_avg_480, v_max_480
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_480 = v_amt_480 + erp_fn_tax_amount(v_amt_480, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_480, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_480 AS CHAR), ' avg ', CAST(v_avg_480 AS CHAR),
                   ' max ', CAST(v_max_480 AS CHAR)));
  END;

  -- reconcile block 481: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_481 INT DEFAULT 0;
    DECLARE v_pid_481 INT;
    DECLARE v_oh_481 DECIMAL(18,4);
    DECLARE v_av_481 DECIMAL(18,4);
    DECLARE cur_481 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_481 = 1;
    OPEN cur_481;
    rl_481: LOOP
      FETCH cur_481 INTO v_pid_481, v_oh_481;
      IF v_fin_481 = 1 THEN LEAVE rl_481; END IF;
      SET v_av_481 = erp_fn_available_qty(v_pid_481, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_481, 1, 'RECON', CAST(v_oh_481 - v_av_481 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_481 AS CHAR));
    END LOOP;
    CLOSE cur_481;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_481,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_481,0) AS CHAR)));
  END;

  -- dynamic-sql block 482: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_482 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_482 VARCHAR(64) DEFAULT 'status';
    SET @dsql_482 = CONCAT('SELECT COUNT(*) INTO @dcnt_482 FROM ', v_tbl_482,
                          ' WHERE ', v_col_482, ' = ?');
    SET @dparm_482 = 'NEW';
    PREPARE pst_482 FROM @dsql_482;
    EXECUTE pst_482 USING @dparm_482;
    DEALLOCATE PREPARE pst_482;
    SET @dupd_482 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_482 = 100;
    PREPARE pud_482 FROM @dupd_482;
    EXECUTE pud_482 USING @doid_482;
    DEALLOCATE PREPARE pud_482;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_482,0), 'COUNT',
            CONCAT('tbl ', v_tbl_482, ' col ', v_col_482));
  END;

  -- recursive block 483: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_483 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_483 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_483;
  END;

  -- reprice block 484: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_484 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_484;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_484, 'UPDATE', CONCAT('rows ', CAST(v_rows_484 AS CHAR)));
  END;

  -- validation block 485: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_485 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_485
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_485 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_485, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_485 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_485, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 486: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_486 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_486 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_486 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_486 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_486 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_486 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_486 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_486 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_486 AS CHAR), ' cr ', CAST(v_cr_486 AS CHAR),
                   ' dr ', CAST(v_dr_486 AS CHAR), ' tot ', CAST(v_tot_486 AS CHAR)));
  END;

  -- invoice rollup block 487: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_487 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_487 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_487
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_487
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_487 AS CHAR), ' paid ', CAST(v_paid_487 AS CHAR)));
  END;

  -- gl reconciliation block 488: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_488 INT DEFAULT 0;
    DECLARE v_acct_488 INT;
    DECLARE v_dr_488 DECIMAL(18,2);
    DECLARE v_cr_488 DECIMAL(18,2);
    DECLARE gcur_488 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_488 = 1;
    OPEN gcur_488;
    gl_488: LOOP
      FETCH gcur_488 INTO v_acct_488, v_dr_488, v_cr_488;
      IF v_gfin_488 = 1 THEN LEAVE gl_488; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_488, 'BALANCE',
              CONCAT('net ', CAST(v_dr_488 - v_cr_488 AS CHAR)));
    END LOOP;
    CLOSE gcur_488;
  END;

  -- transaction block 489: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_489;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_489;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 489, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 490: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_490;
    CREATE TEMPORARY TABLE tmp_agg_490 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_490 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_490 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_490;
  END;

  -- upsert block 491: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_491 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_491, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_491, 'MERGE', CONCAT('stock topped for ', CAST(v_key_491 AS CHAR)));
  END;

  -- json block 492: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_492 JSON;
    DECLARE v_sku_492 VARCHAR(40);
    DECLARE v_tag_492 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_492, v_sku_492, v_tag_492
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_492,''), ' tag ', IFNULL(v_tag_492,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_492, 'tag', v_tag_492) AS CHAR)));
  END;

  -- cte block 493: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_493 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_493 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_493 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_493 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 494: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_494 VARCHAR(10);
    DECLARE v_amt_494 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_494 FROM erp_order;
    SET v_band_494 = CASE
        WHEN v_amt_494 >= 10000 THEN 'HIGH'
        WHEN v_amt_494 >= 1000  THEN 'MED'
        WHEN v_amt_494 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_494, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 495: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_495 INT DEFAULT 0;
    DECLARE v_j_495 INT DEFAULT 0;
    DECLARE v_rc_495 INT DEFAULT 0;
    REPEAT
      SET v_i_495 = v_i_495 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R495'), v_i_495)
        ON DUPLICATE KEY UPDATE tick = v_i_495;
    UNTIL v_i_495 >= 3 END REPEAT;
    WHILE v_j_495 < 3 DO
      SET v_j_495 = v_j_495 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_495 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_495 + v_j_495, 'ITER',
            CONCAT('i ', CAST(v_i_495 AS CHAR), ' j ', CAST(v_j_495 AS CHAR),
                   ' diag ', CAST(v_rc_495 AS CHAR)));
  END;

  -- analytics block 496: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_496 INT DEFAULT 0;
    DECLARE v_amt_496 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_496 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_496 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_496, v_amt_496, v_avg_496, v_max_496
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_496 = v_amt_496 + erp_fn_tax_amount(v_amt_496, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_496, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_496 AS CHAR), ' avg ', CAST(v_avg_496 AS CHAR),
                   ' max ', CAST(v_max_496 AS CHAR)));
  END;

  -- reconcile block 497: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_497 INT DEFAULT 0;
    DECLARE v_pid_497 INT;
    DECLARE v_oh_497 DECIMAL(18,4);
    DECLARE v_av_497 DECIMAL(18,4);
    DECLARE cur_497 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_497 = 1;
    OPEN cur_497;
    rl_497: LOOP
      FETCH cur_497 INTO v_pid_497, v_oh_497;
      IF v_fin_497 = 1 THEN LEAVE rl_497; END IF;
      SET v_av_497 = erp_fn_available_qty(v_pid_497, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_497, 1, 'RECON', CAST(v_oh_497 - v_av_497 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_497 AS CHAR));
    END LOOP;
    CLOSE cur_497;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_497,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_497,0) AS CHAR)));
  END;

  -- dynamic-sql block 498: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_498 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_498 VARCHAR(64) DEFAULT 'status';
    SET @dsql_498 = CONCAT('SELECT COUNT(*) INTO @dcnt_498 FROM ', v_tbl_498,
                          ' WHERE ', v_col_498, ' = ?');
    SET @dparm_498 = 'NEW';
    PREPARE pst_498 FROM @dsql_498;
    EXECUTE pst_498 USING @dparm_498;
    DEALLOCATE PREPARE pst_498;
    SET @dupd_498 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_498 = 100;
    PREPARE pud_498 FROM @dupd_498;
    EXECUTE pud_498 USING @doid_498;
    DEALLOCATE PREPARE pud_498;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_498,0), 'COUNT',
            CONCAT('tbl ', v_tbl_498, ' col ', v_col_498));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_apply_payment  [procedure]
CREATE PROCEDURE erp_usp_apply_payment(IN p_invoice_id INT)
BEGIN
  DECLARE v_amt DECIMAL(18,2) DEFAULT 0;
  DECLARE v_pid INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('PAYMENT', p_invoice_id, 'ERROR', 'apply_payment failed');
  END;
  START TRANSACTION;
  SELECT gross_amount INTO v_amt FROM erp_invoice WHERE invoice_id = p_invoice_id;
  INSERT INTO erp_payment (customer_id, amount, currency, pay_status)
  SELECT customer_id, v_amt, 'USD', 'APPLIED' FROM erp_invoice WHERE invoice_id = p_invoice_id;
  SET v_pid = LAST_INSERT_ID();
  INSERT INTO erp_payment_alloc (payment_id, invoice_id, amount) VALUES (v_pid, p_invoice_id, v_amt);
  UPDATE erp_invoice SET status = 'PAID' WHERE invoice_id = p_invoice_id;
  COMMIT;
  CALL erp_usp_update_ledger(9200);
  CALL erp_usp_post_gl(9200, v_amt);
  CALL erp_usp_audit_log('PAYMENT', p_invoice_id, 'APPLY', CONCAT('amt ', CAST(v_amt AS CHAR)));

  -- recursive block 499: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_499 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_499 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_499;
  END;

  -- reprice block 500: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_500 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_500;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_500, 'UPDATE', CONCAT('rows ', CAST(v_rows_500 AS CHAR)));
  END;

  -- validation block 501: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_501 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_501
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_501 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_501, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_501 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_501, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 502: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_502 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_502 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_502 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_502 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_502 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_502 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_502 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_502 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_502 AS CHAR), ' cr ', CAST(v_cr_502 AS CHAR),
                   ' dr ', CAST(v_dr_502 AS CHAR), ' tot ', CAST(v_tot_502 AS CHAR)));
  END;

  -- invoice rollup block 503: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_503 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_503 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_503
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_503
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_503 AS CHAR), ' paid ', CAST(v_paid_503 AS CHAR)));
  END;

  -- gl reconciliation block 504: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_504 INT DEFAULT 0;
    DECLARE v_acct_504 INT;
    DECLARE v_dr_504 DECIMAL(18,2);
    DECLARE v_cr_504 DECIMAL(18,2);
    DECLARE gcur_504 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_504 = 1;
    OPEN gcur_504;
    gl_504: LOOP
      FETCH gcur_504 INTO v_acct_504, v_dr_504, v_cr_504;
      IF v_gfin_504 = 1 THEN LEAVE gl_504; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_504, 'BALANCE',
              CONCAT('net ', CAST(v_dr_504 - v_cr_504 AS CHAR)));
    END LOOP;
    CLOSE gcur_504;
  END;

  -- transaction block 505: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_505;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_505;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 505, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 506: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_506;
    CREATE TEMPORARY TABLE tmp_agg_506 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_506 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_506 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_506;
  END;

  -- upsert block 507: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_507 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_507, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_507, 'MERGE', CONCAT('stock topped for ', CAST(v_key_507 AS CHAR)));
  END;

  -- json block 508: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_508 JSON;
    DECLARE v_sku_508 VARCHAR(40);
    DECLARE v_tag_508 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_508, v_sku_508, v_tag_508
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_508,''), ' tag ', IFNULL(v_tag_508,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_508, 'tag', v_tag_508) AS CHAR)));
  END;

  -- cte block 509: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_509 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_509 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_509 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_509 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 510: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_510 VARCHAR(10);
    DECLARE v_amt_510 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_510 FROM erp_order;
    SET v_band_510 = CASE
        WHEN v_amt_510 >= 10000 THEN 'HIGH'
        WHEN v_amt_510 >= 1000  THEN 'MED'
        WHEN v_amt_510 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_510, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 511: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_511 INT DEFAULT 0;
    DECLARE v_j_511 INT DEFAULT 0;
    DECLARE v_rc_511 INT DEFAULT 0;
    REPEAT
      SET v_i_511 = v_i_511 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R511'), v_i_511)
        ON DUPLICATE KEY UPDATE tick = v_i_511;
    UNTIL v_i_511 >= 3 END REPEAT;
    WHILE v_j_511 < 3 DO
      SET v_j_511 = v_j_511 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_511 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_511 + v_j_511, 'ITER',
            CONCAT('i ', CAST(v_i_511 AS CHAR), ' j ', CAST(v_j_511 AS CHAR),
                   ' diag ', CAST(v_rc_511 AS CHAR)));
  END;

  -- analytics block 512: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_512 INT DEFAULT 0;
    DECLARE v_amt_512 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_512 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_512 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_512, v_amt_512, v_avg_512, v_max_512
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_512 = v_amt_512 + erp_fn_tax_amount(v_amt_512, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_512, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_512 AS CHAR), ' avg ', CAST(v_avg_512 AS CHAR),
                   ' max ', CAST(v_max_512 AS CHAR)));
  END;

  -- reconcile block 513: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_513 INT DEFAULT 0;
    DECLARE v_pid_513 INT;
    DECLARE v_oh_513 DECIMAL(18,4);
    DECLARE v_av_513 DECIMAL(18,4);
    DECLARE cur_513 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_513 = 1;
    OPEN cur_513;
    rl_513: LOOP
      FETCH cur_513 INTO v_pid_513, v_oh_513;
      IF v_fin_513 = 1 THEN LEAVE rl_513; END IF;
      SET v_av_513 = erp_fn_available_qty(v_pid_513, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_513, 1, 'RECON', CAST(v_oh_513 - v_av_513 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_513 AS CHAR));
    END LOOP;
    CLOSE cur_513;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_513,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_513,0) AS CHAR)));
  END;

  -- dynamic-sql block 514: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_514 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_514 VARCHAR(64) DEFAULT 'status';
    SET @dsql_514 = CONCAT('SELECT COUNT(*) INTO @dcnt_514 FROM ', v_tbl_514,
                          ' WHERE ', v_col_514, ' = ?');
    SET @dparm_514 = 'NEW';
    PREPARE pst_514 FROM @dsql_514;
    EXECUTE pst_514 USING @dparm_514;
    DEALLOCATE PREPARE pst_514;
    SET @dupd_514 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_514 = 100;
    PREPARE pud_514 FROM @dupd_514;
    EXECUTE pud_514 USING @doid_514;
    DEALLOCATE PREPARE pud_514;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_514,0), 'COUNT',
            CONCAT('tbl ', v_tbl_514, ' col ', v_col_514));
  END;

  -- recursive block 515: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_515 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_515 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_515;
  END;

  -- reprice block 516: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_516 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_516;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_516, 'UPDATE', CONCAT('rows ', CAST(v_rows_516 AS CHAR)));
  END;

  -- validation block 517: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_517 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_517
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_517 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_517, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_517 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_517, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 518: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_518 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_518 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_518 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_518 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_518 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_518 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_518 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_518 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_518 AS CHAR), ' cr ', CAST(v_cr_518 AS CHAR),
                   ' dr ', CAST(v_dr_518 AS CHAR), ' tot ', CAST(v_tot_518 AS CHAR)));
  END;

  -- invoice rollup block 519: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_519 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_519 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_519
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_519
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_519 AS CHAR), ' paid ', CAST(v_paid_519 AS CHAR)));
  END;

  -- gl reconciliation block 520: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_520 INT DEFAULT 0;
    DECLARE v_acct_520 INT;
    DECLARE v_dr_520 DECIMAL(18,2);
    DECLARE v_cr_520 DECIMAL(18,2);
    DECLARE gcur_520 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_520 = 1;
    OPEN gcur_520;
    gl_520: LOOP
      FETCH gcur_520 INTO v_acct_520, v_dr_520, v_cr_520;
      IF v_gfin_520 = 1 THEN LEAVE gl_520; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_520, 'BALANCE',
              CONCAT('net ', CAST(v_dr_520 - v_cr_520 AS CHAR)));
    END LOOP;
    CLOSE gcur_520;
  END;

  -- transaction block 521: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_521;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_521;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 521, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 522: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_522;
    CREATE TEMPORARY TABLE tmp_agg_522 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_522 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_522 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_522;
  END;

  -- upsert block 523: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_523 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_523, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_523, 'MERGE', CONCAT('stock topped for ', CAST(v_key_523 AS CHAR)));
  END;

  -- json block 524: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_524 JSON;
    DECLARE v_sku_524 VARCHAR(40);
    DECLARE v_tag_524 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_524, v_sku_524, v_tag_524
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_524,''), ' tag ', IFNULL(v_tag_524,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_524, 'tag', v_tag_524) AS CHAR)));
  END;

  -- cte block 525: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_525 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_525 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_525 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_525 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 526: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_526 VARCHAR(10);
    DECLARE v_amt_526 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_526 FROM erp_order;
    SET v_band_526 = CASE
        WHEN v_amt_526 >= 10000 THEN 'HIGH'
        WHEN v_amt_526 >= 1000  THEN 'MED'
        WHEN v_amt_526 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_526, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 527: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_527 INT DEFAULT 0;
    DECLARE v_j_527 INT DEFAULT 0;
    DECLARE v_rc_527 INT DEFAULT 0;
    REPEAT
      SET v_i_527 = v_i_527 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R527'), v_i_527)
        ON DUPLICATE KEY UPDATE tick = v_i_527;
    UNTIL v_i_527 >= 3 END REPEAT;
    WHILE v_j_527 < 3 DO
      SET v_j_527 = v_j_527 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_527 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_527 + v_j_527, 'ITER',
            CONCAT('i ', CAST(v_i_527 AS CHAR), ' j ', CAST(v_j_527 AS CHAR),
                   ' diag ', CAST(v_rc_527 AS CHAR)));
  END;

  -- analytics block 528: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_528 INT DEFAULT 0;
    DECLARE v_amt_528 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_528 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_528 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_528, v_amt_528, v_avg_528, v_max_528
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_528 = v_amt_528 + erp_fn_tax_amount(v_amt_528, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_528, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_528 AS CHAR), ' avg ', CAST(v_avg_528 AS CHAR),
                   ' max ', CAST(v_max_528 AS CHAR)));
  END;

  -- reconcile block 529: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_529 INT DEFAULT 0;
    DECLARE v_pid_529 INT;
    DECLARE v_oh_529 DECIMAL(18,4);
    DECLARE v_av_529 DECIMAL(18,4);
    DECLARE cur_529 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_529 = 1;
    OPEN cur_529;
    rl_529: LOOP
      FETCH cur_529 INTO v_pid_529, v_oh_529;
      IF v_fin_529 = 1 THEN LEAVE rl_529; END IF;
      SET v_av_529 = erp_fn_available_qty(v_pid_529, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_529, 1, 'RECON', CAST(v_oh_529 - v_av_529 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_529 AS CHAR));
    END LOOP;
    CLOSE cur_529;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_529,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_529,0) AS CHAR)));
  END;

  -- dynamic-sql block 530: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_530 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_530 VARCHAR(64) DEFAULT 'status';
    SET @dsql_530 = CONCAT('SELECT COUNT(*) INTO @dcnt_530 FROM ', v_tbl_530,
                          ' WHERE ', v_col_530, ' = ?');
    SET @dparm_530 = 'NEW';
    PREPARE pst_530 FROM @dsql_530;
    EXECUTE pst_530 USING @dparm_530;
    DEALLOCATE PREPARE pst_530;
    SET @dupd_530 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_530 = 100;
    PREPARE pud_530 FROM @dupd_530;
    EXECUTE pud_530 USING @doid_530;
    DEALLOCATE PREPARE pud_530;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_530,0), 'COUNT',
            CONCAT('tbl ', v_tbl_530, ' col ', v_col_530));
  END;

  -- recursive block 531: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_531 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_531 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_531;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_generate_invoice  [procedure]
CREATE PROCEDURE erp_usp_generate_invoice(IN p_order_id INT)
BEGIN
  DECLARE v_total DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cust INT;
  DECLARE v_inv INT;
  DECLARE v_doc BIGINT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('INVOICE', p_order_id, 'ERROR', 'generate_invoice failed');
  END;
  START TRANSACTION;
  SELECT customer_id INTO v_cust FROM erp_order WHERE order_id = p_order_id;
  SET v_total = erp_fn_order_total(p_order_id);
  SET v_doc = erp_fn_next_docnum('INV');
  INSERT INTO erp_invoice (order_id, customer_id, doc_number, gross_amount, net_amount, currency, status)
  VALUES (p_order_id, v_cust, v_doc, v_total, v_total, 'USD', 'OPEN');
  SET v_inv = LAST_INSERT_ID();
  SAVEPOINT sp_inv;
  UPDATE erp_order SET status = 'INVOICED' WHERE order_id = p_order_id;
  IF v_total <= 0 THEN
    ROLLBACK TO SAVEPOINT sp_inv;
  END IF;
  COMMIT;
  CALL erp_usp_ship_order(p_order_id);
  CALL erp_usp_apply_payment(v_inv);
  CALL erp_usp_post_gl(9300, v_total);
  CALL erp_usp_audit_log('INVOICE', v_inv, 'GENERATE', CONCAT('total ', CAST(v_total AS CHAR)));

  -- reprice block 532: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_532 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_532;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_532, 'UPDATE', CONCAT('rows ', CAST(v_rows_532 AS CHAR)));
  END;

  -- validation block 533: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_533 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_533
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_533 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_533, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_533 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_533, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 534: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_534 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_534 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_534 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_534 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_534 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_534 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_534 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_534 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_534 AS CHAR), ' cr ', CAST(v_cr_534 AS CHAR),
                   ' dr ', CAST(v_dr_534 AS CHAR), ' tot ', CAST(v_tot_534 AS CHAR)));
  END;

  -- invoice rollup block 535: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_535 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_535 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_535
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_535
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_535 AS CHAR), ' paid ', CAST(v_paid_535 AS CHAR)));
  END;

  -- gl reconciliation block 536: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_536 INT DEFAULT 0;
    DECLARE v_acct_536 INT;
    DECLARE v_dr_536 DECIMAL(18,2);
    DECLARE v_cr_536 DECIMAL(18,2);
    DECLARE gcur_536 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_536 = 1;
    OPEN gcur_536;
    gl_536: LOOP
      FETCH gcur_536 INTO v_acct_536, v_dr_536, v_cr_536;
      IF v_gfin_536 = 1 THEN LEAVE gl_536; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_536, 'BALANCE',
              CONCAT('net ', CAST(v_dr_536 - v_cr_536 AS CHAR)));
    END LOOP;
    CLOSE gcur_536;
  END;

  -- transaction block 537: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_537;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_537;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 537, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 538: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_538;
    CREATE TEMPORARY TABLE tmp_agg_538 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_538 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_538 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_538;
  END;

  -- upsert block 539: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_539 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_539, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_539, 'MERGE', CONCAT('stock topped for ', CAST(v_key_539 AS CHAR)));
  END;

  -- json block 540: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_540 JSON;
    DECLARE v_sku_540 VARCHAR(40);
    DECLARE v_tag_540 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_540, v_sku_540, v_tag_540
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_540,''), ' tag ', IFNULL(v_tag_540,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_540, 'tag', v_tag_540) AS CHAR)));
  END;

  -- cte block 541: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_541 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_541 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_541 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_541 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 542: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_542 VARCHAR(10);
    DECLARE v_amt_542 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_542 FROM erp_order;
    SET v_band_542 = CASE
        WHEN v_amt_542 >= 10000 THEN 'HIGH'
        WHEN v_amt_542 >= 1000  THEN 'MED'
        WHEN v_amt_542 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_542, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 543: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_543 INT DEFAULT 0;
    DECLARE v_j_543 INT DEFAULT 0;
    DECLARE v_rc_543 INT DEFAULT 0;
    REPEAT
      SET v_i_543 = v_i_543 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R543'), v_i_543)
        ON DUPLICATE KEY UPDATE tick = v_i_543;
    UNTIL v_i_543 >= 3 END REPEAT;
    WHILE v_j_543 < 3 DO
      SET v_j_543 = v_j_543 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_543 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_543 + v_j_543, 'ITER',
            CONCAT('i ', CAST(v_i_543 AS CHAR), ' j ', CAST(v_j_543 AS CHAR),
                   ' diag ', CAST(v_rc_543 AS CHAR)));
  END;

  -- analytics block 544: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_544 INT DEFAULT 0;
    DECLARE v_amt_544 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_544 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_544 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_544, v_amt_544, v_avg_544, v_max_544
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_544 = v_amt_544 + erp_fn_tax_amount(v_amt_544, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_544, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_544 AS CHAR), ' avg ', CAST(v_avg_544 AS CHAR),
                   ' max ', CAST(v_max_544 AS CHAR)));
  END;

  -- reconcile block 545: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_545 INT DEFAULT 0;
    DECLARE v_pid_545 INT;
    DECLARE v_oh_545 DECIMAL(18,4);
    DECLARE v_av_545 DECIMAL(18,4);
    DECLARE cur_545 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_545 = 1;
    OPEN cur_545;
    rl_545: LOOP
      FETCH cur_545 INTO v_pid_545, v_oh_545;
      IF v_fin_545 = 1 THEN LEAVE rl_545; END IF;
      SET v_av_545 = erp_fn_available_qty(v_pid_545, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_545, 1, 'RECON', CAST(v_oh_545 - v_av_545 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_545 AS CHAR));
    END LOOP;
    CLOSE cur_545;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_545,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_545,0) AS CHAR)));
  END;

  -- dynamic-sql block 546: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_546 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_546 VARCHAR(64) DEFAULT 'status';
    SET @dsql_546 = CONCAT('SELECT COUNT(*) INTO @dcnt_546 FROM ', v_tbl_546,
                          ' WHERE ', v_col_546, ' = ?');
    SET @dparm_546 = 'NEW';
    PREPARE pst_546 FROM @dsql_546;
    EXECUTE pst_546 USING @dparm_546;
    DEALLOCATE PREPARE pst_546;
    SET @dupd_546 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_546 = 100;
    PREPARE pud_546 FROM @dupd_546;
    EXECUTE pud_546 USING @doid_546;
    DEALLOCATE PREPARE pud_546;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_546,0), 'COUNT',
            CONCAT('tbl ', v_tbl_546, ' col ', v_col_546));
  END;

  -- recursive block 547: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_547 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_547 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_547;
  END;

  -- reprice block 548: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_548 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_548;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_548, 'UPDATE', CONCAT('rows ', CAST(v_rows_548 AS CHAR)));
  END;

