        WHEN v_amt_558 >= 10000 THEN 'HIGH'
        WHEN v_amt_558 >= 1000  THEN 'MED'
        WHEN v_amt_558 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_558, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 559: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_559 INT DEFAULT 0;
    DECLARE v_j_559 INT DEFAULT 0;
    DECLARE v_rc_559 INT DEFAULT 0;
    REPEAT
      SET v_i_559 = v_i_559 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R559'), v_i_559)
        ON DUPLICATE KEY UPDATE tick = v_i_559;
    UNTIL v_i_559 >= 3 END REPEAT;
    WHILE v_j_559 < 3 DO
      SET v_j_559 = v_j_559 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_559 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_559 + v_j_559, 'ITER',
            CONCAT('i ', CAST(v_i_559 AS CHAR), ' j ', CAST(v_j_559 AS CHAR),
                   ' diag ', CAST(v_rc_559 AS CHAR)));
  END;

  -- analytics block 560: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_560 INT DEFAULT 0;
    DECLARE v_amt_560 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_560 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_560 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_560, v_amt_560, v_avg_560, v_max_560
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_560 = v_amt_560 + erp_fn_tax_amount(v_amt_560, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_560, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_560 AS CHAR), ' avg ', CAST(v_avg_560 AS CHAR),
                   ' max ', CAST(v_max_560 AS CHAR)));
  END;

  -- reconcile block 561: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_561 INT DEFAULT 0;
    DECLARE v_pid_561 INT;
    DECLARE v_oh_561 DECIMAL(18,4);
    DECLARE v_av_561 DECIMAL(18,4);
    DECLARE cur_561 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_561 = 1;
    OPEN cur_561;
    rl_561: LOOP
      FETCH cur_561 INTO v_pid_561, v_oh_561;
      IF v_fin_561 = 1 THEN LEAVE rl_561; END IF;
      SET v_av_561 = erp_fn_available_qty(v_pid_561, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_561, 1, 'RECON', CAST(v_oh_561 - v_av_561 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_561 AS CHAR));
    END LOOP;
    CLOSE cur_561;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_561,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_561,0) AS CHAR)));
  END;

  -- dynamic-sql block 562: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_562 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_562 VARCHAR(64) DEFAULT 'status';
    SET @dsql_562 = CONCAT('SELECT COUNT(*) INTO @dcnt_562 FROM ', v_tbl_562,
                          ' WHERE ', v_col_562, ' = ?');
    SET @dparm_562 = 'NEW';
    PREPARE pst_562 FROM @dsql_562;
    EXECUTE pst_562 USING @dparm_562;
    DEALLOCATE PREPARE pst_562;
    SET @dupd_562 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_562 = 100;
    PREPARE pud_562 FROM @dupd_562;
    EXECUTE pud_562 USING @doid_562;
    DEALLOCATE PREPARE pud_562;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_562,0), 'COUNT',
            CONCAT('tbl ', v_tbl_562, ' col ', v_col_562));
  END;

  -- recursive block 563: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_563 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_563 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_563;
  END;

  -- reprice block 564: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_564 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_564;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_564, 'UPDATE', CONCAT('rows ', CAST(v_rows_564 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_issue_materials  [procedure]
CREATE PROCEDURE erp_usp_issue_materials(IN p_wo_id INT)
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_comp INT;
  DECLARE v_qty DECIMAL(18,4);
  DECLARE cur_bom CURSOR FOR
    SELECT component_id, qty_per FROM erp_bom WHERE parent_id =
      (SELECT product_id FROM erp_work_order WHERE work_order_id = p_wo_id);
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  OPEN cur_bom;
  im_loop: LOOP
    FETCH cur_bom INTO v_comp, v_qty;
    IF v_done = 1 THEN LEAVE im_loop; END IF;
    INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
    VALUES (v_comp, 1, 'ISSUE', v_qty, CONCAT('WO-', CAST(p_wo_id AS CHAR)));
  END LOOP;
  CLOSE cur_bom;
  CALL erp_usp_generate_invoice(100);
  CALL erp_usp_post_gl(9400, 0);
  CALL erp_usp_audit_log('WO', p_wo_id, 'ISSUE', 'materials issued');

  -- validation block 565: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_565 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_565
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_565 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_565, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_565 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_565, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 566: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_566 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_566 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_566 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_566 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_566 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_566 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_566 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_566 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_566 AS CHAR), ' cr ', CAST(v_cr_566 AS CHAR),
                   ' dr ', CAST(v_dr_566 AS CHAR), ' tot ', CAST(v_tot_566 AS CHAR)));
  END;

  -- invoice rollup block 567: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_567 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_567 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_567
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_567
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_567 AS CHAR), ' paid ', CAST(v_paid_567 AS CHAR)));
  END;

  -- gl reconciliation block 568: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_568 INT DEFAULT 0;
    DECLARE v_acct_568 INT;
    DECLARE v_dr_568 DECIMAL(18,2);
    DECLARE v_cr_568 DECIMAL(18,2);
    DECLARE gcur_568 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_568 = 1;
    OPEN gcur_568;
    gl_568: LOOP
      FETCH gcur_568 INTO v_acct_568, v_dr_568, v_cr_568;
      IF v_gfin_568 = 1 THEN LEAVE gl_568; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_568, 'BALANCE',
              CONCAT('net ', CAST(v_dr_568 - v_cr_568 AS CHAR)));
    END LOOP;
    CLOSE gcur_568;
  END;

  -- transaction block 569: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_569;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_569;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 569, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 570: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_570;
    CREATE TEMPORARY TABLE tmp_agg_570 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_570 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_570 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_570;
  END;

  -- upsert block 571: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_571 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_571, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_571, 'MERGE', CONCAT('stock topped for ', CAST(v_key_571 AS CHAR)));
  END;

  -- json block 572: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_572 JSON;
    DECLARE v_sku_572 VARCHAR(40);
    DECLARE v_tag_572 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_572, v_sku_572, v_tag_572
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_572,''), ' tag ', IFNULL(v_tag_572,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_572, 'tag', v_tag_572) AS CHAR)));
  END;

  -- cte block 573: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_573 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_573 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_573 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_573 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 574: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_574 VARCHAR(10);
    DECLARE v_amt_574 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_574 FROM erp_order;
    SET v_band_574 = CASE
        WHEN v_amt_574 >= 10000 THEN 'HIGH'
        WHEN v_amt_574 >= 1000  THEN 'MED'
        WHEN v_amt_574 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_574, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 575: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_575 INT DEFAULT 0;
    DECLARE v_j_575 INT DEFAULT 0;
    DECLARE v_rc_575 INT DEFAULT 0;
    REPEAT
      SET v_i_575 = v_i_575 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R575'), v_i_575)
        ON DUPLICATE KEY UPDATE tick = v_i_575;
    UNTIL v_i_575 >= 3 END REPEAT;
    WHILE v_j_575 < 3 DO
      SET v_j_575 = v_j_575 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_575 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_575 + v_j_575, 'ITER',
            CONCAT('i ', CAST(v_i_575 AS CHAR), ' j ', CAST(v_j_575 AS CHAR),
                   ' diag ', CAST(v_rc_575 AS CHAR)));
  END;

  -- analytics block 576: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_576 INT DEFAULT 0;
    DECLARE v_amt_576 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_576 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_576 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_576, v_amt_576, v_avg_576, v_max_576
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_576 = v_amt_576 + erp_fn_tax_amount(v_amt_576, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_576, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_576 AS CHAR), ' avg ', CAST(v_avg_576 AS CHAR),
                   ' max ', CAST(v_max_576 AS CHAR)));
  END;

  -- reconcile block 577: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_577 INT DEFAULT 0;
    DECLARE v_pid_577 INT;
    DECLARE v_oh_577 DECIMAL(18,4);
    DECLARE v_av_577 DECIMAL(18,4);
    DECLARE cur_577 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_577 = 1;
    OPEN cur_577;
    rl_577: LOOP
      FETCH cur_577 INTO v_pid_577, v_oh_577;
      IF v_fin_577 = 1 THEN LEAVE rl_577; END IF;
      SET v_av_577 = erp_fn_available_qty(v_pid_577, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_577, 1, 'RECON', CAST(v_oh_577 - v_av_577 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_577 AS CHAR));
    END LOOP;
    CLOSE cur_577;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_577,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_577,0) AS CHAR)));
  END;

  -- dynamic-sql block 578: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_578 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_578 VARCHAR(64) DEFAULT 'status';
    SET @dsql_578 = CONCAT('SELECT COUNT(*) INTO @dcnt_578 FROM ', v_tbl_578,
                          ' WHERE ', v_col_578, ' = ?');
    SET @dparm_578 = 'NEW';
    PREPARE pst_578 FROM @dsql_578;
    EXECUTE pst_578 USING @dparm_578;
    DEALLOCATE PREPARE pst_578;
    SET @dupd_578 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_578 = 100;
    PREPARE pud_578 FROM @dupd_578;
    EXECUTE pud_578 USING @doid_578;
    DEALLOCATE PREPARE pud_578;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_578,0), 'COUNT',
            CONCAT('tbl ', v_tbl_578, ' col ', v_col_578));
  END;

  -- recursive block 579: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_579 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_579 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_579;
  END;

  -- reprice block 580: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_580 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_580;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_580, 'UPDATE', CONCAT('rows ', CAST(v_rows_580 AS CHAR)));
  END;

  -- validation block 581: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_581 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_581
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_581 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_581, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_581 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_581, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 582: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_582 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_582 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_582 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_582 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_582 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_582 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_582 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_582 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_582 AS CHAR), ' cr ', CAST(v_cr_582 AS CHAR),
                   ' dr ', CAST(v_dr_582 AS CHAR), ' tot ', CAST(v_tot_582 AS CHAR)));
  END;

  -- invoice rollup block 583: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_583 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_583 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_583
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_583
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_583 AS CHAR), ' paid ', CAST(v_paid_583 AS CHAR)));
  END;

  -- gl reconciliation block 584: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_584 INT DEFAULT 0;
    DECLARE v_acct_584 INT;
    DECLARE v_dr_584 DECIMAL(18,2);
    DECLARE v_cr_584 DECIMAL(18,2);
    DECLARE gcur_584 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_584 = 1;
    OPEN gcur_584;
    gl_584: LOOP
      FETCH gcur_584 INTO v_acct_584, v_dr_584, v_cr_584;
      IF v_gfin_584 = 1 THEN LEAVE gl_584; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_584, 'BALANCE',
              CONCAT('net ', CAST(v_dr_584 - v_cr_584 AS CHAR)));
    END LOOP;
    CLOSE gcur_584;
  END;

  -- transaction block 585: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_585;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_585;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 585, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 586: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_586;
    CREATE TEMPORARY TABLE tmp_agg_586 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_586 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_586 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_586;
  END;

  -- upsert block 587: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_587 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_587, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_587, 'MERGE', CONCAT('stock topped for ', CAST(v_key_587 AS CHAR)));
  END;

  -- json block 588: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_588 JSON;
    DECLARE v_sku_588 VARCHAR(40);
    DECLARE v_tag_588 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_588, v_sku_588, v_tag_588
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_588,''), ' tag ', IFNULL(v_tag_588,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_588, 'tag', v_tag_588) AS CHAR)));
  END;

  -- cte block 589: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_589 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_589 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_589 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_589 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 590: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_590 VARCHAR(10);
    DECLARE v_amt_590 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_590 FROM erp_order;
    SET v_band_590 = CASE
        WHEN v_amt_590 >= 10000 THEN 'HIGH'
        WHEN v_amt_590 >= 1000  THEN 'MED'
        WHEN v_amt_590 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_590, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 591: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_591 INT DEFAULT 0;
    DECLARE v_j_591 INT DEFAULT 0;
    DECLARE v_rc_591 INT DEFAULT 0;
    REPEAT
      SET v_i_591 = v_i_591 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R591'), v_i_591)
        ON DUPLICATE KEY UPDATE tick = v_i_591;
    UNTIL v_i_591 >= 3 END REPEAT;
    WHILE v_j_591 < 3 DO
      SET v_j_591 = v_j_591 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_591 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_591 + v_j_591, 'ITER',
            CONCAT('i ', CAST(v_i_591 AS CHAR), ' j ', CAST(v_j_591 AS CHAR),
                   ' diag ', CAST(v_rc_591 AS CHAR)));
  END;

  -- analytics block 592: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_592 INT DEFAULT 0;
    DECLARE v_amt_592 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_592 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_592 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_592, v_amt_592, v_avg_592, v_max_592
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_592 = v_amt_592 + erp_fn_tax_amount(v_amt_592, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_592, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_592 AS CHAR), ' avg ', CAST(v_avg_592 AS CHAR),
                   ' max ', CAST(v_max_592 AS CHAR)));
  END;

  -- reconcile block 593: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_593 INT DEFAULT 0;
    DECLARE v_pid_593 INT;
    DECLARE v_oh_593 DECIMAL(18,4);
    DECLARE v_av_593 DECIMAL(18,4);
    DECLARE cur_593 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_593 = 1;
    OPEN cur_593;
    rl_593: LOOP
      FETCH cur_593 INTO v_pid_593, v_oh_593;
      IF v_fin_593 = 1 THEN LEAVE rl_593; END IF;
      SET v_av_593 = erp_fn_available_qty(v_pid_593, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_593, 1, 'RECON', CAST(v_oh_593 - v_av_593 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_593 AS CHAR));
    END LOOP;
    CLOSE cur_593;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_593,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_593,0) AS CHAR)));
  END;

  -- dynamic-sql block 594: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_594 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_594 VARCHAR(64) DEFAULT 'status';
    SET @dsql_594 = CONCAT('SELECT COUNT(*) INTO @dcnt_594 FROM ', v_tbl_594,
                          ' WHERE ', v_col_594, ' = ?');
    SET @dparm_594 = 'NEW';
    PREPARE pst_594 FROM @dsql_594;
    EXECUTE pst_594 USING @dparm_594;
    DEALLOCATE PREPARE pst_594;
    SET @dupd_594 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_594 = 100;
    PREPARE pud_594 FROM @dupd_594;
    EXECUTE pud_594 USING @doid_594;
    DEALLOCATE PREPARE pud_594;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_594,0), 'COUNT',
            CONCAT('tbl ', v_tbl_594, ' col ', v_col_594));
  END;

  -- recursive block 595: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_595 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_595 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_595;
  END;

  -- reprice block 596: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_596 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_596;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_596, 'UPDATE', CONCAT('rows ', CAST(v_rows_596 AS CHAR)));
  END;

  -- validation block 597: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_597 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_597
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_597 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_597, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_597 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_597, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_explode_bom  [procedure]
CREATE PROCEDURE erp_usp_explode_bom(IN p_product_id INT)
BEGIN
  DECLARE v_wo INT DEFAULT 7000;
  INSERT INTO erp_audit_log (entity, entity_id, action, detail)
  WITH RECURSIVE bom_tree AS (
    SELECT parent_id, component_id, qty_per, 1 AS lvl
      FROM erp_bom WHERE parent_id = p_product_id
    UNION ALL
    SELECT b.parent_id, b.component_id, b.qty_per, bt.lvl + 1
      FROM erp_bom b
      JOIN bom_tree bt ON b.parent_id = bt.component_id
     WHERE bt.lvl < 15
  )
  SELECT 'BOM', component_id, 'EXPLODE', CONCAT('lvl ', CAST(lvl AS CHAR))
    FROM bom_tree;
  CALL erp_usp_bom_explode_rec(p_product_id, 0);
  CALL erp_usp_issue_materials(v_wo);
  CALL erp_usp_audit_log('BOM', p_product_id, 'EXPLODE', 'bom exploded');

  -- fx/credit block 598: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_598 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_598 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_598 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_598 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_598 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_598 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_598 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_598 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_598 AS CHAR), ' cr ', CAST(v_cr_598 AS CHAR),
                   ' dr ', CAST(v_dr_598 AS CHAR), ' tot ', CAST(v_tot_598 AS CHAR)));
  END;

  -- invoice rollup block 599: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_599 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_599 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_599
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_599
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_599 AS CHAR), ' paid ', CAST(v_paid_599 AS CHAR)));
  END;

  -- gl reconciliation block 600: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_600 INT DEFAULT 0;
    DECLARE v_acct_600 INT;
    DECLARE v_dr_600 DECIMAL(18,2);
    DECLARE v_cr_600 DECIMAL(18,2);
    DECLARE gcur_600 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_600 = 1;
    OPEN gcur_600;
    gl_600: LOOP
      FETCH gcur_600 INTO v_acct_600, v_dr_600, v_cr_600;
      IF v_gfin_600 = 1 THEN LEAVE gl_600; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_600, 'BALANCE',
              CONCAT('net ', CAST(v_dr_600 - v_cr_600 AS CHAR)));
    END LOOP;
    CLOSE gcur_600;
  END;

  -- transaction block 601: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_601;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_601;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 601, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 602: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_602;
    CREATE TEMPORARY TABLE tmp_agg_602 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_602 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_602 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_602;
  END;

  -- upsert block 603: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_603 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_603, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_603, 'MERGE', CONCAT('stock topped for ', CAST(v_key_603 AS CHAR)));
  END;

  -- json block 604: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_604 JSON;
    DECLARE v_sku_604 VARCHAR(40);
    DECLARE v_tag_604 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_604, v_sku_604, v_tag_604
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_604,''), ' tag ', IFNULL(v_tag_604,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_604, 'tag', v_tag_604) AS CHAR)));
  END;

  -- cte block 605: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_605 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_605 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_605 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_605 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 606: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_606 VARCHAR(10);
    DECLARE v_amt_606 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_606 FROM erp_order;
    SET v_band_606 = CASE
        WHEN v_amt_606 >= 10000 THEN 'HIGH'
        WHEN v_amt_606 >= 1000  THEN 'MED'
        WHEN v_amt_606 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_606, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 607: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_607 INT DEFAULT 0;
    DECLARE v_j_607 INT DEFAULT 0;
    DECLARE v_rc_607 INT DEFAULT 0;
    REPEAT
      SET v_i_607 = v_i_607 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R607'), v_i_607)
        ON DUPLICATE KEY UPDATE tick = v_i_607;
    UNTIL v_i_607 >= 3 END REPEAT;
    WHILE v_j_607 < 3 DO
      SET v_j_607 = v_j_607 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_607 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_607 + v_j_607, 'ITER',
            CONCAT('i ', CAST(v_i_607 AS CHAR), ' j ', CAST(v_j_607 AS CHAR),
                   ' diag ', CAST(v_rc_607 AS CHAR)));
  END;

  -- analytics block 608: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_608 INT DEFAULT 0;
    DECLARE v_amt_608 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_608 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_608 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_608, v_amt_608, v_avg_608, v_max_608
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_608 = v_amt_608 + erp_fn_tax_amount(v_amt_608, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_608, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_608 AS CHAR), ' avg ', CAST(v_avg_608 AS CHAR),
                   ' max ', CAST(v_max_608 AS CHAR)));
  END;

  -- reconcile block 609: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_609 INT DEFAULT 0;
    DECLARE v_pid_609 INT;
    DECLARE v_oh_609 DECIMAL(18,4);
    DECLARE v_av_609 DECIMAL(18,4);
    DECLARE cur_609 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_609 = 1;
    OPEN cur_609;
    rl_609: LOOP
      FETCH cur_609 INTO v_pid_609, v_oh_609;
      IF v_fin_609 = 1 THEN LEAVE rl_609; END IF;
      SET v_av_609 = erp_fn_available_qty(v_pid_609, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_609, 1, 'RECON', CAST(v_oh_609 - v_av_609 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_609 AS CHAR));
    END LOOP;
    CLOSE cur_609;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_609,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_609,0) AS CHAR)));
  END;

  -- dynamic-sql block 610: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_610 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_610 VARCHAR(64) DEFAULT 'status';
    SET @dsql_610 = CONCAT('SELECT COUNT(*) INTO @dcnt_610 FROM ', v_tbl_610,
                          ' WHERE ', v_col_610, ' = ?');
    SET @dparm_610 = 'NEW';
    PREPARE pst_610 FROM @dsql_610;
    EXECUTE pst_610 USING @dparm_610;
    DEALLOCATE PREPARE pst_610;
    SET @dupd_610 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_610 = 100;
    PREPARE pud_610 FROM @dupd_610;
    EXECUTE pud_610 USING @doid_610;
    DEALLOCATE PREPARE pud_610;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_610,0), 'COUNT',
            CONCAT('tbl ', v_tbl_610, ' col ', v_col_610));
  END;

  -- recursive block 611: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_611 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_611 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_611;
  END;

  -- reprice block 612: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_612 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_612;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_612, 'UPDATE', CONCAT('rows ', CAST(v_rows_612 AS CHAR)));
  END;

  -- validation block 613: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_613 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_613
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_613 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_613, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_613 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_613, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 614: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_614 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_614 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_614 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_614 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_614 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_614 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_614 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_614 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_614 AS CHAR), ' cr ', CAST(v_cr_614 AS CHAR),
                   ' dr ', CAST(v_dr_614 AS CHAR), ' tot ', CAST(v_tot_614 AS CHAR)));
  END;

  -- invoice rollup block 615: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_615 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_615 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_615
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_615
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_615 AS CHAR), ' paid ', CAST(v_paid_615 AS CHAR)));
  END;

  -- gl reconciliation block 616: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_616 INT DEFAULT 0;
    DECLARE v_acct_616 INT;
    DECLARE v_dr_616 DECIMAL(18,2);
    DECLARE v_cr_616 DECIMAL(18,2);
    DECLARE gcur_616 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_616 = 1;
    OPEN gcur_616;
    gl_616: LOOP
      FETCH gcur_616 INTO v_acct_616, v_dr_616, v_cr_616;
      IF v_gfin_616 = 1 THEN LEAVE gl_616; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_616, 'BALANCE',
              CONCAT('net ', CAST(v_dr_616 - v_cr_616 AS CHAR)));
    END LOOP;
    CLOSE gcur_616;
  END;

  -- transaction block 617: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_617;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_617;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 617, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 618: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_618;
    CREATE TEMPORARY TABLE tmp_agg_618 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_618 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_618 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_618;
  END;

  -- upsert block 619: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_619 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_619, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_619, 'MERGE', CONCAT('stock topped for ', CAST(v_key_619 AS CHAR)));
  END;

  -- json block 620: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_620 JSON;
    DECLARE v_sku_620 VARCHAR(40);
    DECLARE v_tag_620 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_620, v_sku_620, v_tag_620
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_620,''), ' tag ', IFNULL(v_tag_620,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_620, 'tag', v_tag_620) AS CHAR)));
  END;

  -- cte block 621: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_621 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_621 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_621 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_621 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

