  -- reprice block 628: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_628 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_628;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_628, 'UPDATE', CONCAT('rows ', CAST(v_rows_628 AS CHAR)));
  END;

  -- validation block 629: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_629 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_629
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_629 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_629, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_629 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_629, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 630: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_630 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_630 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_630 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_630 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_630 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_630 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_630 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_630 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_630 AS CHAR), ' cr ', CAST(v_cr_630 AS CHAR),
                   ' dr ', CAST(v_dr_630 AS CHAR), ' tot ', CAST(v_tot_630 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_plan_production  [procedure]
CREATE PROCEDURE erp_usp_plan_production(IN p_product_id INT)
BEGIN
  DECLARE v_need DECIMAL(18,4) DEFAULT 0;
  SELECT IFNULL(SUM(qty),0) INTO v_need
    FROM erp_order_line WHERE product_id = p_product_id;
  INSERT INTO erp_work_order (product_id, planned_qty, wo_status)
  VALUES (p_product_id, v_need, 'PLANNED')
  ON DUPLICATE KEY UPDATE planned_qty = v_need;
  CALL erp_usp_explode_bom(p_product_id);
  CALL erp_usp_audit_log('MRP', p_product_id, 'PLAN', CONCAT('need ', CAST(v_need AS CHAR)));

  -- invoice rollup block 631: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_631 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_631 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_631
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_631
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_631 AS CHAR), ' paid ', CAST(v_paid_631 AS CHAR)));
  END;

  -- gl reconciliation block 632: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_632 INT DEFAULT 0;
    DECLARE v_acct_632 INT;
    DECLARE v_dr_632 DECIMAL(18,2);
    DECLARE v_cr_632 DECIMAL(18,2);
    DECLARE gcur_632 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_632 = 1;
    OPEN gcur_632;
    gl_632: LOOP
      FETCH gcur_632 INTO v_acct_632, v_dr_632, v_cr_632;
      IF v_gfin_632 = 1 THEN LEAVE gl_632; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_632, 'BALANCE',
              CONCAT('net ', CAST(v_dr_632 - v_cr_632 AS CHAR)));
    END LOOP;
    CLOSE gcur_632;
  END;

  -- transaction block 633: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_633;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_633;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 633, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 634: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_634;
    CREATE TEMPORARY TABLE tmp_agg_634 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_634 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_634 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_634;
  END;

  -- upsert block 635: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_635 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_635, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_635, 'MERGE', CONCAT('stock topped for ', CAST(v_key_635 AS CHAR)));
  END;

  -- json block 636: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_636 JSON;
    DECLARE v_sku_636 VARCHAR(40);
    DECLARE v_tag_636 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_636, v_sku_636, v_tag_636
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_636,''), ' tag ', IFNULL(v_tag_636,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_636, 'tag', v_tag_636) AS CHAR)));
  END;

  -- cte block 637: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_637 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_637 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_637 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_637 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 638: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_638 VARCHAR(10);
    DECLARE v_amt_638 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_638 FROM erp_order;
    SET v_band_638 = CASE
        WHEN v_amt_638 >= 10000 THEN 'HIGH'
        WHEN v_amt_638 >= 1000  THEN 'MED'
        WHEN v_amt_638 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_638, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 639: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_639 INT DEFAULT 0;
    DECLARE v_j_639 INT DEFAULT 0;
    DECLARE v_rc_639 INT DEFAULT 0;
    REPEAT
      SET v_i_639 = v_i_639 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R639'), v_i_639)
        ON DUPLICATE KEY UPDATE tick = v_i_639;
    UNTIL v_i_639 >= 3 END REPEAT;
    WHILE v_j_639 < 3 DO
      SET v_j_639 = v_j_639 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_639 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_639 + v_j_639, 'ITER',
            CONCAT('i ', CAST(v_i_639 AS CHAR), ' j ', CAST(v_j_639 AS CHAR),
                   ' diag ', CAST(v_rc_639 AS CHAR)));
  END;

  -- analytics block 640: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_640 INT DEFAULT 0;
    DECLARE v_amt_640 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_640 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_640 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_640, v_amt_640, v_avg_640, v_max_640
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_640 = v_amt_640 + erp_fn_tax_amount(v_amt_640, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_640, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_640 AS CHAR), ' avg ', CAST(v_avg_640 AS CHAR),
                   ' max ', CAST(v_max_640 AS CHAR)));
  END;

  -- reconcile block 641: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_641 INT DEFAULT 0;
    DECLARE v_pid_641 INT;
    DECLARE v_oh_641 DECIMAL(18,4);
    DECLARE v_av_641 DECIMAL(18,4);
    DECLARE cur_641 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_641 = 1;
    OPEN cur_641;
    rl_641: LOOP
      FETCH cur_641 INTO v_pid_641, v_oh_641;
      IF v_fin_641 = 1 THEN LEAVE rl_641; END IF;
      SET v_av_641 = erp_fn_available_qty(v_pid_641, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_641, 1, 'RECON', CAST(v_oh_641 - v_av_641 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_641 AS CHAR));
    END LOOP;
    CLOSE cur_641;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_641,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_641,0) AS CHAR)));
  END;

  -- dynamic-sql block 642: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_642 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_642 VARCHAR(64) DEFAULT 'status';
    SET @dsql_642 = CONCAT('SELECT COUNT(*) INTO @dcnt_642 FROM ', v_tbl_642,
                          ' WHERE ', v_col_642, ' = ?');
    SET @dparm_642 = 'NEW';
    PREPARE pst_642 FROM @dsql_642;
    EXECUTE pst_642 USING @dparm_642;
    DEALLOCATE PREPARE pst_642;
    SET @dupd_642 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_642 = 100;
    PREPARE pud_642 FROM @dupd_642;
    EXECUTE pud_642 USING @doid_642;
    DEALLOCATE PREPARE pud_642;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_642,0), 'COUNT',
            CONCAT('tbl ', v_tbl_642, ' col ', v_col_642));
  END;

  -- recursive block 643: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_643 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_643 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_643;
  END;

  -- reprice block 644: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_644 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_644;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_644, 'UPDATE', CONCAT('rows ', CAST(v_rows_644 AS CHAR)));
  END;

  -- validation block 645: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_645 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_645
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_645 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_645, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_645 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_645, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 646: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_646 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_646 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_646 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_646 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_646 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_646 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_646 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_646 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_646 AS CHAR), ' cr ', CAST(v_cr_646 AS CHAR),
                   ' dr ', CAST(v_dr_646 AS CHAR), ' tot ', CAST(v_tot_646 AS CHAR)));
  END;

  -- invoice rollup block 647: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_647 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_647 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_647
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_647
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_647 AS CHAR), ' paid ', CAST(v_paid_647 AS CHAR)));
  END;

  -- gl reconciliation block 648: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_648 INT DEFAULT 0;
    DECLARE v_acct_648 INT;
    DECLARE v_dr_648 DECIMAL(18,2);
    DECLARE v_cr_648 DECIMAL(18,2);
    DECLARE gcur_648 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_648 = 1;
    OPEN gcur_648;
    gl_648: LOOP
      FETCH gcur_648 INTO v_acct_648, v_dr_648, v_cr_648;
      IF v_gfin_648 = 1 THEN LEAVE gl_648; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_648, 'BALANCE',
              CONCAT('net ', CAST(v_dr_648 - v_cr_648 AS CHAR)));
    END LOOP;
    CLOSE gcur_648;
  END;

  -- transaction block 649: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_649;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_649;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 649, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 650: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_650;
    CREATE TEMPORARY TABLE tmp_agg_650 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_650 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_650 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_650;
  END;

  -- upsert block 651: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_651 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_651, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_651, 'MERGE', CONCAT('stock topped for ', CAST(v_key_651 AS CHAR)));
  END;

  -- json block 652: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_652 JSON;
    DECLARE v_sku_652 VARCHAR(40);
    DECLARE v_tag_652 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_652, v_sku_652, v_tag_652
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_652,''), ' tag ', IFNULL(v_tag_652,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_652, 'tag', v_tag_652) AS CHAR)));
  END;

  -- cte block 653: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_653 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_653 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_653 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_653 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 654: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_654 VARCHAR(10);
    DECLARE v_amt_654 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_654 FROM erp_order;
    SET v_band_654 = CASE
        WHEN v_amt_654 >= 10000 THEN 'HIGH'
        WHEN v_amt_654 >= 1000  THEN 'MED'
        WHEN v_amt_654 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_654, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 655: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_655 INT DEFAULT 0;
    DECLARE v_j_655 INT DEFAULT 0;
    DECLARE v_rc_655 INT DEFAULT 0;
    REPEAT
      SET v_i_655 = v_i_655 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R655'), v_i_655)
        ON DUPLICATE KEY UPDATE tick = v_i_655;
    UNTIL v_i_655 >= 3 END REPEAT;
    WHILE v_j_655 < 3 DO
      SET v_j_655 = v_j_655 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_655 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_655 + v_j_655, 'ITER',
            CONCAT('i ', CAST(v_i_655 AS CHAR), ' j ', CAST(v_j_655 AS CHAR),
                   ' diag ', CAST(v_rc_655 AS CHAR)));
  END;

  -- analytics block 656: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_656 INT DEFAULT 0;
    DECLARE v_amt_656 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_656 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_656 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_656, v_amt_656, v_avg_656, v_max_656
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_656 = v_amt_656 + erp_fn_tax_amount(v_amt_656, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_656, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_656 AS CHAR), ' avg ', CAST(v_avg_656 AS CHAR),
                   ' max ', CAST(v_max_656 AS CHAR)));
  END;

  -- reconcile block 657: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_657 INT DEFAULT 0;
    DECLARE v_pid_657 INT;
    DECLARE v_oh_657 DECIMAL(18,4);
    DECLARE v_av_657 DECIMAL(18,4);
    DECLARE cur_657 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_657 = 1;
    OPEN cur_657;
    rl_657: LOOP
      FETCH cur_657 INTO v_pid_657, v_oh_657;
      IF v_fin_657 = 1 THEN LEAVE rl_657; END IF;
      SET v_av_657 = erp_fn_available_qty(v_pid_657, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_657, 1, 'RECON', CAST(v_oh_657 - v_av_657 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_657 AS CHAR));
    END LOOP;
    CLOSE cur_657;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_657,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_657,0) AS CHAR)));
  END;

  -- dynamic-sql block 658: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_658 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_658 VARCHAR(64) DEFAULT 'status';
    SET @dsql_658 = CONCAT('SELECT COUNT(*) INTO @dcnt_658 FROM ', v_tbl_658,
                          ' WHERE ', v_col_658, ' = ?');
    SET @dparm_658 = 'NEW';
    PREPARE pst_658 FROM @dsql_658;
    EXECUTE pst_658 USING @dparm_658;
    DEALLOCATE PREPARE pst_658;
    SET @dupd_658 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_658 = 100;
    PREPARE pud_658 FROM @dupd_658;
    EXECUTE pud_658 USING @doid_658;
    DEALLOCATE PREPARE pud_658;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_658,0), 'COUNT',
            CONCAT('tbl ', v_tbl_658, ' col ', v_col_658));
  END;

  -- recursive block 659: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_659 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_659 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_659;
  END;

  -- reprice block 660: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_660 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_660;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_660, 'UPDATE', CONCAT('rows ', CAST(v_rows_660 AS CHAR)));
  END;

  -- validation block 661: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_661 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_661
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_661 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_661, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_661 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_661, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 662: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_662 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_662 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_662 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_662 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_662 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_662 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_662 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_662 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_662 AS CHAR), ' cr ', CAST(v_cr_662 AS CHAR),
                   ' dr ', CAST(v_dr_662 AS CHAR), ' tot ', CAST(v_tot_662 AS CHAR)));
  END;

  -- invoice rollup block 663: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_663 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_663 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_663
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_663
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_663 AS CHAR), ' paid ', CAST(v_paid_663 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_reserve_stock  [procedure]
CREATE PROCEDURE erp_usp_reserve_stock(IN p_order_id INT)
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_pid INT;
  DECLARE v_qty DECIMAL(18,4);
  DECLARE cur_ln CURSOR FOR
    SELECT product_id, qty FROM erp_order_line WHERE order_id = p_order_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  OPEN cur_ln;
  rs_loop: LOOP
    FETCH cur_ln INTO v_pid, v_qty;
    IF v_done = 1 THEN LEAVE rs_loop; END IF;
    UPDATE erp_stock_level SET qty_reserved = qty_reserved + v_qty
     WHERE product_id = v_pid AND warehouse_id = 1;
    CALL erp_usp_plan_production(v_pid);
  END LOOP;
  CLOSE cur_ln;
  CALL erp_usp_audit_log('RESERVE', p_order_id, 'RESERVE', 'stock reserved');

  -- gl reconciliation block 664: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_664 INT DEFAULT 0;
    DECLARE v_acct_664 INT;
    DECLARE v_dr_664 DECIMAL(18,2);
    DECLARE v_cr_664 DECIMAL(18,2);
    DECLARE gcur_664 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_664 = 1;
    OPEN gcur_664;
    gl_664: LOOP
      FETCH gcur_664 INTO v_acct_664, v_dr_664, v_cr_664;
      IF v_gfin_664 = 1 THEN LEAVE gl_664; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_664, 'BALANCE',
              CONCAT('net ', CAST(v_dr_664 - v_cr_664 AS CHAR)));
    END LOOP;
    CLOSE gcur_664;
  END;

  -- transaction block 665: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_665;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_665;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 665, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 666: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_666;
    CREATE TEMPORARY TABLE tmp_agg_666 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_666 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_666 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_666;
  END;

  -- upsert block 667: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_667 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_667, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_667, 'MERGE', CONCAT('stock topped for ', CAST(v_key_667 AS CHAR)));
  END;

  -- json block 668: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_668 JSON;
    DECLARE v_sku_668 VARCHAR(40);
    DECLARE v_tag_668 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_668, v_sku_668, v_tag_668
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_668,''), ' tag ', IFNULL(v_tag_668,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_668, 'tag', v_tag_668) AS CHAR)));
  END;

  -- cte block 669: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_669 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_669 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_669 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_669 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 670: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_670 VARCHAR(10);
    DECLARE v_amt_670 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_670 FROM erp_order;
    SET v_band_670 = CASE
        WHEN v_amt_670 >= 10000 THEN 'HIGH'
        WHEN v_amt_670 >= 1000  THEN 'MED'
        WHEN v_amt_670 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_670, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 671: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_671 INT DEFAULT 0;
    DECLARE v_j_671 INT DEFAULT 0;
    DECLARE v_rc_671 INT DEFAULT 0;
    REPEAT
      SET v_i_671 = v_i_671 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R671'), v_i_671)
        ON DUPLICATE KEY UPDATE tick = v_i_671;
    UNTIL v_i_671 >= 3 END REPEAT;
    WHILE v_j_671 < 3 DO
      SET v_j_671 = v_j_671 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_671 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_671 + v_j_671, 'ITER',
            CONCAT('i ', CAST(v_i_671 AS CHAR), ' j ', CAST(v_j_671 AS CHAR),
                   ' diag ', CAST(v_rc_671 AS CHAR)));
  END;

  -- analytics block 672: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_672 INT DEFAULT 0;
    DECLARE v_amt_672 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_672 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_672 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_672, v_amt_672, v_avg_672, v_max_672
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_672 = v_amt_672 + erp_fn_tax_amount(v_amt_672, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_672, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_672 AS CHAR), ' avg ', CAST(v_avg_672 AS CHAR),
                   ' max ', CAST(v_max_672 AS CHAR)));
  END;

  -- reconcile block 673: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_673 INT DEFAULT 0;
    DECLARE v_pid_673 INT;
    DECLARE v_oh_673 DECIMAL(18,4);
    DECLARE v_av_673 DECIMAL(18,4);
    DECLARE cur_673 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_673 = 1;
    OPEN cur_673;
    rl_673: LOOP
      FETCH cur_673 INTO v_pid_673, v_oh_673;
      IF v_fin_673 = 1 THEN LEAVE rl_673; END IF;
      SET v_av_673 = erp_fn_available_qty(v_pid_673, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_673, 1, 'RECON', CAST(v_oh_673 - v_av_673 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_673 AS CHAR));
    END LOOP;
    CLOSE cur_673;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_673,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_673,0) AS CHAR)));
  END;

  -- dynamic-sql block 674: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_674 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_674 VARCHAR(64) DEFAULT 'status';
    SET @dsql_674 = CONCAT('SELECT COUNT(*) INTO @dcnt_674 FROM ', v_tbl_674,
                          ' WHERE ', v_col_674, ' = ?');
    SET @dparm_674 = 'NEW';
    PREPARE pst_674 FROM @dsql_674;
    EXECUTE pst_674 USING @dparm_674;
    DEALLOCATE PREPARE pst_674;
    SET @dupd_674 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_674 = 100;
    PREPARE pud_674 FROM @dupd_674;
    EXECUTE pud_674 USING @doid_674;
    DEALLOCATE PREPARE pud_674;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_674,0), 'COUNT',
            CONCAT('tbl ', v_tbl_674, ' col ', v_col_674));
  END;

  -- recursive block 675: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_675 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_675 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_675;
  END;

  -- reprice block 676: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_676 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_676;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_676, 'UPDATE', CONCAT('rows ', CAST(v_rows_676 AS CHAR)));
  END;

  -- validation block 677: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_677 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_677
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_677 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_677, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_677 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_677, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 678: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_678 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_678 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_678 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_678 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_678 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_678 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_678 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_678 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_678 AS CHAR), ' cr ', CAST(v_cr_678 AS CHAR),
                   ' dr ', CAST(v_dr_678 AS CHAR), ' tot ', CAST(v_tot_678 AS CHAR)));
  END;

  -- invoice rollup block 679: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_679 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_679 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_679
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_679
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_679 AS CHAR), ' paid ', CAST(v_paid_679 AS CHAR)));
  END;

  -- gl reconciliation block 680: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_680 INT DEFAULT 0;
    DECLARE v_acct_680 INT;
    DECLARE v_dr_680 DECIMAL(18,2);
    DECLARE v_cr_680 DECIMAL(18,2);
    DECLARE gcur_680 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_680 = 1;
    OPEN gcur_680;
    gl_680: LOOP
      FETCH gcur_680 INTO v_acct_680, v_dr_680, v_cr_680;
      IF v_gfin_680 = 1 THEN LEAVE gl_680; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_680, 'BALANCE',
              CONCAT('net ', CAST(v_dr_680 - v_cr_680 AS CHAR)));
    END LOOP;
    CLOSE gcur_680;
  END;

  -- transaction block 681: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_681;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_681;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 681, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 682: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_682;
    CREATE TEMPORARY TABLE tmp_agg_682 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_682 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_682 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_682;
  END;

  -- upsert block 683: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_683 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_683, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_683, 'MERGE', CONCAT('stock topped for ', CAST(v_key_683 AS CHAR)));
  END;

  -- json block 684: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_684 JSON;
    DECLARE v_sku_684 VARCHAR(40);
    DECLARE v_tag_684 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_684, v_sku_684, v_tag_684
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_684,''), ' tag ', IFNULL(v_tag_684,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_684, 'tag', v_tag_684) AS CHAR)));
  END;

  -- cte block 685: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_685 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_685 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_685 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_685 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 686: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_686 VARCHAR(10);
    DECLARE v_amt_686 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_686 FROM erp_order;
    SET v_band_686 = CASE
        WHEN v_amt_686 >= 10000 THEN 'HIGH'
        WHEN v_amt_686 >= 1000  THEN 'MED'
        WHEN v_amt_686 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_686, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 687: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_687 INT DEFAULT 0;
    DECLARE v_j_687 INT DEFAULT 0;
    DECLARE v_rc_687 INT DEFAULT 0;
    REPEAT
      SET v_i_687 = v_i_687 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R687'), v_i_687)
        ON DUPLICATE KEY UPDATE tick = v_i_687;
    UNTIL v_i_687 >= 3 END REPEAT;
    WHILE v_j_687 < 3 DO
      SET v_j_687 = v_j_687 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_687 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_687 + v_j_687, 'ITER',
            CONCAT('i ', CAST(v_i_687 AS CHAR), ' j ', CAST(v_j_687 AS CHAR),
                   ' diag ', CAST(v_rc_687 AS CHAR)));
  END;

  -- analytics block 688: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_688 INT DEFAULT 0;
    DECLARE v_amt_688 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_688 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_688 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_688, v_amt_688, v_avg_688, v_max_688
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_688 = v_amt_688 + erp_fn_tax_amount(v_amt_688, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_688, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_688 AS CHAR), ' avg ', CAST(v_avg_688 AS CHAR),
                   ' max ', CAST(v_max_688 AS CHAR)));
  END;

  -- reconcile block 689: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_689 INT DEFAULT 0;
    DECLARE v_pid_689 INT;
    DECLARE v_oh_689 DECIMAL(18,4);
    DECLARE v_av_689 DECIMAL(18,4);
    DECLARE cur_689 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_689 = 1;
    OPEN cur_689;
    rl_689: LOOP
      FETCH cur_689 INTO v_pid_689, v_oh_689;
      IF v_fin_689 = 1 THEN LEAVE rl_689; END IF;
      SET v_av_689 = erp_fn_available_qty(v_pid_689, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_689, 1, 'RECON', CAST(v_oh_689 - v_av_689 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_689 AS CHAR));
    END LOOP;
    CLOSE cur_689;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_689,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_689,0) AS CHAR)));
  END;

  -- dynamic-sql block 690: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_690 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_690 VARCHAR(64) DEFAULT 'status';
    SET @dsql_690 = CONCAT('SELECT COUNT(*) INTO @dcnt_690 FROM ', v_tbl_690,
                          ' WHERE ', v_col_690, ' = ?');
    SET @dparm_690 = 'NEW';
    PREPARE pst_690 FROM @dsql_690;
    EXECUTE pst_690 USING @dparm_690;
    DEALLOCATE PREPARE pst_690;
    SET @dupd_690 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_690 = 100;
    PREPARE pud_690 FROM @dupd_690;
    EXECUTE pud_690 USING @doid_690;
    DEALLOCATE PREPARE pud_690;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_690,0), 'COUNT',
            CONCAT('tbl ', v_tbl_690, ' col ', v_col_690));
  END;

  -- recursive block 691: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_691 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_691 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_691;
  END;

  -- reprice block 692: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_692 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_692;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_692, 'UPDATE', CONCAT('rows ', CAST(v_rows_692 AS CHAR)));
  END;

  -- validation block 693: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_693 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_693
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_693 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_693, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_693 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_693, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 694: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_694 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_694 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_694 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_694 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_694 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_694 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_694 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_694 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_694 AS CHAR), ' cr ', CAST(v_cr_694 AS CHAR),
                   ' dr ', CAST(v_dr_694 AS CHAR), ' tot ', CAST(v_tot_694 AS CHAR)));
  END;

  -- invoice rollup block 695: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_695 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_695 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_695
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_695
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_695 AS CHAR), ' paid ', CAST(v_paid_695 AS CHAR)));
  END;

  -- gl reconciliation block 696: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_696 INT DEFAULT 0;
    DECLARE v_acct_696 INT;
    DECLARE v_dr_696 DECIMAL(18,2);
    DECLARE v_cr_696 DECIMAL(18,2);
    DECLARE gcur_696 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_696 = 1;
    OPEN gcur_696;
    gl_696: LOOP
      FETCH gcur_696 INTO v_acct_696, v_dr_696, v_cr_696;
      IF v_gfin_696 = 1 THEN LEAVE gl_696; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_696, 'BALANCE',
              CONCAT('net ', CAST(v_dr_696 - v_cr_696 AS CHAR)));
    END LOOP;
    CLOSE gcur_696;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_allocate_inventory  [procedure]
CREATE PROCEDURE erp_usp_allocate_inventory(IN p_order_id INT)
BEGIN
  DECLARE v_lines INT DEFAULT 0;
  SELECT COUNT(*) INTO v_lines FROM erp_order_line WHERE order_id = p_order_id;
  CALL erp_usp_reserve_stock(p_order_id);
  CALL erp_usp_audit_log('ALLOC', p_order_id, 'ALLOCATE', CONCAT('lines ', CAST(v_lines AS CHAR)));

  -- transaction block 697: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_697;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_697;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 697, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 698: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_698;
    CREATE TEMPORARY TABLE tmp_agg_698 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_698 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_698 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_698;
  END;

  -- upsert block 699: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_699 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_699, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_699, 'MERGE', CONCAT('stock topped for ', CAST(v_key_699 AS CHAR)));
  END;

  -- json block 700: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_700 JSON;
    DECLARE v_sku_700 VARCHAR(40);
    DECLARE v_tag_700 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_700, v_sku_700, v_tag_700
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_700,''), ' tag ', IFNULL(v_tag_700,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_700, 'tag', v_tag_700) AS CHAR)));
  END;

  -- cte block 701: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_701 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_701 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_701 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_701 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 702: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_702 VARCHAR(10);
    DECLARE v_amt_702 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_702 FROM erp_order;
    SET v_band_702 = CASE
        WHEN v_amt_702 >= 10000 THEN 'HIGH'
        WHEN v_amt_702 >= 1000  THEN 'MED'
        WHEN v_amt_702 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_702, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 703: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_703 INT DEFAULT 0;
    DECLARE v_j_703 INT DEFAULT 0;
    DECLARE v_rc_703 INT DEFAULT 0;
    REPEAT
      SET v_i_703 = v_i_703 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R703'), v_i_703)
        ON DUPLICATE KEY UPDATE tick = v_i_703;
    UNTIL v_i_703 >= 3 END REPEAT;
    WHILE v_j_703 < 3 DO
      SET v_j_703 = v_j_703 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_703 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_703 + v_j_703, 'ITER',
            CONCAT('i ', CAST(v_i_703 AS CHAR), ' j ', CAST(v_j_703 AS CHAR),
                   ' diag ', CAST(v_rc_703 AS CHAR)));
  END;

  -- analytics block 704: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_704 INT DEFAULT 0;
    DECLARE v_amt_704 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_704 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_704 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_704, v_amt_704, v_avg_704, v_max_704
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_704 = v_amt_704 + erp_fn_tax_amount(v_amt_704, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_704, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_704 AS CHAR), ' avg ', CAST(v_avg_704 AS CHAR),
                   ' max ', CAST(v_max_704 AS CHAR)));
  END;

  -- reconcile block 705: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_705 INT DEFAULT 0;
    DECLARE v_pid_705 INT;
    DECLARE v_oh_705 DECIMAL(18,4);
    DECLARE v_av_705 DECIMAL(18,4);
    DECLARE cur_705 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_705 = 1;
    OPEN cur_705;
    rl_705: LOOP
      FETCH cur_705 INTO v_pid_705, v_oh_705;
      IF v_fin_705 = 1 THEN LEAVE rl_705; END IF;
      SET v_av_705 = erp_fn_available_qty(v_pid_705, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_705, 1, 'RECON', CAST(v_oh_705 - v_av_705 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_705 AS CHAR));
    END LOOP;
    CLOSE cur_705;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_705,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_705,0) AS CHAR)));
  END;

  -- dynamic-sql block 706: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_706 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_706 VARCHAR(64) DEFAULT 'status';
    SET @dsql_706 = CONCAT('SELECT COUNT(*) INTO @dcnt_706 FROM ', v_tbl_706,
                          ' WHERE ', v_col_706, ' = ?');
    SET @dparm_706 = 'NEW';
    PREPARE pst_706 FROM @dsql_706;
    EXECUTE pst_706 USING @dparm_706;
    DEALLOCATE PREPARE pst_706;
    SET @dupd_706 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_706 = 100;
    PREPARE pud_706 FROM @dupd_706;
    EXECUTE pud_706 USING @doid_706;
    DEALLOCATE PREPARE pud_706;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_706,0), 'COUNT',
            CONCAT('tbl ', v_tbl_706, ' col ', v_col_706));
  END;

  -- recursive block 707: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_707 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_707 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_707;
  END;

  -- reprice block 708: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_708 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_708;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_708, 'UPDATE', CONCAT('rows ', CAST(v_rows_708 AS CHAR)));
  END;

  -- validation block 709: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_709 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_709
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_709 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_709, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_709 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_709, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 710: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_710 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_710 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_710 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_710 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_710 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_710 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_710 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_710 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_710 AS CHAR), ' cr ', CAST(v_cr_710 AS CHAR),
                   ' dr ', CAST(v_dr_710 AS CHAR), ' tot ', CAST(v_tot_710 AS CHAR)));
  END;

  -- invoice rollup block 711: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_711 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_711 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_711
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_711
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_711 AS CHAR), ' paid ', CAST(v_paid_711 AS CHAR)));
  END;

  -- gl reconciliation block 712: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_712 INT DEFAULT 0;
    DECLARE v_acct_712 INT;
    DECLARE v_dr_712 DECIMAL(18,2);
    DECLARE v_cr_712 DECIMAL(18,2);
    DECLARE gcur_712 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_712 = 1;
    OPEN gcur_712;
    gl_712: LOOP
      FETCH gcur_712 INTO v_acct_712, v_dr_712, v_cr_712;
      IF v_gfin_712 = 1 THEN LEAVE gl_712; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_712, 'BALANCE',
              CONCAT('net ', CAST(v_dr_712 - v_cr_712 AS CHAR)));
    END LOOP;
    CLOSE gcur_712;
  END;

  -- transaction block 713: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_713;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_713;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 713, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 714: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_714;
    CREATE TEMPORARY TABLE tmp_agg_714 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_714 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_714 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_714;
  END;

  -- upsert block 715: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_715 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_715, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_715, 'MERGE', CONCAT('stock topped for ', CAST(v_key_715 AS CHAR)));
  END;

