  BEGIN
    DECLARE v_doc_716 JSON;
    DECLARE v_sku_716 VARCHAR(40);
    DECLARE v_tag_716 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_716, v_sku_716, v_tag_716
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_716,''), ' tag ', IFNULL(v_tag_716,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_716, 'tag', v_tag_716) AS CHAR)));
  END;

  -- cte block 717: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_717 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_717 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_717 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_717 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 718: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_718 VARCHAR(10);
    DECLARE v_amt_718 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_718 FROM erp_order;
    SET v_band_718 = CASE
        WHEN v_amt_718 >= 10000 THEN 'HIGH'
        WHEN v_amt_718 >= 1000  THEN 'MED'
        WHEN v_amt_718 > 0      THEN 'LOW'
        ELSE 'ZERO'
