  -- repeat/while block 719: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_719 INT DEFAULT 0;
    DECLARE v_j_719 INT DEFAULT 0;
    DECLARE v_rc_719 INT DEFAULT 0;
    REPEAT
