  -- reconcile block 721: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_721 INT DEFAULT 0;
    DECLARE v_pid_721 INT;
    DECLARE v_oh_721 DECIMAL(18,4);
    DECLARE v_av_721 DECIMAL(18,4);
    DECLARE cur_721 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
