  -- dynamic-sql block 722: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_722 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_722 VARCHAR(64) DEFAULT 'status';
    SET @dsql_722 = CONCAT('SELECT COUNT(*) INTO @dcnt_722 FROM ', v_tbl_722,
                          ' WHERE ', v_col_722, ' = ?');
    SET @dparm_722 = 'NEW';
    PREPARE pst_722 FROM @dsql_722;
    EXECUTE pst_722 USING @dparm_722;
    DEALLOCATE PREPARE pst_722;
    SET @dupd_722 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_722 = 100;
    PREPARE pud_722 FROM @dupd_722;
    EXECUTE pud_722 USING @doid_722;
    DEALLOCATE PREPARE pud_722;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_722,0), 'COUNT',
            CONCAT('tbl ', v_tbl_722, ' col ', v_col_722));
  END;

  -- recursive block 723: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_723 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_723 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_723;
  END;

  -- reprice block 724: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_724 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_724;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_724, 'UPDATE', CONCAT('rows ', CAST(v_rows_724 AS CHAR)));
  END;

  -- validation block 725: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_725 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_725
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_725 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_725, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_725 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_725, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 726: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_726 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_726 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_726 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_726 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_726 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_726 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_726 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_726 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_726 AS CHAR), ' cr ', CAST(v_cr_726 AS CHAR),
                   ' dr ', CAST(v_dr_726 AS CHAR), ' tot ', CAST(v_tot_726 AS CHAR)));
  END;

  -- invoice rollup block 727: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_727 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_727 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_727
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_727
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_727 AS CHAR), ' paid ', CAST(v_paid_727 AS CHAR)));
  END;

  -- gl reconciliation block 728: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_728 INT DEFAULT 0;
    DECLARE v_acct_728 INT;
    DECLARE v_dr_728 DECIMAL(18,2);
    DECLARE v_cr_728 DECIMAL(18,2);
    DECLARE gcur_728 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_728 = 1;
    OPEN gcur_728;
    gl_728: LOOP
      FETCH gcur_728 INTO v_acct_728, v_dr_728, v_cr_728;
      IF v_gfin_728 = 1 THEN LEAVE gl_728; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_728, 'BALANCE',
              CONCAT('net ', CAST(v_dr_728 - v_cr_728 AS CHAR)));
    END LOOP;
    CLOSE gcur_728;
  END;

  -- transaction block 729: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_729;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_729;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 729, 'COMMIT', 'savepoint block committed');
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_process_order  [procedure]
CREATE PROCEDURE erp_usp_process_order(IN p_order_id INT)
BEGIN
  DECLARE v_total DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cust INT DEFAULT 0;
  DECLARE v_ok INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('ORDER', p_order_id, 'ERROR', 'process_order failed');
  END;
  START TRANSACTION;
  SELECT customer_id INTO v_cust FROM erp_order WHERE order_id = p_order_id;
  CALL erp_usp_check_credit(v_cust, v_ok);
  SET v_total = erp_fn_order_total(p_order_id);
  UPDATE erp_order SET total_amount = v_total, status = 'PROCESSING'
   WHERE order_id = p_order_id;
  CALL erp_usp_allocate_inventory(p_order_id);
  COMMIT;
  CALL erp_usp_audit_log('ORDER', p_order_id, 'PROCESS', CONCAT('total ', CAST(v_total AS CHAR)));

  -- temp-table block 730: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_730;
    CREATE TEMPORARY TABLE tmp_agg_730 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_730 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_730 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_730;
  END;

  -- upsert block 731: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_731 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_731, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_731, 'MERGE', CONCAT('stock topped for ', CAST(v_key_731 AS CHAR)));
  END;

  -- json block 732: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_732 JSON;
    DECLARE v_sku_732 VARCHAR(40);
    DECLARE v_tag_732 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_732, v_sku_732, v_tag_732
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_732,''), ' tag ', IFNULL(v_tag_732,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_732, 'tag', v_tag_732) AS CHAR)));
  END;

  -- cte block 733: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_733 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_733 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_733 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_733 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 734: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_734 VARCHAR(10);
    DECLARE v_amt_734 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_734 FROM erp_order;
    SET v_band_734 = CASE
        WHEN v_amt_734 >= 10000 THEN 'HIGH'
        WHEN v_amt_734 >= 1000  THEN 'MED'
        WHEN v_amt_734 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_734, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 735: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_735 INT DEFAULT 0;
    DECLARE v_j_735 INT DEFAULT 0;
    DECLARE v_rc_735 INT DEFAULT 0;
    REPEAT
      SET v_i_735 = v_i_735 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R735'), v_i_735)
        ON DUPLICATE KEY UPDATE tick = v_i_735;
    UNTIL v_i_735 >= 3 END REPEAT;
    WHILE v_j_735 < 3 DO
      SET v_j_735 = v_j_735 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_735 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_735 + v_j_735, 'ITER',
            CONCAT('i ', CAST(v_i_735 AS CHAR), ' j ', CAST(v_j_735 AS CHAR),
                   ' diag ', CAST(v_rc_735 AS CHAR)));
  END;

  -- analytics block 736: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_736 INT DEFAULT 0;
    DECLARE v_amt_736 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_736 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_736 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_736, v_amt_736, v_avg_736, v_max_736
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_736 = v_amt_736 + erp_fn_tax_amount(v_amt_736, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_736, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_736 AS CHAR), ' avg ', CAST(v_avg_736 AS CHAR),
                   ' max ', CAST(v_max_736 AS CHAR)));
  END;

  -- reconcile block 737: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_737 INT DEFAULT 0;
    DECLARE v_pid_737 INT;
    DECLARE v_oh_737 DECIMAL(18,4);
    DECLARE v_av_737 DECIMAL(18,4);
    DECLARE cur_737 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_737 = 1;
    OPEN cur_737;
    rl_737: LOOP
      FETCH cur_737 INTO v_pid_737, v_oh_737;
      IF v_fin_737 = 1 THEN LEAVE rl_737; END IF;
      SET v_av_737 = erp_fn_available_qty(v_pid_737, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_737, 1, 'RECON', CAST(v_oh_737 - v_av_737 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_737 AS CHAR));
    END LOOP;
    CLOSE cur_737;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_737,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_737,0) AS CHAR)));
  END;

  -- dynamic-sql block 738: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_738 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_738 VARCHAR(64) DEFAULT 'status';
    SET @dsql_738 = CONCAT('SELECT COUNT(*) INTO @dcnt_738 FROM ', v_tbl_738,
                          ' WHERE ', v_col_738, ' = ?');
    SET @dparm_738 = 'NEW';
    PREPARE pst_738 FROM @dsql_738;
    EXECUTE pst_738 USING @dparm_738;
    DEALLOCATE PREPARE pst_738;
    SET @dupd_738 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_738 = 100;
    PREPARE pud_738 FROM @dupd_738;
    EXECUTE pud_738 USING @doid_738;
    DEALLOCATE PREPARE pud_738;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_738,0), 'COUNT',
            CONCAT('tbl ', v_tbl_738, ' col ', v_col_738));
  END;

  -- recursive block 739: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_739 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_739 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_739;
  END;

  -- reprice block 740: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_740 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_740;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_740, 'UPDATE', CONCAT('rows ', CAST(v_rows_740 AS CHAR)));
  END;

  -- validation block 741: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_741 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_741
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_741 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_741, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_741 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_741, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 742: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_742 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_742 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_742 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_742 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_742 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_742 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_742 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_742 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_742 AS CHAR), ' cr ', CAST(v_cr_742 AS CHAR),
                   ' dr ', CAST(v_dr_742 AS CHAR), ' tot ', CAST(v_tot_742 AS CHAR)));
  END;

  -- invoice rollup block 743: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_743 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_743 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_743
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_743
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_743 AS CHAR), ' paid ', CAST(v_paid_743 AS CHAR)));
  END;

  -- gl reconciliation block 744: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_744 INT DEFAULT 0;
    DECLARE v_acct_744 INT;
    DECLARE v_dr_744 DECIMAL(18,2);
    DECLARE v_cr_744 DECIMAL(18,2);
    DECLARE gcur_744 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_744 = 1;
    OPEN gcur_744;
    gl_744: LOOP
      FETCH gcur_744 INTO v_acct_744, v_dr_744, v_cr_744;
      IF v_gfin_744 = 1 THEN LEAVE gl_744; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_744, 'BALANCE',
              CONCAT('net ', CAST(v_dr_744 - v_cr_744 AS CHAR)));
    END LOOP;
    CLOSE gcur_744;
  END;

  -- transaction block 745: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_745;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_745;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 745, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 746: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_746;
    CREATE TEMPORARY TABLE tmp_agg_746 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_746 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_746 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_746;
  END;

  -- upsert block 747: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_747 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_747, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_747, 'MERGE', CONCAT('stock topped for ', CAST(v_key_747 AS CHAR)));
  END;

  -- json block 748: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_748 JSON;
    DECLARE v_sku_748 VARCHAR(40);
    DECLARE v_tag_748 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_748, v_sku_748, v_tag_748
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_748,''), ' tag ', IFNULL(v_tag_748,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_748, 'tag', v_tag_748) AS CHAR)));
  END;

  -- cte block 749: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_749 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_749 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_749 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_749 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 750: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_750 VARCHAR(10);
    DECLARE v_amt_750 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_750 FROM erp_order;
    SET v_band_750 = CASE
        WHEN v_amt_750 >= 10000 THEN 'HIGH'
        WHEN v_amt_750 >= 1000  THEN 'MED'
        WHEN v_amt_750 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_750, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 751: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_751 INT DEFAULT 0;
    DECLARE v_j_751 INT DEFAULT 0;
    DECLARE v_rc_751 INT DEFAULT 0;
    REPEAT
      SET v_i_751 = v_i_751 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R751'), v_i_751)
        ON DUPLICATE KEY UPDATE tick = v_i_751;
    UNTIL v_i_751 >= 3 END REPEAT;
    WHILE v_j_751 < 3 DO
      SET v_j_751 = v_j_751 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_751 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_751 + v_j_751, 'ITER',
            CONCAT('i ', CAST(v_i_751 AS CHAR), ' j ', CAST(v_j_751 AS CHAR),
                   ' diag ', CAST(v_rc_751 AS CHAR)));
  END;

  -- analytics block 752: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_752 INT DEFAULT 0;
    DECLARE v_amt_752 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_752 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_752 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_752, v_amt_752, v_avg_752, v_max_752
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_752 = v_amt_752 + erp_fn_tax_amount(v_amt_752, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_752, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_752 AS CHAR), ' avg ', CAST(v_avg_752 AS CHAR),
                   ' max ', CAST(v_max_752 AS CHAR)));
  END;

  -- reconcile block 753: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_753 INT DEFAULT 0;
    DECLARE v_pid_753 INT;
    DECLARE v_oh_753 DECIMAL(18,4);
    DECLARE v_av_753 DECIMAL(18,4);
    DECLARE cur_753 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_753 = 1;
    OPEN cur_753;
    rl_753: LOOP
      FETCH cur_753 INTO v_pid_753, v_oh_753;
      IF v_fin_753 = 1 THEN LEAVE rl_753; END IF;
      SET v_av_753 = erp_fn_available_qty(v_pid_753, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_753, 1, 'RECON', CAST(v_oh_753 - v_av_753 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_753 AS CHAR));
    END LOOP;
    CLOSE cur_753;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_753,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_753,0) AS CHAR)));
  END;

  -- dynamic-sql block 754: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_754 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_754 VARCHAR(64) DEFAULT 'status';
    SET @dsql_754 = CONCAT('SELECT COUNT(*) INTO @dcnt_754 FROM ', v_tbl_754,
                          ' WHERE ', v_col_754, ' = ?');
    SET @dparm_754 = 'NEW';
    PREPARE pst_754 FROM @dsql_754;
    EXECUTE pst_754 USING @dparm_754;
    DEALLOCATE PREPARE pst_754;
    SET @dupd_754 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_754 = 100;
    PREPARE pud_754 FROM @dupd_754;
    EXECUTE pud_754 USING @doid_754;
    DEALLOCATE PREPARE pud_754;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_754,0), 'COUNT',
            CONCAT('tbl ', v_tbl_754, ' col ', v_col_754));
  END;

  -- recursive block 755: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_755 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_755 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_755;
  END;

  -- reprice block 756: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_756 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_756;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_756, 'UPDATE', CONCAT('rows ', CAST(v_rows_756 AS CHAR)));
  END;

  -- validation block 757: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_757 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_757
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_757 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_757, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_757 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_757, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 758: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_758 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_758 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_758 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_758 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_758 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_758 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_758 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_758 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_758 AS CHAR), ' cr ', CAST(v_cr_758 AS CHAR),
                   ' dr ', CAST(v_dr_758 AS CHAR), ' tot ', CAST(v_tot_758 AS CHAR)));
  END;

  -- invoice rollup block 759: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_759 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_759 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_759
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_759
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_759 AS CHAR), ' paid ', CAST(v_paid_759 AS CHAR)));
  END;

  -- gl reconciliation block 760: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_760 INT DEFAULT 0;
    DECLARE v_acct_760 INT;
    DECLARE v_dr_760 DECIMAL(18,2);
    DECLARE v_cr_760 DECIMAL(18,2);
    DECLARE gcur_760 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_760 = 1;
    OPEN gcur_760;
    gl_760: LOOP
      FETCH gcur_760 INTO v_acct_760, v_dr_760, v_cr_760;
      IF v_gfin_760 = 1 THEN LEAVE gl_760; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_760, 'BALANCE',
              CONCAT('net ', CAST(v_dr_760 - v_cr_760 AS CHAR)));
    END LOOP;
    CLOSE gcur_760;
  END;

  -- transaction block 761: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_761;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_761;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 761, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 762: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_762;
    CREATE TEMPORARY TABLE tmp_agg_762 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_762 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_762 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_762;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_process_all_orders  [procedure]
CREATE PROCEDURE erp_usp_process_all_orders()
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_oid INT;
  DECLARE v_count INT DEFAULT 0;
  DECLARE cur_orders CURSOR FOR
    SELECT order_id FROM erp_order WHERE status = 'NEW' ORDER BY order_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  OPEN cur_orders;
  order_loop: LOOP
    FETCH cur_orders INTO v_oid;
    IF v_done = 1 THEN LEAVE order_loop; END IF;
    SET v_count = v_count + 1;
    CALL erp_usp_process_order(v_oid);
  END LOOP;
  CLOSE cur_orders;
  CALL erp_usp_audit_log('BATCH', v_count, 'PROCESS_ALL', CONCAT('orders ', CAST(v_count AS CHAR)));

  -- upsert block 763: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_763 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_763, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_763, 'MERGE', CONCAT('stock topped for ', CAST(v_key_763 AS CHAR)));
  END;

  -- json block 764: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_764 JSON;
    DECLARE v_sku_764 VARCHAR(40);
    DECLARE v_tag_764 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_764, v_sku_764, v_tag_764
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_764,''), ' tag ', IFNULL(v_tag_764,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_764, 'tag', v_tag_764) AS CHAR)));
  END;

  -- cte block 765: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_765 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_765 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_765 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_765 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 766: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_766 VARCHAR(10);
    DECLARE v_amt_766 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_766 FROM erp_order;
    SET v_band_766 = CASE
        WHEN v_amt_766 >= 10000 THEN 'HIGH'
        WHEN v_amt_766 >= 1000  THEN 'MED'
        WHEN v_amt_766 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_766, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 767: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_767 INT DEFAULT 0;
    DECLARE v_j_767 INT DEFAULT 0;
    DECLARE v_rc_767 INT DEFAULT 0;
    REPEAT
      SET v_i_767 = v_i_767 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R767'), v_i_767)
        ON DUPLICATE KEY UPDATE tick = v_i_767;
    UNTIL v_i_767 >= 3 END REPEAT;
    WHILE v_j_767 < 3 DO
      SET v_j_767 = v_j_767 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_767 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_767 + v_j_767, 'ITER',
            CONCAT('i ', CAST(v_i_767 AS CHAR), ' j ', CAST(v_j_767 AS CHAR),
                   ' diag ', CAST(v_rc_767 AS CHAR)));
  END;

  -- analytics block 768: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_768 INT DEFAULT 0;
    DECLARE v_amt_768 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_768 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_768 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_768, v_amt_768, v_avg_768, v_max_768
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_768 = v_amt_768 + erp_fn_tax_amount(v_amt_768, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_768, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_768 AS CHAR), ' avg ', CAST(v_avg_768 AS CHAR),
                   ' max ', CAST(v_max_768 AS CHAR)));
  END;

  -- reconcile block 769: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_769 INT DEFAULT 0;
    DECLARE v_pid_769 INT;
    DECLARE v_oh_769 DECIMAL(18,4);
    DECLARE v_av_769 DECIMAL(18,4);
    DECLARE cur_769 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_769 = 1;
    OPEN cur_769;
    rl_769: LOOP
      FETCH cur_769 INTO v_pid_769, v_oh_769;
      IF v_fin_769 = 1 THEN LEAVE rl_769; END IF;
      SET v_av_769 = erp_fn_available_qty(v_pid_769, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_769, 1, 'RECON', CAST(v_oh_769 - v_av_769 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_769 AS CHAR));
    END LOOP;
    CLOSE cur_769;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_769,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_769,0) AS CHAR)));
  END;

  -- dynamic-sql block 770: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_770 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_770 VARCHAR(64) DEFAULT 'status';
    SET @dsql_770 = CONCAT('SELECT COUNT(*) INTO @dcnt_770 FROM ', v_tbl_770,
                          ' WHERE ', v_col_770, ' = ?');
    SET @dparm_770 = 'NEW';
    PREPARE pst_770 FROM @dsql_770;
    EXECUTE pst_770 USING @dparm_770;
    DEALLOCATE PREPARE pst_770;
    SET @dupd_770 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_770 = 100;
    PREPARE pud_770 FROM @dupd_770;
    EXECUTE pud_770 USING @doid_770;
    DEALLOCATE PREPARE pud_770;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_770,0), 'COUNT',
            CONCAT('tbl ', v_tbl_770, ' col ', v_col_770));
  END;

  -- recursive block 771: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_771 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_771 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_771;
  END;

  -- reprice block 772: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_772 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_772;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_772, 'UPDATE', CONCAT('rows ', CAST(v_rows_772 AS CHAR)));
  END;

  -- validation block 773: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_773 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_773
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_773 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_773, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_773 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_773, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 774: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_774 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_774 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_774 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_774 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_774 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_774 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_774 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_774 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_774 AS CHAR), ' cr ', CAST(v_cr_774 AS CHAR),
                   ' dr ', CAST(v_dr_774 AS CHAR), ' tot ', CAST(v_tot_774 AS CHAR)));
  END;

  -- invoice rollup block 775: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_775 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_775 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_775
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_775
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_775 AS CHAR), ' paid ', CAST(v_paid_775 AS CHAR)));
  END;

  -- gl reconciliation block 776: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_776 INT DEFAULT 0;
    DECLARE v_acct_776 INT;
    DECLARE v_dr_776 DECIMAL(18,2);
    DECLARE v_cr_776 DECIMAL(18,2);
    DECLARE gcur_776 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_776 = 1;
    OPEN gcur_776;
    gl_776: LOOP
      FETCH gcur_776 INTO v_acct_776, v_dr_776, v_cr_776;
      IF v_gfin_776 = 1 THEN LEAVE gl_776; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_776, 'BALANCE',
              CONCAT('net ', CAST(v_dr_776 - v_cr_776 AS CHAR)));
    END LOOP;
    CLOSE gcur_776;
  END;

  -- transaction block 777: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_777;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_777;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 777, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 778: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_778;
    CREATE TEMPORARY TABLE tmp_agg_778 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_778 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_778 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_778;
  END;

  -- upsert block 779: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_779 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_779, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_779, 'MERGE', CONCAT('stock topped for ', CAST(v_key_779 AS CHAR)));
  END;

  -- json block 780: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_780 JSON;
    DECLARE v_sku_780 VARCHAR(40);
    DECLARE v_tag_780 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_780, v_sku_780, v_tag_780
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_780,''), ' tag ', IFNULL(v_tag_780,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_780, 'tag', v_tag_780) AS CHAR)));
  END;

  -- cte block 781: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_781 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_781 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_781 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_781 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 782: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_782 VARCHAR(10);
    DECLARE v_amt_782 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_782 FROM erp_order;
    SET v_band_782 = CASE
        WHEN v_amt_782 >= 10000 THEN 'HIGH'
        WHEN v_amt_782 >= 1000  THEN 'MED'
        WHEN v_amt_782 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_782, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 783: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_783 INT DEFAULT 0;
    DECLARE v_j_783 INT DEFAULT 0;
    DECLARE v_rc_783 INT DEFAULT 0;
    REPEAT
      SET v_i_783 = v_i_783 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R783'), v_i_783)
        ON DUPLICATE KEY UPDATE tick = v_i_783;
    UNTIL v_i_783 >= 3 END REPEAT;
    WHILE v_j_783 < 3 DO
      SET v_j_783 = v_j_783 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_783 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_783 + v_j_783, 'ITER',
            CONCAT('i ', CAST(v_i_783 AS CHAR), ' j ', CAST(v_j_783 AS CHAR),
                   ' diag ', CAST(v_rc_783 AS CHAR)));
  END;

  -- analytics block 784: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_784 INT DEFAULT 0;
    DECLARE v_amt_784 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_784 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_784 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_784, v_amt_784, v_avg_784, v_max_784
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_784 = v_amt_784 + erp_fn_tax_amount(v_amt_784, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_784, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_784 AS CHAR), ' avg ', CAST(v_avg_784 AS CHAR),
                   ' max ', CAST(v_max_784 AS CHAR)));
  END;

  -- reconcile block 785: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_785 INT DEFAULT 0;
    DECLARE v_pid_785 INT;
    DECLARE v_oh_785 DECIMAL(18,4);
    DECLARE v_av_785 DECIMAL(18,4);
    DECLARE cur_785 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_785 = 1;
    OPEN cur_785;
    rl_785: LOOP
      FETCH cur_785 INTO v_pid_785, v_oh_785;
      IF v_fin_785 = 1 THEN LEAVE rl_785; END IF;
      SET v_av_785 = erp_fn_available_qty(v_pid_785, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_785, 1, 'RECON', CAST(v_oh_785 - v_av_785 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_785 AS CHAR));
    END LOOP;
    CLOSE cur_785;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_785,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_785,0) AS CHAR)));
  END;

