  -- transaction block 793: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_793;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_793;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 793, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 794: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_794;
    CREATE TEMPORARY TABLE tmp_agg_794 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_794 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_794 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_794;
  END;

  -- upsert block 795: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_795 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_795, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_795, 'MERGE', CONCAT('stock topped for ', CAST(v_key_795 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_close_period  [procedure]
CREATE PROCEDURE erp_usp_close_period(IN p_period VARCHAR(7))
BEGIN
  DECLARE v_open INT DEFAULT 0;
  SELECT COUNT(*) INTO v_open FROM erp_order WHERE status IN ('NEW','PROCESSING');
  UPDATE erp_period SET closed = 1 WHERE period_code = p_period;
  CALL erp_usp_post_gl(9500, 0);
  CALL erp_usp_audit_log('PERIOD', v_open, 'CLOSE', CONCAT('period ', p_period));

  -- json block 796: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_796 JSON;
    DECLARE v_sku_796 VARCHAR(40);
    DECLARE v_tag_796 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_796, v_sku_796, v_tag_796
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_796,''), ' tag ', IFNULL(v_tag_796,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_796, 'tag', v_tag_796) AS CHAR)));
  END;

  -- cte block 797: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_797 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_797 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_797 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_797 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 798: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_798 VARCHAR(10);
    DECLARE v_amt_798 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_798 FROM erp_order;
    SET v_band_798 = CASE
        WHEN v_amt_798 >= 10000 THEN 'HIGH'
        WHEN v_amt_798 >= 1000  THEN 'MED'
        WHEN v_amt_798 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_798, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 799: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_799 INT DEFAULT 0;
    DECLARE v_j_799 INT DEFAULT 0;
    DECLARE v_rc_799 INT DEFAULT 0;
    REPEAT
      SET v_i_799 = v_i_799 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R799'), v_i_799)
        ON DUPLICATE KEY UPDATE tick = v_i_799;
    UNTIL v_i_799 >= 3 END REPEAT;
    WHILE v_j_799 < 3 DO
      SET v_j_799 = v_j_799 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_799 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_799 + v_j_799, 'ITER',
            CONCAT('i ', CAST(v_i_799 AS CHAR), ' j ', CAST(v_j_799 AS CHAR),
                   ' diag ', CAST(v_rc_799 AS CHAR)));
  END;

  -- analytics block 800: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_800 INT DEFAULT 0;
    DECLARE v_amt_800 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_800 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_800 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_800, v_amt_800, v_avg_800, v_max_800
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_800 = v_amt_800 + erp_fn_tax_amount(v_amt_800, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_800, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_800 AS CHAR), ' avg ', CAST(v_avg_800 AS CHAR),
                   ' max ', CAST(v_max_800 AS CHAR)));
  END;

  -- reconcile block 801: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_801 INT DEFAULT 0;
    DECLARE v_pid_801 INT;
    DECLARE v_oh_801 DECIMAL(18,4);
    DECLARE v_av_801 DECIMAL(18,4);
    DECLARE cur_801 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_801 = 1;
    OPEN cur_801;
    rl_801: LOOP
      FETCH cur_801 INTO v_pid_801, v_oh_801;
      IF v_fin_801 = 1 THEN LEAVE rl_801; END IF;
      SET v_av_801 = erp_fn_available_qty(v_pid_801, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_801, 1, 'RECON', CAST(v_oh_801 - v_av_801 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_801 AS CHAR));
    END LOOP;
    CLOSE cur_801;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_801,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_801,0) AS CHAR)));
  END;

  -- dynamic-sql block 802: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_802 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_802 VARCHAR(64) DEFAULT 'status';
    SET @dsql_802 = CONCAT('SELECT COUNT(*) INTO @dcnt_802 FROM ', v_tbl_802,
                          ' WHERE ', v_col_802, ' = ?');
    SET @dparm_802 = 'NEW';
    PREPARE pst_802 FROM @dsql_802;
    EXECUTE pst_802 USING @dparm_802;
    DEALLOCATE PREPARE pst_802;
    SET @dupd_802 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_802 = 100;
    PREPARE pud_802 FROM @dupd_802;
    EXECUTE pud_802 USING @doid_802;
    DEALLOCATE PREPARE pud_802;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_802,0), 'COUNT',
            CONCAT('tbl ', v_tbl_802, ' col ', v_col_802));
  END;

  -- recursive block 803: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_803 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_803 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_803;
  END;

  -- reprice block 804: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_804 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_804;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_804, 'UPDATE', CONCAT('rows ', CAST(v_rows_804 AS CHAR)));
  END;

  -- validation block 805: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_805 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_805
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_805 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_805, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_805 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_805, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 806: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_806 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_806 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_806 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_806 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_806 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_806 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_806 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_806 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_806 AS CHAR), ' cr ', CAST(v_cr_806 AS CHAR),
                   ' dr ', CAST(v_dr_806 AS CHAR), ' tot ', CAST(v_tot_806 AS CHAR)));
  END;

  -- invoice rollup block 807: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_807 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_807 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_807
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_807
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_807 AS CHAR), ' paid ', CAST(v_paid_807 AS CHAR)));
  END;

  -- gl reconciliation block 808: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_808 INT DEFAULT 0;
    DECLARE v_acct_808 INT;
    DECLARE v_dr_808 DECIMAL(18,2);
    DECLARE v_cr_808 DECIMAL(18,2);
    DECLARE gcur_808 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_808 = 1;
    OPEN gcur_808;
    gl_808: LOOP
      FETCH gcur_808 INTO v_acct_808, v_dr_808, v_cr_808;
      IF v_gfin_808 = 1 THEN LEAVE gl_808; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_808, 'BALANCE',
              CONCAT('net ', CAST(v_dr_808 - v_cr_808 AS CHAR)));
    END LOOP;
    CLOSE gcur_808;
  END;

  -- transaction block 809: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_809;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_809;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 809, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 810: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_810;
    CREATE TEMPORARY TABLE tmp_agg_810 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_810 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_810 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_810;
  END;

  -- upsert block 811: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_811 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_811, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_811, 'MERGE', CONCAT('stock topped for ', CAST(v_key_811 AS CHAR)));
  END;

  -- json block 812: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_812 JSON;
    DECLARE v_sku_812 VARCHAR(40);
    DECLARE v_tag_812 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_812, v_sku_812, v_tag_812
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_812,''), ' tag ', IFNULL(v_tag_812,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_812, 'tag', v_tag_812) AS CHAR)));
  END;

  -- cte block 813: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_813 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_813 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_813 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_813 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 814: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_814 VARCHAR(10);
    DECLARE v_amt_814 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_814 FROM erp_order;
    SET v_band_814 = CASE
        WHEN v_amt_814 >= 10000 THEN 'HIGH'
        WHEN v_amt_814 >= 1000  THEN 'MED'
        WHEN v_amt_814 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_814, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 815: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_815 INT DEFAULT 0;
    DECLARE v_j_815 INT DEFAULT 0;
    DECLARE v_rc_815 INT DEFAULT 0;
    REPEAT
      SET v_i_815 = v_i_815 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R815'), v_i_815)
        ON DUPLICATE KEY UPDATE tick = v_i_815;
    UNTIL v_i_815 >= 3 END REPEAT;
    WHILE v_j_815 < 3 DO
      SET v_j_815 = v_j_815 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_815 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_815 + v_j_815, 'ITER',
            CONCAT('i ', CAST(v_i_815 AS CHAR), ' j ', CAST(v_j_815 AS CHAR),
                   ' diag ', CAST(v_rc_815 AS CHAR)));
  END;

  -- analytics block 816: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_816 INT DEFAULT 0;
    DECLARE v_amt_816 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_816 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_816 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_816, v_amt_816, v_avg_816, v_max_816
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_816 = v_amt_816 + erp_fn_tax_amount(v_amt_816, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_816, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_816 AS CHAR), ' avg ', CAST(v_avg_816 AS CHAR),
                   ' max ', CAST(v_max_816 AS CHAR)));
  END;

  -- reconcile block 817: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_817 INT DEFAULT 0;
    DECLARE v_pid_817 INT;
    DECLARE v_oh_817 DECIMAL(18,4);
    DECLARE v_av_817 DECIMAL(18,4);
    DECLARE cur_817 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_817 = 1;
    OPEN cur_817;
    rl_817: LOOP
      FETCH cur_817 INTO v_pid_817, v_oh_817;
      IF v_fin_817 = 1 THEN LEAVE rl_817; END IF;
      SET v_av_817 = erp_fn_available_qty(v_pid_817, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_817, 1, 'RECON', CAST(v_oh_817 - v_av_817 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_817 AS CHAR));
    END LOOP;
    CLOSE cur_817;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_817,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_817,0) AS CHAR)));
  END;

  -- dynamic-sql block 818: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_818 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_818 VARCHAR(64) DEFAULT 'status';
    SET @dsql_818 = CONCAT('SELECT COUNT(*) INTO @dcnt_818 FROM ', v_tbl_818,
                          ' WHERE ', v_col_818, ' = ?');
    SET @dparm_818 = 'NEW';
    PREPARE pst_818 FROM @dsql_818;
    EXECUTE pst_818 USING @dparm_818;
    DEALLOCATE PREPARE pst_818;
    SET @dupd_818 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_818 = 100;
    PREPARE pud_818 FROM @dupd_818;
    EXECUTE pud_818 USING @doid_818;
    DEALLOCATE PREPARE pud_818;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_818,0), 'COUNT',
            CONCAT('tbl ', v_tbl_818, ' col ', v_col_818));
  END;

  -- recursive block 819: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_819 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_819 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_819;
  END;

  -- reprice block 820: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_820 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_820;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_820, 'UPDATE', CONCAT('rows ', CAST(v_rows_820 AS CHAR)));
  END;

  -- validation block 821: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_821 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_821
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_821 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_821, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_821 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_821, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 822: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_822 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_822 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_822 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_822 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_822 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_822 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_822 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_822 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_822 AS CHAR), ' cr ', CAST(v_cr_822 AS CHAR),
                   ' dr ', CAST(v_dr_822 AS CHAR), ' tot ', CAST(v_tot_822 AS CHAR)));
  END;

  -- invoice rollup block 823: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_823 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_823 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_823
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_823
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_823 AS CHAR), ' paid ', CAST(v_paid_823 AS CHAR)));
  END;

  -- gl reconciliation block 824: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_824 INT DEFAULT 0;
    DECLARE v_acct_824 INT;
    DECLARE v_dr_824 DECIMAL(18,2);
    DECLARE v_cr_824 DECIMAL(18,2);
    DECLARE gcur_824 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_824 = 1;
    OPEN gcur_824;
    gl_824: LOOP
      FETCH gcur_824 INTO v_acct_824, v_dr_824, v_cr_824;
      IF v_gfin_824 = 1 THEN LEAVE gl_824; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_824, 'BALANCE',
              CONCAT('net ', CAST(v_dr_824 - v_cr_824 AS CHAR)));
    END LOOP;
    CLOSE gcur_824;
  END;

  -- transaction block 825: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_825;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_825;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 825, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 826: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_826;
    CREATE TEMPORARY TABLE tmp_agg_826 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_826 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_826 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_826;
  END;

  -- upsert block 827: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_827 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_827, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_827, 'MERGE', CONCAT('stock topped for ', CAST(v_key_827 AS CHAR)));
  END;

  -- json block 828: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_828 JSON;
    DECLARE v_sku_828 VARCHAR(40);
    DECLARE v_tag_828 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_828, v_sku_828, v_tag_828
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_828,''), ' tag ', IFNULL(v_tag_828,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_828, 'tag', v_tag_828) AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_dynamic_report  [procedure]
CREATE PROCEDURE erp_usp_dynamic_report(IN p_table VARCHAR(64), IN p_status VARCHAR(20), OUT p_rows INT)
BEGIN
  SET @rsql = CONCAT('SELECT COUNT(*) INTO @rcnt FROM ', p_table, ' WHERE status = ?');
  SET @rst = p_status;
  PREPARE rstmt FROM @rsql;
  EXECUTE rstmt USING @rst;
  DEALLOCATE PREPARE rstmt;
  SET p_rows = IFNULL(@rcnt, 0);
  CALL erp_usp_audit_log('REPORT', p_rows, 'DYNAMIC', CONCAT('tbl ', p_table, ' st ', p_status));

  -- cte block 829: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_829 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_829 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_829 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_829 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 830: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_830 VARCHAR(10);
    DECLARE v_amt_830 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_830 FROM erp_order;
    SET v_band_830 = CASE
        WHEN v_amt_830 >= 10000 THEN 'HIGH'
        WHEN v_amt_830 >= 1000  THEN 'MED'
        WHEN v_amt_830 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_830, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 831: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_831 INT DEFAULT 0;
    DECLARE v_j_831 INT DEFAULT 0;
    DECLARE v_rc_831 INT DEFAULT 0;
    REPEAT
      SET v_i_831 = v_i_831 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R831'), v_i_831)
        ON DUPLICATE KEY UPDATE tick = v_i_831;
    UNTIL v_i_831 >= 3 END REPEAT;
    WHILE v_j_831 < 3 DO
      SET v_j_831 = v_j_831 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_831 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_831 + v_j_831, 'ITER',
            CONCAT('i ', CAST(v_i_831 AS CHAR), ' j ', CAST(v_j_831 AS CHAR),
                   ' diag ', CAST(v_rc_831 AS CHAR)));
  END;

  -- analytics block 832: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_832 INT DEFAULT 0;
    DECLARE v_amt_832 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_832 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_832 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_832, v_amt_832, v_avg_832, v_max_832
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_832 = v_amt_832 + erp_fn_tax_amount(v_amt_832, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_832, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_832 AS CHAR), ' avg ', CAST(v_avg_832 AS CHAR),
                   ' max ', CAST(v_max_832 AS CHAR)));
  END;

  -- reconcile block 833: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_833 INT DEFAULT 0;
    DECLARE v_pid_833 INT;
    DECLARE v_oh_833 DECIMAL(18,4);
    DECLARE v_av_833 DECIMAL(18,4);
    DECLARE cur_833 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_833 = 1;
    OPEN cur_833;
    rl_833: LOOP
      FETCH cur_833 INTO v_pid_833, v_oh_833;
      IF v_fin_833 = 1 THEN LEAVE rl_833; END IF;
      SET v_av_833 = erp_fn_available_qty(v_pid_833, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_833, 1, 'RECON', CAST(v_oh_833 - v_av_833 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_833 AS CHAR));
    END LOOP;
    CLOSE cur_833;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_833,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_833,0) AS CHAR)));
  END;

  -- dynamic-sql block 834: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_834 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_834 VARCHAR(64) DEFAULT 'status';
    SET @dsql_834 = CONCAT('SELECT COUNT(*) INTO @dcnt_834 FROM ', v_tbl_834,
                          ' WHERE ', v_col_834, ' = ?');
    SET @dparm_834 = 'NEW';
    PREPARE pst_834 FROM @dsql_834;
    EXECUTE pst_834 USING @dparm_834;
    DEALLOCATE PREPARE pst_834;
    SET @dupd_834 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_834 = 100;
    PREPARE pud_834 FROM @dupd_834;
    EXECUTE pud_834 USING @doid_834;
    DEALLOCATE PREPARE pud_834;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_834,0), 'COUNT',
            CONCAT('tbl ', v_tbl_834, ' col ', v_col_834));
  END;

  -- recursive block 835: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_835 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_835 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_835;
  END;

  -- reprice block 836: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_836 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_836;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_836, 'UPDATE', CONCAT('rows ', CAST(v_rows_836 AS CHAR)));
  END;

  -- validation block 837: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_837 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_837
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_837 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_837, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_837 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_837, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 838: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_838 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_838 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_838 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_838 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_838 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_838 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_838 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_838 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_838 AS CHAR), ' cr ', CAST(v_cr_838 AS CHAR),
                   ' dr ', CAST(v_dr_838 AS CHAR), ' tot ', CAST(v_tot_838 AS CHAR)));
  END;

  -- invoice rollup block 839: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_839 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_839 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_839
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_839
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_839 AS CHAR), ' paid ', CAST(v_paid_839 AS CHAR)));
  END;

  -- gl reconciliation block 840: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_840 INT DEFAULT 0;
    DECLARE v_acct_840 INT;
    DECLARE v_dr_840 DECIMAL(18,2);
    DECLARE v_cr_840 DECIMAL(18,2);
    DECLARE gcur_840 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_840 = 1;
    OPEN gcur_840;
    gl_840: LOOP
      FETCH gcur_840 INTO v_acct_840, v_dr_840, v_cr_840;
      IF v_gfin_840 = 1 THEN LEAVE gl_840; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_840, 'BALANCE',
              CONCAT('net ', CAST(v_dr_840 - v_cr_840 AS CHAR)));
    END LOOP;
    CLOSE gcur_840;
  END;

  -- transaction block 841: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_841;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_841;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 841, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 842: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_842;
    CREATE TEMPORARY TABLE tmp_agg_842 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_842 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_842 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_842;
  END;

  -- upsert block 843: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_843 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_843, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_843, 'MERGE', CONCAT('stock topped for ', CAST(v_key_843 AS CHAR)));
  END;

  -- json block 844: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_844 JSON;
    DECLARE v_sku_844 VARCHAR(40);
    DECLARE v_tag_844 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_844, v_sku_844, v_tag_844
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_844,''), ' tag ', IFNULL(v_tag_844,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_844, 'tag', v_tag_844) AS CHAR)));
  END;

  -- cte block 845: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_845 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_845 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_845 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_845 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 846: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_846 VARCHAR(10);
    DECLARE v_amt_846 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_846 FROM erp_order;
    SET v_band_846 = CASE
        WHEN v_amt_846 >= 10000 THEN 'HIGH'
        WHEN v_amt_846 >= 1000  THEN 'MED'
        WHEN v_amt_846 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_846, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 847: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_847 INT DEFAULT 0;
    DECLARE v_j_847 INT DEFAULT 0;
    DECLARE v_rc_847 INT DEFAULT 0;
    REPEAT
      SET v_i_847 = v_i_847 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R847'), v_i_847)
        ON DUPLICATE KEY UPDATE tick = v_i_847;
    UNTIL v_i_847 >= 3 END REPEAT;
    WHILE v_j_847 < 3 DO
      SET v_j_847 = v_j_847 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_847 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_847 + v_j_847, 'ITER',
            CONCAT('i ', CAST(v_i_847 AS CHAR), ' j ', CAST(v_j_847 AS CHAR),
                   ' diag ', CAST(v_rc_847 AS CHAR)));
  END;

  -- analytics block 848: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_848 INT DEFAULT 0;
    DECLARE v_amt_848 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_848 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_848 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_848, v_amt_848, v_avg_848, v_max_848
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_848 = v_amt_848 + erp_fn_tax_amount(v_amt_848, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_848, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_848 AS CHAR), ' avg ', CAST(v_avg_848 AS CHAR),
                   ' max ', CAST(v_max_848 AS CHAR)));
  END;

  -- reconcile block 849: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_849 INT DEFAULT 0;
    DECLARE v_pid_849 INT;
    DECLARE v_oh_849 DECIMAL(18,4);
    DECLARE v_av_849 DECIMAL(18,4);
    DECLARE cur_849 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_849 = 1;
    OPEN cur_849;
    rl_849: LOOP
      FETCH cur_849 INTO v_pid_849, v_oh_849;
      IF v_fin_849 = 1 THEN LEAVE rl_849; END IF;
      SET v_av_849 = erp_fn_available_qty(v_pid_849, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_849, 1, 'RECON', CAST(v_oh_849 - v_av_849 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_849 AS CHAR));
    END LOOP;
    CLOSE cur_849;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_849,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_849,0) AS CHAR)));
  END;

  -- dynamic-sql block 850: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_850 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_850 VARCHAR(64) DEFAULT 'status';
    SET @dsql_850 = CONCAT('SELECT COUNT(*) INTO @dcnt_850 FROM ', v_tbl_850,
                          ' WHERE ', v_col_850, ' = ?');
    SET @dparm_850 = 'NEW';
    PREPARE pst_850 FROM @dsql_850;
    EXECUTE pst_850 USING @dparm_850;
    DEALLOCATE PREPARE pst_850;
    SET @dupd_850 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_850 = 100;
    PREPARE pud_850 FROM @dupd_850;
    EXECUTE pud_850 USING @doid_850;
    DEALLOCATE PREPARE pud_850;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_850,0), 'COUNT',
            CONCAT('tbl ', v_tbl_850, ' col ', v_col_850));
  END;

  -- recursive block 851: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_851 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_851 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_851;
  END;

  -- reprice block 852: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_852 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_852;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_852, 'UPDATE', CONCAT('rows ', CAST(v_rows_852 AS CHAR)));
  END;

  -- validation block 853: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_853 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_853
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_853 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_853, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_853 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_853, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 854: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_854 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_854 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_854 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_854 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_854 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_854 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_854 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_854 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_854 AS CHAR), ' cr ', CAST(v_cr_854 AS CHAR),
                   ' dr ', CAST(v_dr_854 AS CHAR), ' tot ', CAST(v_tot_854 AS CHAR)));
  END;

  -- invoice rollup block 855: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_855 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_855 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_855
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_855
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_855 AS CHAR), ' paid ', CAST(v_paid_855 AS CHAR)));
  END;

  -- gl reconciliation block 856: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_856 INT DEFAULT 0;
    DECLARE v_acct_856 INT;
    DECLARE v_dr_856 DECIMAL(18,2);
    DECLARE v_cr_856 DECIMAL(18,2);
    DECLARE gcur_856 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_856 = 1;
    OPEN gcur_856;
    gl_856: LOOP
      FETCH gcur_856 INTO v_acct_856, v_dr_856, v_cr_856;
      IF v_gfin_856 = 1 THEN LEAVE gl_856; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_856, 'BALANCE',
              CONCAT('net ', CAST(v_dr_856 - v_cr_856 AS CHAR)));
    END LOOP;
    CLOSE gcur_856;
  END;

  -- transaction block 857: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_857;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_857;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 857, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 858: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_858;
    CREATE TEMPORARY TABLE tmp_agg_858 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_858 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_858 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_858;
  END;

  -- upsert block 859: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_859 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_859, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_859, 'MERGE', CONCAT('stock topped for ', CAST(v_key_859 AS CHAR)));
  END;

  -- json block 860: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_860 JSON;
    DECLARE v_sku_860 VARCHAR(40);
    DECLARE v_tag_860 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_860, v_sku_860, v_tag_860
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_860,''), ' tag ', IFNULL(v_tag_860,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_860, 'tag', v_tag_860) AS CHAR)));
  END;

  -- cte block 861: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_861 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_861 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_861 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_861 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_rebuild_stats  [procedure]
CREATE PROCEDURE erp_usp_rebuild_stats()
BEGIN
  DECLARE v_cust INT DEFAULT 0;
  DECLARE v_prod INT DEFAULT 0;
  SELECT COUNT(*) INTO v_cust FROM erp_customer;
  SELECT COUNT(*) INTO v_prod FROM erp_product;
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('customers', v_cust), ('products', v_prod)
  ON DUPLICATE KEY UPDATE stat_value = VALUES(stat_value);
  CALL erp_usp_audit_log('STATS', v_cust + v_prod, 'REBUILD', 'stats rebuilt');

  -- case block 862: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_862 VARCHAR(10);
    DECLARE v_amt_862 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_862 FROM erp_order;
    SET v_band_862 = CASE
        WHEN v_amt_862 >= 10000 THEN 'HIGH'
        WHEN v_amt_862 >= 1000  THEN 'MED'
        WHEN v_amt_862 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_862, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 863: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_863 INT DEFAULT 0;
    DECLARE v_j_863 INT DEFAULT 0;
    DECLARE v_rc_863 INT DEFAULT 0;
    REPEAT
      SET v_i_863 = v_i_863 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R863'), v_i_863)
        ON DUPLICATE KEY UPDATE tick = v_i_863;
    UNTIL v_i_863 >= 3 END REPEAT;
    WHILE v_j_863 < 3 DO
      SET v_j_863 = v_j_863 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_863 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_863 + v_j_863, 'ITER',
            CONCAT('i ', CAST(v_i_863 AS CHAR), ' j ', CAST(v_j_863 AS CHAR),
                   ' diag ', CAST(v_rc_863 AS CHAR)));
  END;

  -- analytics block 864: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_864 INT DEFAULT 0;
    DECLARE v_amt_864 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_864 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_864 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_864, v_amt_864, v_avg_864, v_max_864
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_864 = v_amt_864 + erp_fn_tax_amount(v_amt_864, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_864, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_864 AS CHAR), ' avg ', CAST(v_avg_864 AS CHAR),
                   ' max ', CAST(v_max_864 AS CHAR)));
  END;

  -- reconcile block 865: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_865 INT DEFAULT 0;
    DECLARE v_pid_865 INT;
    DECLARE v_oh_865 DECIMAL(18,4);
    DECLARE v_av_865 DECIMAL(18,4);
    DECLARE cur_865 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_865 = 1;
    OPEN cur_865;
    rl_865: LOOP
      FETCH cur_865 INTO v_pid_865, v_oh_865;
      IF v_fin_865 = 1 THEN LEAVE rl_865; END IF;
      SET v_av_865 = erp_fn_available_qty(v_pid_865, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_865, 1, 'RECON', CAST(v_oh_865 - v_av_865 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_865 AS CHAR));
    END LOOP;
    CLOSE cur_865;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_865,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_865,0) AS CHAR)));
  END;

  -- dynamic-sql block 866: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_866 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_866 VARCHAR(64) DEFAULT 'status';
    SET @dsql_866 = CONCAT('SELECT COUNT(*) INTO @dcnt_866 FROM ', v_tbl_866,
                          ' WHERE ', v_col_866, ' = ?');
    SET @dparm_866 = 'NEW';
    PREPARE pst_866 FROM @dsql_866;
    EXECUTE pst_866 USING @dparm_866;
    DEALLOCATE PREPARE pst_866;
    SET @dupd_866 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_866 = 100;
    PREPARE pud_866 FROM @dupd_866;
    EXECUTE pud_866 USING @doid_866;
    DEALLOCATE PREPARE pud_866;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_866,0), 'COUNT',
            CONCAT('tbl ', v_tbl_866, ' col ', v_col_866));
  END;

  -- recursive block 867: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_867 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_867 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_867;
  END;

  -- reprice block 868: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_868 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_868;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_868, 'UPDATE', CONCAT('rows ', CAST(v_rows_868 AS CHAR)));
  END;

  -- validation block 869: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_869 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_869
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_869 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_869, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_869 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_869, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 870: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_870 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_870 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_870 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_870 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_870 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_870 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_870 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_870 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_870 AS CHAR), ' cr ', CAST(v_cr_870 AS CHAR),
                   ' dr ', CAST(v_dr_870 AS CHAR), ' tot ', CAST(v_tot_870 AS CHAR)));
  END;

  -- invoice rollup block 871: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_871 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_871 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_871
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_871
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_871 AS CHAR), ' paid ', CAST(v_paid_871 AS CHAR)));
  END;

  -- gl reconciliation block 872: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_872 INT DEFAULT 0;
    DECLARE v_acct_872 INT;
    DECLARE v_dr_872 DECIMAL(18,2);
    DECLARE v_cr_872 DECIMAL(18,2);
    DECLARE gcur_872 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_872 = 1;
    OPEN gcur_872;
    gl_872: LOOP
      FETCH gcur_872 INTO v_acct_872, v_dr_872, v_cr_872;
      IF v_gfin_872 = 1 THEN LEAVE gl_872; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_872, 'BALANCE',
              CONCAT('net ', CAST(v_dr_872 - v_cr_872 AS CHAR)));
    END LOOP;
    CLOSE gcur_872;
  END;

  -- transaction block 873: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_873;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_873;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 873, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 874: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_874;
    CREATE TEMPORARY TABLE tmp_agg_874 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_874 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_874 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_874;
  END;

  -- upsert block 875: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_875 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_875, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_875, 'MERGE', CONCAT('stock topped for ', CAST(v_key_875 AS CHAR)));
  END;

  -- json block 876: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_876 JSON;
    DECLARE v_sku_876 VARCHAR(40);
    DECLARE v_tag_876 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_876, v_sku_876, v_tag_876
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_876,''), ' tag ', IFNULL(v_tag_876,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_876, 'tag', v_tag_876) AS CHAR)));
  END;

  -- cte block 877: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_877 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_877 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_877 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_877 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 878: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_878 VARCHAR(10);
    DECLARE v_amt_878 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_878 FROM erp_order;
    SET v_band_878 = CASE
        WHEN v_amt_878 >= 10000 THEN 'HIGH'
        WHEN v_amt_878 >= 1000  THEN 'MED'
        WHEN v_amt_878 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_878, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 879: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_879 INT DEFAULT 0;
    DECLARE v_j_879 INT DEFAULT 0;
    DECLARE v_rc_879 INT DEFAULT 0;
    REPEAT
      SET v_i_879 = v_i_879 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R879'), v_i_879)
        ON DUPLICATE KEY UPDATE tick = v_i_879;
    UNTIL v_i_879 >= 3 END REPEAT;
    WHILE v_j_879 < 3 DO
      SET v_j_879 = v_j_879 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_879 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_879 + v_j_879, 'ITER',
            CONCAT('i ', CAST(v_i_879 AS CHAR), ' j ', CAST(v_j_879 AS CHAR),
                   ' diag ', CAST(v_rc_879 AS CHAR)));
  END;

  -- analytics block 880: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_880 INT DEFAULT 0;
    DECLARE v_amt_880 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_880 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_880 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_880, v_amt_880, v_avg_880, v_max_880
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_880 = v_amt_880 + erp_fn_tax_amount(v_amt_880, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_880, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_880 AS CHAR), ' avg ', CAST(v_avg_880 AS CHAR),
                   ' max ', CAST(v_max_880 AS CHAR)));
  END;

