    OPEN gcur_888;
    gl_888: LOOP
      FETCH gcur_888 INTO v_acct_888, v_dr_888, v_cr_888;
      IF v_gfin_888 = 1 THEN LEAVE gl_888; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_888, 'BALANCE',
              CONCAT('net ', CAST(v_dr_888 - v_cr_888 AS CHAR)));
    END LOOP;
    CLOSE gcur_888;
  END;

  -- transaction block 889: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_889;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_889;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 889, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 890: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_890;
    CREATE TEMPORARY TABLE tmp_agg_890 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_890 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_890 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_890;
  END;

  -- upsert block 891: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_891 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_891, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_891, 'MERGE', CONCAT('stock topped for ', CAST(v_key_891 AS CHAR)));
  END;

  -- json block 892: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_892 JSON;
    DECLARE v_sku_892 VARCHAR(40);
    DECLARE v_tag_892 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_892, v_sku_892, v_tag_892
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_892,''), ' tag ', IFNULL(v_tag_892,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_892, 'tag', v_tag_892) AS CHAR)));
  END;

  -- cte block 893: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_893 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_893 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_893 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_893 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 894: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_894 VARCHAR(10);
    DECLARE v_amt_894 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_894 FROM erp_order;
    SET v_band_894 = CASE
        WHEN v_amt_894 >= 10000 THEN 'HIGH'
        WHEN v_amt_894 >= 1000  THEN 'MED'
        WHEN v_amt_894 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_894, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_refresh_mv  [procedure]
CREATE PROCEDURE erp_usp_refresh_mv()
BEGIN
  -- simulate a materialized view (MySQL N/A) via a refreshed table
  DELETE FROM erp_mv_customer_sales;
  INSERT INTO erp_mv_customer_sales (customer_id, order_count, total_sales)
  SELECT c.customer_id, COUNT(o.order_id), IFNULL(SUM(o.total_amount),0)
    FROM erp_customer c
    LEFT JOIN erp_order o ON o.customer_id = c.customer_id
   GROUP BY c.customer_id;
  CALL erp_usp_audit_log('MV', 0, 'REFRESH', 'materialized view refreshed');

  -- repeat/while block 895: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_895 INT DEFAULT 0;
    DECLARE v_j_895 INT DEFAULT 0;
    DECLARE v_rc_895 INT DEFAULT 0;
    REPEAT
      SET v_i_895 = v_i_895 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R895'), v_i_895)
        ON DUPLICATE KEY UPDATE tick = v_i_895;
    UNTIL v_i_895 >= 3 END REPEAT;
    WHILE v_j_895 < 3 DO
      SET v_j_895 = v_j_895 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_895 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_895 + v_j_895, 'ITER',
            CONCAT('i ', CAST(v_i_895 AS CHAR), ' j ', CAST(v_j_895 AS CHAR),
                   ' diag ', CAST(v_rc_895 AS CHAR)));
  END;

  -- analytics block 896: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_896 INT DEFAULT 0;
    DECLARE v_amt_896 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_896 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_896 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_896, v_amt_896, v_avg_896, v_max_896
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_896 = v_amt_896 + erp_fn_tax_amount(v_amt_896, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_896, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_896 AS CHAR), ' avg ', CAST(v_avg_896 AS CHAR),
                   ' max ', CAST(v_max_896 AS CHAR)));
  END;

  -- reconcile block 897: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_897 INT DEFAULT 0;
    DECLARE v_pid_897 INT;
    DECLARE v_oh_897 DECIMAL(18,4);
    DECLARE v_av_897 DECIMAL(18,4);
    DECLARE cur_897 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_897 = 1;
    OPEN cur_897;
    rl_897: LOOP
      FETCH cur_897 INTO v_pid_897, v_oh_897;
      IF v_fin_897 = 1 THEN LEAVE rl_897; END IF;
      SET v_av_897 = erp_fn_available_qty(v_pid_897, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_897, 1, 'RECON', CAST(v_oh_897 - v_av_897 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_897 AS CHAR));
    END LOOP;
    CLOSE cur_897;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_897,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_897,0) AS CHAR)));
  END;

  -- dynamic-sql block 898: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_898 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_898 VARCHAR(64) DEFAULT 'status';
    SET @dsql_898 = CONCAT('SELECT COUNT(*) INTO @dcnt_898 FROM ', v_tbl_898,
                          ' WHERE ', v_col_898, ' = ?');
    SET @dparm_898 = 'NEW';
    PREPARE pst_898 FROM @dsql_898;
    EXECUTE pst_898 USING @dparm_898;
    DEALLOCATE PREPARE pst_898;
    SET @dupd_898 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_898 = 100;
    PREPARE pud_898 FROM @dupd_898;
    EXECUTE pud_898 USING @doid_898;
    DEALLOCATE PREPARE pud_898;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_898,0), 'COUNT',
            CONCAT('tbl ', v_tbl_898, ' col ', v_col_898));
  END;

  -- recursive block 899: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_899 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_899 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_899;
  END;

  -- reprice block 900: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_900 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_900;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_900, 'UPDATE', CONCAT('rows ', CAST(v_rows_900 AS CHAR)));
  END;

  -- validation block 901: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_901 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_901
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_901 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_901, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_901 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_901, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 902: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_902 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_902 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_902 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_902 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_902 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_902 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_902 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_902 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_902 AS CHAR), ' cr ', CAST(v_cr_902 AS CHAR),
                   ' dr ', CAST(v_dr_902 AS CHAR), ' tot ', CAST(v_tot_902 AS CHAR)));
  END;

  -- invoice rollup block 903: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_903 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_903 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_903
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_903
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_903 AS CHAR), ' paid ', CAST(v_paid_903 AS CHAR)));
  END;

  -- gl reconciliation block 904: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_904 INT DEFAULT 0;
    DECLARE v_acct_904 INT;
    DECLARE v_dr_904 DECIMAL(18,2);
    DECLARE v_cr_904 DECIMAL(18,2);
    DECLARE gcur_904 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_904 = 1;
    OPEN gcur_904;
    gl_904: LOOP
      FETCH gcur_904 INTO v_acct_904, v_dr_904, v_cr_904;
      IF v_gfin_904 = 1 THEN LEAVE gl_904; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_904, 'BALANCE',
              CONCAT('net ', CAST(v_dr_904 - v_cr_904 AS CHAR)));
    END LOOP;
    CLOSE gcur_904;
  END;

  -- transaction block 905: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_905;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_905;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 905, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 906: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_906;
    CREATE TEMPORARY TABLE tmp_agg_906 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_906 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_906 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_906;
  END;

  -- upsert block 907: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_907 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_907, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_907, 'MERGE', CONCAT('stock topped for ', CAST(v_key_907 AS CHAR)));
  END;

  -- json block 908: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_908 JSON;
    DECLARE v_sku_908 VARCHAR(40);
    DECLARE v_tag_908 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_908, v_sku_908, v_tag_908
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_908,''), ' tag ', IFNULL(v_tag_908,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_908, 'tag', v_tag_908) AS CHAR)));
  END;

  -- cte block 909: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_909 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_909 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_909 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_909 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 910: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_910 VARCHAR(10);
    DECLARE v_amt_910 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_910 FROM erp_order;
    SET v_band_910 = CASE
        WHEN v_amt_910 >= 10000 THEN 'HIGH'
        WHEN v_amt_910 >= 1000  THEN 'MED'
        WHEN v_amt_910 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_910, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 911: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_911 INT DEFAULT 0;
    DECLARE v_j_911 INT DEFAULT 0;
    DECLARE v_rc_911 INT DEFAULT 0;
    REPEAT
      SET v_i_911 = v_i_911 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R911'), v_i_911)
        ON DUPLICATE KEY UPDATE tick = v_i_911;
    UNTIL v_i_911 >= 3 END REPEAT;
    WHILE v_j_911 < 3 DO
      SET v_j_911 = v_j_911 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_911 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_911 + v_j_911, 'ITER',
            CONCAT('i ', CAST(v_i_911 AS CHAR), ' j ', CAST(v_j_911 AS CHAR),
                   ' diag ', CAST(v_rc_911 AS CHAR)));
  END;

  -- analytics block 912: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_912 INT DEFAULT 0;
    DECLARE v_amt_912 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_912 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_912 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_912, v_amt_912, v_avg_912, v_max_912
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_912 = v_amt_912 + erp_fn_tax_amount(v_amt_912, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_912, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_912 AS CHAR), ' avg ', CAST(v_avg_912 AS CHAR),
                   ' max ', CAST(v_max_912 AS CHAR)));
  END;

  -- reconcile block 913: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_913 INT DEFAULT 0;
    DECLARE v_pid_913 INT;
    DECLARE v_oh_913 DECIMAL(18,4);
    DECLARE v_av_913 DECIMAL(18,4);
    DECLARE cur_913 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_913 = 1;
    OPEN cur_913;
    rl_913: LOOP
      FETCH cur_913 INTO v_pid_913, v_oh_913;
      IF v_fin_913 = 1 THEN LEAVE rl_913; END IF;
      SET v_av_913 = erp_fn_available_qty(v_pid_913, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_913, 1, 'RECON', CAST(v_oh_913 - v_av_913 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_913 AS CHAR));
    END LOOP;
    CLOSE cur_913;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_913,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_913,0) AS CHAR)));
  END;

  -- dynamic-sql block 914: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_914 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_914 VARCHAR(64) DEFAULT 'status';
    SET @dsql_914 = CONCAT('SELECT COUNT(*) INTO @dcnt_914 FROM ', v_tbl_914,
                          ' WHERE ', v_col_914, ' = ?');
    SET @dparm_914 = 'NEW';
    PREPARE pst_914 FROM @dsql_914;
    EXECUTE pst_914 USING @dparm_914;
    DEALLOCATE PREPARE pst_914;
    SET @dupd_914 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_914 = 100;
    PREPARE pud_914 FROM @dupd_914;
    EXECUTE pud_914 USING @doid_914;
    DEALLOCATE PREPARE pud_914;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_914,0), 'COUNT',
            CONCAT('tbl ', v_tbl_914, ' col ', v_col_914));
  END;

  -- recursive block 915: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_915 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_915 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_915;
  END;

  -- reprice block 916: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_916 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_916;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_916, 'UPDATE', CONCAT('rows ', CAST(v_rows_916 AS CHAR)));
  END;

  -- validation block 917: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_917 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_917
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_917 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_917, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_917 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_917, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 918: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_918 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_918 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_918 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_918 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_918 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_918 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_918 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_918 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_918 AS CHAR), ' cr ', CAST(v_cr_918 AS CHAR),
                   ' dr ', CAST(v_dr_918 AS CHAR), ' tot ', CAST(v_tot_918 AS CHAR)));
  END;

  -- invoice rollup block 919: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_919 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_919 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_919
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_919
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_919 AS CHAR), ' paid ', CAST(v_paid_919 AS CHAR)));
  END;

  -- gl reconciliation block 920: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_920 INT DEFAULT 0;
    DECLARE v_acct_920 INT;
    DECLARE v_dr_920 DECIMAL(18,2);
    DECLARE v_cr_920 DECIMAL(18,2);
    DECLARE gcur_920 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_920 = 1;
    OPEN gcur_920;
    gl_920: LOOP
      FETCH gcur_920 INTO v_acct_920, v_dr_920, v_cr_920;
      IF v_gfin_920 = 1 THEN LEAVE gl_920; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_920, 'BALANCE',
              CONCAT('net ', CAST(v_dr_920 - v_cr_920 AS CHAR)));
    END LOOP;
    CLOSE gcur_920;
  END;

  -- transaction block 921: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_921;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_921;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 921, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 922: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_922;
    CREATE TEMPORARY TABLE tmp_agg_922 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_922 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_922 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_922;
  END;

  -- upsert block 923: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_923 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_923, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_923, 'MERGE', CONCAT('stock topped for ', CAST(v_key_923 AS CHAR)));
  END;

  -- json block 924: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_924 JSON;
    DECLARE v_sku_924 VARCHAR(40);
    DECLARE v_tag_924 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_924, v_sku_924, v_tag_924
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_924,''), ' tag ', IFNULL(v_tag_924,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_924, 'tag', v_tag_924) AS CHAR)));
  END;

  -- cte block 925: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_925 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_925 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_925 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_925 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 926: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_926 VARCHAR(10);
    DECLARE v_amt_926 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_926 FROM erp_order;
    SET v_band_926 = CASE
        WHEN v_amt_926 >= 10000 THEN 'HIGH'
        WHEN v_amt_926 >= 1000  THEN 'MED'
        WHEN v_amt_926 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_926, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 927: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_927 INT DEFAULT 0;
    DECLARE v_j_927 INT DEFAULT 0;
    DECLARE v_rc_927 INT DEFAULT 0;
    REPEAT
      SET v_i_927 = v_i_927 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R927'), v_i_927)
        ON DUPLICATE KEY UPDATE tick = v_i_927;
    UNTIL v_i_927 >= 3 END REPEAT;
    WHILE v_j_927 < 3 DO
      SET v_j_927 = v_j_927 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_927 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_927 + v_j_927, 'ITER',
            CONCAT('i ', CAST(v_i_927 AS CHAR), ' j ', CAST(v_j_927 AS CHAR),
                   ' diag ', CAST(v_rc_927 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_edge_ops  [procedure]
CREATE PROCEDURE erp_usp_edge_ops()
BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE v_deep INT DEFAULT 0;
  -- deeply nested subquery edge case
  SELECT COUNT(*) INTO v_deep FROM erp_order o
   WHERE o.order_id IN (
     SELECT order_id FROM erp_order_line WHERE product_id IN (
       SELECT product_id FROM erp_product WHERE category_id IN (
         SELECT category_id FROM erp_product_category WHERE category_id IN (
           SELECT category_id FROM erp_product WHERE active = 1))));
  SELECT COALESCE(MAX(order_id), 0) INTO v_n FROM erp_order;
  CALL erp_usp_audit_log('EDGE', v_deep, 'NESTED', CONCAT('maxid ', CAST(v_n AS CHAR)));

  -- analytics block 928: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_928 INT DEFAULT 0;
    DECLARE v_amt_928 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_928 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_928 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_928, v_amt_928, v_avg_928, v_max_928
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_928 = v_amt_928 + erp_fn_tax_amount(v_amt_928, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_928, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_928 AS CHAR), ' avg ', CAST(v_avg_928 AS CHAR),
                   ' max ', CAST(v_max_928 AS CHAR)));
  END;

  -- reconcile block 929: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_929 INT DEFAULT 0;
    DECLARE v_pid_929 INT;
    DECLARE v_oh_929 DECIMAL(18,4);
    DECLARE v_av_929 DECIMAL(18,4);
    DECLARE cur_929 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_929 = 1;
    OPEN cur_929;
    rl_929: LOOP
      FETCH cur_929 INTO v_pid_929, v_oh_929;
      IF v_fin_929 = 1 THEN LEAVE rl_929; END IF;
      SET v_av_929 = erp_fn_available_qty(v_pid_929, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_929, 1, 'RECON', CAST(v_oh_929 - v_av_929 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_929 AS CHAR));
    END LOOP;
    CLOSE cur_929;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_929,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_929,0) AS CHAR)));
  END;

  -- dynamic-sql block 930: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_930 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_930 VARCHAR(64) DEFAULT 'status';
    SET @dsql_930 = CONCAT('SELECT COUNT(*) INTO @dcnt_930 FROM ', v_tbl_930,
                          ' WHERE ', v_col_930, ' = ?');
    SET @dparm_930 = 'NEW';
    PREPARE pst_930 FROM @dsql_930;
    EXECUTE pst_930 USING @dparm_930;
    DEALLOCATE PREPARE pst_930;
    SET @dupd_930 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_930 = 100;
    PREPARE pud_930 FROM @dupd_930;
    EXECUTE pud_930 USING @doid_930;
    DEALLOCATE PREPARE pud_930;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_930,0), 'COUNT',
            CONCAT('tbl ', v_tbl_930, ' col ', v_col_930));
  END;

  -- recursive block 931: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_931 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_931 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_931;
  END;

  -- reprice block 932: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_932 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_932;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_932, 'UPDATE', CONCAT('rows ', CAST(v_rows_932 AS CHAR)));
  END;

  -- validation block 933: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_933 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_933
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_933 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_933, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_933 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_933, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 934: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_934 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_934 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_934 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_934 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_934 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_934 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_934 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_934 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_934 AS CHAR), ' cr ', CAST(v_cr_934 AS CHAR),
                   ' dr ', CAST(v_dr_934 AS CHAR), ' tot ', CAST(v_tot_934 AS CHAR)));
  END;

  -- invoice rollup block 935: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_935 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_935 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_935
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_935
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_935 AS CHAR), ' paid ', CAST(v_paid_935 AS CHAR)));
  END;

  -- gl reconciliation block 936: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_936 INT DEFAULT 0;
    DECLARE v_acct_936 INT;
    DECLARE v_dr_936 DECIMAL(18,2);
    DECLARE v_cr_936 DECIMAL(18,2);
    DECLARE gcur_936 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_936 = 1;
    OPEN gcur_936;
    gl_936: LOOP
      FETCH gcur_936 INTO v_acct_936, v_dr_936, v_cr_936;
      IF v_gfin_936 = 1 THEN LEAVE gl_936; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_936, 'BALANCE',
              CONCAT('net ', CAST(v_dr_936 - v_cr_936 AS CHAR)));
    END LOOP;
    CLOSE gcur_936;
  END;

  -- transaction block 937: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_937;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_937;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 937, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 938: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_938;
    CREATE TEMPORARY TABLE tmp_agg_938 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_938 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_938 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_938;
  END;

  -- upsert block 939: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_939 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_939, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_939, 'MERGE', CONCAT('stock topped for ', CAST(v_key_939 AS CHAR)));
  END;

  -- json block 940: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_940 JSON;
    DECLARE v_sku_940 VARCHAR(40);
    DECLARE v_tag_940 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_940, v_sku_940, v_tag_940
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_940,''), ' tag ', IFNULL(v_tag_940,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_940, 'tag', v_tag_940) AS CHAR)));
  END;

  -- cte block 941: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_941 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_941 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_941 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_941 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 942: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_942 VARCHAR(10);
    DECLARE v_amt_942 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_942 FROM erp_order;
    SET v_band_942 = CASE
        WHEN v_amt_942 >= 10000 THEN 'HIGH'
        WHEN v_amt_942 >= 1000  THEN 'MED'
        WHEN v_amt_942 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_942, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 943: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_943 INT DEFAULT 0;
    DECLARE v_j_943 INT DEFAULT 0;
    DECLARE v_rc_943 INT DEFAULT 0;
    REPEAT
      SET v_i_943 = v_i_943 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R943'), v_i_943)
        ON DUPLICATE KEY UPDATE tick = v_i_943;
    UNTIL v_i_943 >= 3 END REPEAT;
    WHILE v_j_943 < 3 DO
      SET v_j_943 = v_j_943 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_943 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_943 + v_j_943, 'ITER',
            CONCAT('i ', CAST(v_i_943 AS CHAR), ' j ', CAST(v_j_943 AS CHAR),
                   ' diag ', CAST(v_rc_943 AS CHAR)));
  END;

  -- analytics block 944: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_944 INT DEFAULT 0;
    DECLARE v_amt_944 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_944 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_944 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_944, v_amt_944, v_avg_944, v_max_944
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_944 = v_amt_944 + erp_fn_tax_amount(v_amt_944, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_944, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_944 AS CHAR), ' avg ', CAST(v_avg_944 AS CHAR),
                   ' max ', CAST(v_max_944 AS CHAR)));
  END;

  -- reconcile block 945: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_945 INT DEFAULT 0;
    DECLARE v_pid_945 INT;
    DECLARE v_oh_945 DECIMAL(18,4);
    DECLARE v_av_945 DECIMAL(18,4);
    DECLARE cur_945 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_945 = 1;
    OPEN cur_945;
    rl_945: LOOP
      FETCH cur_945 INTO v_pid_945, v_oh_945;
      IF v_fin_945 = 1 THEN LEAVE rl_945; END IF;
      SET v_av_945 = erp_fn_available_qty(v_pid_945, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_945, 1, 'RECON', CAST(v_oh_945 - v_av_945 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_945 AS CHAR));
    END LOOP;
    CLOSE cur_945;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_945,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_945,0) AS CHAR)));
  END;

  -- dynamic-sql block 946: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_946 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_946 VARCHAR(64) DEFAULT 'status';
    SET @dsql_946 = CONCAT('SELECT COUNT(*) INTO @dcnt_946 FROM ', v_tbl_946,
                          ' WHERE ', v_col_946, ' = ?');
    SET @dparm_946 = 'NEW';
    PREPARE pst_946 FROM @dsql_946;
    EXECUTE pst_946 USING @dparm_946;
    DEALLOCATE PREPARE pst_946;
    SET @dupd_946 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_946 = 100;
    PREPARE pud_946 FROM @dupd_946;
    EXECUTE pud_946 USING @doid_946;
    DEALLOCATE PREPARE pud_946;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_946,0), 'COUNT',
            CONCAT('tbl ', v_tbl_946, ' col ', v_col_946));
  END;

  -- recursive block 947: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_947 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_947 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_947;
  END;

  -- reprice block 948: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_948 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_948;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_948, 'UPDATE', CONCAT('rows ', CAST(v_rows_948 AS CHAR)));
  END;

  -- validation block 949: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_949 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_949
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_949 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_949, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_949 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_949, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 950: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_950 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_950 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_950 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_950 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_950 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_950 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_950 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_950 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_950 AS CHAR), ' cr ', CAST(v_cr_950 AS CHAR),
                   ' dr ', CAST(v_dr_950 AS CHAR), ' tot ', CAST(v_tot_950 AS CHAR)));
  END;

  -- invoice rollup block 951: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_951 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_951 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_951
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_951
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_951 AS CHAR), ' paid ', CAST(v_paid_951 AS CHAR)));
  END;

  -- gl reconciliation block 952: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_952 INT DEFAULT 0;
    DECLARE v_acct_952 INT;
    DECLARE v_dr_952 DECIMAL(18,2);
    DECLARE v_cr_952 DECIMAL(18,2);
