  -- analytics block 960: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_960 INT DEFAULT 0;
    DECLARE v_amt_960 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_960 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_960 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_960, v_amt_960, v_avg_960, v_max_960
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_960 = v_amt_960 + erp_fn_tax_amount(v_amt_960, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_960, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_960 AS CHAR), ' avg ', CAST(v_avg_960 AS CHAR),
                   ' max ', CAST(v_max_960 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_bom_explode_rec  [procedure]
CREATE PROCEDURE erp_usp_bom_explode_rec(IN p_product_id INT, IN p_depth INT)
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_child INT;
  DECLARE cur_c CURSOR FOR SELECT component_id FROM erp_bom WHERE parent_id = p_product_id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  -- base case / depth guard: terminate when max depth reached
  IF p_depth >= 15 THEN
    CALL erp_usp_audit_log('BOMREC', p_product_id, 'MAXDEPTH', CONCAT('stop at ', CAST(p_depth AS CHAR)));
  ELSE
    OPEN cur_c;
    bomrec_loop: LOOP
      FETCH cur_c INTO v_child;
      IF v_done = 1 THEN LEAVE bomrec_loop; END IF;
      CALL erp_usp_audit_log('BOMREC', v_child, 'VISIT', CONCAT('depth ', CAST(p_depth AS CHAR)));
      -- DIRECT SELF-RECURSION
      CALL erp_usp_bom_explode_rec(v_child, p_depth + 1);
    END LOOP;
    CLOSE cur_c;
  END IF;
END$$

-- ---------------------------------------------------------------- erp_usp_ping  [procedure]
CREATE PROCEDURE erp_usp_ping(IN p_depth INT)
BEGIN
  IF p_depth <= 0 THEN
    CALL erp_usp_audit_log('PINGPONG', 0, 'PING_STOP', 'ping base case reached');
  ELSE
    CALL erp_usp_audit_log('PINGPONG', p_depth, 'PING', CONCAT('ping ', CAST(p_depth AS CHAR)));
    -- MUTUAL RECURSION: ping -> pong
    CALL erp_usp_pong(p_depth - 1);
  END IF;
END$$

-- ---------------------------------------------------------------- erp_usp_pong  [procedure]
CREATE PROCEDURE erp_usp_pong(IN p_depth INT)
BEGIN
  IF p_depth <= 0 THEN
    CALL erp_usp_audit_log('PINGPONG', 0, 'PONG_STOP', 'pong base case reached');
  ELSE
    CALL erp_usp_audit_log('PINGPONG', p_depth, 'PONG', CONCAT('pong ', CAST(p_depth AS CHAR)));
    -- MUTUAL RECURSION: pong -> ping  (circular cycle ping<->pong)
    CALL erp_usp_ping(p_depth - 1);
  END IF;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_01  [procedure]
CREATE PROCEDURE erp_usp_stage_01()
BEGIN
  DECLARE v_amt_s01 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s01 INT DEFAULT 0;
  DECLARE v_fx_s01  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s01 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s01 VARCHAR(60);
  DECLARE v_av_s01  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s01  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 1, 'ERROR', 'stage 01 failed');
  END;
  START TRANSACTION;
  SET v_fx_s01  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s01 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s01 = erp_fn_json_tag(1);
  SET v_av_s01  = erp_fn_available_qty(1, 1);
  SET v_cr_s01  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s01, v_amt_s01 FROM erp_order;
  SET v_amt_s01 = v_amt_s01 + erp_fn_tax_amount(v_amt_s01, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_01', v_cnt_s01)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s01;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s01 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 1, 'CREDIT', 'stage 01 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 1, 'OK', CONCAT('stage 01 tag ', IFNULL(v_tag_s01,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s01, 'RUN_01',
       CONCAT('fx ', CAST(v_fx_s01 AS CHAR), ' mar ', CAST(v_mar_s01 AS CHAR)));
  CALL erp_usp_stage_02();

  -- reconcile block 961: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_961 INT DEFAULT 0;
    DECLARE v_pid_961 INT;
    DECLARE v_oh_961 DECIMAL(18,4);
    DECLARE v_av_961 DECIMAL(18,4);
    DECLARE cur_961 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_961 = 1;
    OPEN cur_961;
    rl_961: LOOP
      FETCH cur_961 INTO v_pid_961, v_oh_961;
      IF v_fin_961 = 1 THEN LEAVE rl_961; END IF;
      SET v_av_961 = erp_fn_available_qty(v_pid_961, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_961, 1, 'RECON', CAST(v_oh_961 - v_av_961 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_961 AS CHAR));
    END LOOP;
    CLOSE cur_961;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_961,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_961,0) AS CHAR)));
  END;

  -- dynamic-sql block 962: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_962 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_962 VARCHAR(64) DEFAULT 'status';
    SET @dsql_962 = CONCAT('SELECT COUNT(*) INTO @dcnt_962 FROM ', v_tbl_962,
                          ' WHERE ', v_col_962, ' = ?');
    SET @dparm_962 = 'NEW';
    PREPARE pst_962 FROM @dsql_962;
    EXECUTE pst_962 USING @dparm_962;
    DEALLOCATE PREPARE pst_962;
    SET @dupd_962 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_962 = 100;
    PREPARE pud_962 FROM @dupd_962;
    EXECUTE pud_962 USING @doid_962;
    DEALLOCATE PREPARE pud_962;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_962,0), 'COUNT',
            CONCAT('tbl ', v_tbl_962, ' col ', v_col_962));
  END;

  -- recursive block 963: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_963 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_963 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_963;
  END;

  -- reprice block 964: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_964 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_964;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_964, 'UPDATE', CONCAT('rows ', CAST(v_rows_964 AS CHAR)));
  END;

  -- validation block 965: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_965 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_965
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_965 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_965, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_965 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_965, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 966: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_966 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_966 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_966 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_966 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_966 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_966 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_966 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_966 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_966 AS CHAR), ' cr ', CAST(v_cr_966 AS CHAR),
                   ' dr ', CAST(v_dr_966 AS CHAR), ' tot ', CAST(v_tot_966 AS CHAR)));
  END;

  -- invoice rollup block 967: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_967 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_967 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_967
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_967
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_967 AS CHAR), ' paid ', CAST(v_paid_967 AS CHAR)));
  END;

  -- gl reconciliation block 968: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_968 INT DEFAULT 0;
    DECLARE v_acct_968 INT;
    DECLARE v_dr_968 DECIMAL(18,2);
    DECLARE v_cr_968 DECIMAL(18,2);
    DECLARE gcur_968 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_968 = 1;
    OPEN gcur_968;
    gl_968: LOOP
      FETCH gcur_968 INTO v_acct_968, v_dr_968, v_cr_968;
      IF v_gfin_968 = 1 THEN LEAVE gl_968; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_968, 'BALANCE',
              CONCAT('net ', CAST(v_dr_968 - v_cr_968 AS CHAR)));
    END LOOP;
    CLOSE gcur_968;
  END;

  -- transaction block 969: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_969;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_969;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 969, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 970: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_970;
    CREATE TEMPORARY TABLE tmp_agg_970 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_970 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_970 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_970;
  END;

  -- upsert block 971: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_971 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_971, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_971, 'MERGE', CONCAT('stock topped for ', CAST(v_key_971 AS CHAR)));
  END;

  -- json block 972: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_972 JSON;
    DECLARE v_sku_972 VARCHAR(40);
    DECLARE v_tag_972 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_972, v_sku_972, v_tag_972
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_972,''), ' tag ', IFNULL(v_tag_972,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_972, 'tag', v_tag_972) AS CHAR)));
  END;

  -- cte block 973: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_973 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_973 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_973 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_973 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 974: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_974 VARCHAR(10);
    DECLARE v_amt_974 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_974 FROM erp_order;
    SET v_band_974 = CASE
        WHEN v_amt_974 >= 10000 THEN 'HIGH'
        WHEN v_amt_974 >= 1000  THEN 'MED'
        WHEN v_amt_974 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_974, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 975: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_975 INT DEFAULT 0;
    DECLARE v_j_975 INT DEFAULT 0;
    DECLARE v_rc_975 INT DEFAULT 0;
    REPEAT
      SET v_i_975 = v_i_975 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R975'), v_i_975)
        ON DUPLICATE KEY UPDATE tick = v_i_975;
    UNTIL v_i_975 >= 3 END REPEAT;
    WHILE v_j_975 < 3 DO
      SET v_j_975 = v_j_975 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_975 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_975 + v_j_975, 'ITER',
            CONCAT('i ', CAST(v_i_975 AS CHAR), ' j ', CAST(v_j_975 AS CHAR),
                   ' diag ', CAST(v_rc_975 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_02  [procedure]
CREATE PROCEDURE erp_usp_stage_02()
BEGIN
  DECLARE v_amt_s02 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s02 INT DEFAULT 0;
  DECLARE v_fx_s02  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s02 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s02 VARCHAR(60);
  DECLARE v_av_s02  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s02  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 2, 'ERROR', 'stage 02 failed');
  END;
  START TRANSACTION;
  SET v_fx_s02  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s02 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s02 = erp_fn_json_tag(1);
  SET v_av_s02  = erp_fn_available_qty(1, 1);
  SET v_cr_s02  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s02, v_amt_s02 FROM erp_order;
  SET v_amt_s02 = v_amt_s02 + erp_fn_tax_amount(v_amt_s02, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_02', v_cnt_s02)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s02;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s02 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 2, 'CREDIT', 'stage 02 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 2, 'OK', CONCAT('stage 02 tag ', IFNULL(v_tag_s02,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s02, 'RUN_02',
       CONCAT('fx ', CAST(v_fx_s02 AS CHAR), ' mar ', CAST(v_mar_s02 AS CHAR)));
  CALL erp_usp_stage_03();

  -- analytics block 976: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_976 INT DEFAULT 0;
    DECLARE v_amt_976 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_976 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_976 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_976, v_amt_976, v_avg_976, v_max_976
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_976 = v_amt_976 + erp_fn_tax_amount(v_amt_976, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_976, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_976 AS CHAR), ' avg ', CAST(v_avg_976 AS CHAR),
                   ' max ', CAST(v_max_976 AS CHAR)));
  END;

  -- reconcile block 977: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_977 INT DEFAULT 0;
    DECLARE v_pid_977 INT;
    DECLARE v_oh_977 DECIMAL(18,4);
    DECLARE v_av_977 DECIMAL(18,4);
    DECLARE cur_977 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_977 = 1;
    OPEN cur_977;
    rl_977: LOOP
      FETCH cur_977 INTO v_pid_977, v_oh_977;
      IF v_fin_977 = 1 THEN LEAVE rl_977; END IF;
      SET v_av_977 = erp_fn_available_qty(v_pid_977, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_977, 1, 'RECON', CAST(v_oh_977 - v_av_977 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_977 AS CHAR));
    END LOOP;
    CLOSE cur_977;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_977,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_977,0) AS CHAR)));
  END;

  -- dynamic-sql block 978: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_978 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_978 VARCHAR(64) DEFAULT 'status';
    SET @dsql_978 = CONCAT('SELECT COUNT(*) INTO @dcnt_978 FROM ', v_tbl_978,
                          ' WHERE ', v_col_978, ' = ?');
    SET @dparm_978 = 'NEW';
    PREPARE pst_978 FROM @dsql_978;
    EXECUTE pst_978 USING @dparm_978;
    DEALLOCATE PREPARE pst_978;
    SET @dupd_978 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_978 = 100;
    PREPARE pud_978 FROM @dupd_978;
    EXECUTE pud_978 USING @doid_978;
    DEALLOCATE PREPARE pud_978;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_978,0), 'COUNT',
            CONCAT('tbl ', v_tbl_978, ' col ', v_col_978));
  END;

  -- recursive block 979: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_979 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_979 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_979;
  END;

  -- reprice block 980: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_980 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_980;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_980, 'UPDATE', CONCAT('rows ', CAST(v_rows_980 AS CHAR)));
  END;

  -- validation block 981: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_981 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_981
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_981 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_981, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_981 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_981, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 982: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_982 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_982 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_982 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_982 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_982 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_982 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_982 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_982 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_982 AS CHAR), ' cr ', CAST(v_cr_982 AS CHAR),
                   ' dr ', CAST(v_dr_982 AS CHAR), ' tot ', CAST(v_tot_982 AS CHAR)));
  END;

  -- invoice rollup block 983: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_983 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_983 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_983
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_983
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_983 AS CHAR), ' paid ', CAST(v_paid_983 AS CHAR)));
  END;

  -- gl reconciliation block 984: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_984 INT DEFAULT 0;
    DECLARE v_acct_984 INT;
    DECLARE v_dr_984 DECIMAL(18,2);
    DECLARE v_cr_984 DECIMAL(18,2);
    DECLARE gcur_984 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_984 = 1;
    OPEN gcur_984;
    gl_984: LOOP
      FETCH gcur_984 INTO v_acct_984, v_dr_984, v_cr_984;
      IF v_gfin_984 = 1 THEN LEAVE gl_984; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_984, 'BALANCE',
              CONCAT('net ', CAST(v_dr_984 - v_cr_984 AS CHAR)));
    END LOOP;
    CLOSE gcur_984;
  END;

  -- transaction block 985: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_985;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_985;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 985, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 986: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_986;
    CREATE TEMPORARY TABLE tmp_agg_986 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_986 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_986 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_986;
  END;

  -- upsert block 987: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_987 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_987, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_987, 'MERGE', CONCAT('stock topped for ', CAST(v_key_987 AS CHAR)));
  END;

  -- json block 988: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_988 JSON;
    DECLARE v_sku_988 VARCHAR(40);
    DECLARE v_tag_988 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_988, v_sku_988, v_tag_988
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_988,''), ' tag ', IFNULL(v_tag_988,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_988, 'tag', v_tag_988) AS CHAR)));
  END;

  -- cte block 989: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_989 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_989 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_989 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_989 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 990: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_990 VARCHAR(10);
    DECLARE v_amt_990 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_990 FROM erp_order;
    SET v_band_990 = CASE
        WHEN v_amt_990 >= 10000 THEN 'HIGH'
        WHEN v_amt_990 >= 1000  THEN 'MED'
        WHEN v_amt_990 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_990, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_03  [procedure]
CREATE PROCEDURE erp_usp_stage_03()
BEGIN
  DECLARE v_amt_s03 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s03 INT DEFAULT 0;
  DECLARE v_fx_s03  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s03 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s03 VARCHAR(60);
  DECLARE v_av_s03  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s03  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 3, 'ERROR', 'stage 03 failed');
  END;
  START TRANSACTION;
  SET v_fx_s03  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s03 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s03 = erp_fn_json_tag(1);
  SET v_av_s03  = erp_fn_available_qty(1, 1);
  SET v_cr_s03  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s03, v_amt_s03 FROM erp_order;
  SET v_amt_s03 = v_amt_s03 + erp_fn_tax_amount(v_amt_s03, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_03', v_cnt_s03)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s03;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s03 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 3, 'CREDIT', 'stage 03 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 3, 'OK', CONCAT('stage 03 tag ', IFNULL(v_tag_s03,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s03, 'RUN_03',
       CONCAT('fx ', CAST(v_fx_s03 AS CHAR), ' mar ', CAST(v_mar_s03 AS CHAR)));
  CALL erp_usp_stage_04();

  -- repeat/while block 991: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_991 INT DEFAULT 0;
    DECLARE v_j_991 INT DEFAULT 0;
    DECLARE v_rc_991 INT DEFAULT 0;
    REPEAT
      SET v_i_991 = v_i_991 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R991'), v_i_991)
        ON DUPLICATE KEY UPDATE tick = v_i_991;
    UNTIL v_i_991 >= 3 END REPEAT;
    WHILE v_j_991 < 3 DO
      SET v_j_991 = v_j_991 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_991 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_991 + v_j_991, 'ITER',
            CONCAT('i ', CAST(v_i_991 AS CHAR), ' j ', CAST(v_j_991 AS CHAR),
                   ' diag ', CAST(v_rc_991 AS CHAR)));
  END;

  -- analytics block 992: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_992 INT DEFAULT 0;
    DECLARE v_amt_992 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_992 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_992 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_992, v_amt_992, v_avg_992, v_max_992
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_992 = v_amt_992 + erp_fn_tax_amount(v_amt_992, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_992, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_992 AS CHAR), ' avg ', CAST(v_avg_992 AS CHAR),
                   ' max ', CAST(v_max_992 AS CHAR)));
  END;

  -- reconcile block 993: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_993 INT DEFAULT 0;
    DECLARE v_pid_993 INT;
    DECLARE v_oh_993 DECIMAL(18,4);
    DECLARE v_av_993 DECIMAL(18,4);
    DECLARE cur_993 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_993 = 1;
    OPEN cur_993;
    rl_993: LOOP
      FETCH cur_993 INTO v_pid_993, v_oh_993;
      IF v_fin_993 = 1 THEN LEAVE rl_993; END IF;
      SET v_av_993 = erp_fn_available_qty(v_pid_993, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_993, 1, 'RECON', CAST(v_oh_993 - v_av_993 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_993 AS CHAR));
    END LOOP;
    CLOSE cur_993;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_993,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_993,0) AS CHAR)));
  END;

  -- dynamic-sql block 994: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_994 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_994 VARCHAR(64) DEFAULT 'status';
    SET @dsql_994 = CONCAT('SELECT COUNT(*) INTO @dcnt_994 FROM ', v_tbl_994,
                          ' WHERE ', v_col_994, ' = ?');
    SET @dparm_994 = 'NEW';
    PREPARE pst_994 FROM @dsql_994;
    EXECUTE pst_994 USING @dparm_994;
    DEALLOCATE PREPARE pst_994;
    SET @dupd_994 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_994 = 100;
    PREPARE pud_994 FROM @dupd_994;
    EXECUTE pud_994 USING @doid_994;
    DEALLOCATE PREPARE pud_994;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_994,0), 'COUNT',
            CONCAT('tbl ', v_tbl_994, ' col ', v_col_994));
  END;

  -- recursive block 995: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_995 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_995 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_995;
  END;

  -- reprice block 996: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_996 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_996;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_996, 'UPDATE', CONCAT('rows ', CAST(v_rows_996 AS CHAR)));
  END;

  -- validation block 997: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_997 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_997
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_997 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_997, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_997 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_997, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 998: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_998 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_998 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_998 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_998 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_998 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_998 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_998 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_998 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_998 AS CHAR), ' cr ', CAST(v_cr_998 AS CHAR),
                   ' dr ', CAST(v_dr_998 AS CHAR), ' tot ', CAST(v_tot_998 AS CHAR)));
  END;

  -- invoice rollup block 999: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_999 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_999 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_999
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_999
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_999 AS CHAR), ' paid ', CAST(v_paid_999 AS CHAR)));
  END;

  -- gl reconciliation block 1000: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1000 INT DEFAULT 0;
    DECLARE v_acct_1000 INT;
    DECLARE v_dr_1000 DECIMAL(18,2);
    DECLARE v_cr_1000 DECIMAL(18,2);
    DECLARE gcur_1000 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1000 = 1;
    OPEN gcur_1000;
    gl_1000: LOOP
      FETCH gcur_1000 INTO v_acct_1000, v_dr_1000, v_cr_1000;
      IF v_gfin_1000 = 1 THEN LEAVE gl_1000; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1000, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1000 - v_cr_1000 AS CHAR)));
    END LOOP;
    CLOSE gcur_1000;
  END;

  -- transaction block 1001: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1001;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1001;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1001, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1002: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1002;
    CREATE TEMPORARY TABLE tmp_agg_1002 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1002 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1002 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1002;
  END;

  -- upsert block 1003: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1003 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1003, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1003, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1003 AS CHAR)));
  END;

  -- json block 1004: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1004 JSON;
    DECLARE v_sku_1004 VARCHAR(40);
    DECLARE v_tag_1004 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1004, v_sku_1004, v_tag_1004
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1004,''), ' tag ', IFNULL(v_tag_1004,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1004, 'tag', v_tag_1004) AS CHAR)));
  END;

  -- cte block 1005: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1005 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1005 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1005 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1005 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_04  [procedure]
CREATE PROCEDURE erp_usp_stage_04()
BEGIN
  DECLARE v_amt_s04 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s04 INT DEFAULT 0;
  DECLARE v_fx_s04  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s04 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s04 VARCHAR(60);
  DECLARE v_av_s04  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s04  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 4, 'ERROR', 'stage 04 failed');
  END;
  START TRANSACTION;
  SET v_fx_s04  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s04 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s04 = erp_fn_json_tag(1);
  SET v_av_s04  = erp_fn_available_qty(1, 1);
  SET v_cr_s04  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s04, v_amt_s04 FROM erp_order;
  SET v_amt_s04 = v_amt_s04 + erp_fn_tax_amount(v_amt_s04, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_04', v_cnt_s04)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s04;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s04 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 4, 'CREDIT', 'stage 04 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 4, 'OK', CONCAT('stage 04 tag ', IFNULL(v_tag_s04,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s04, 'RUN_04',
       CONCAT('fx ', CAST(v_fx_s04 AS CHAR), ' mar ', CAST(v_mar_s04 AS CHAR)));
  CALL erp_usp_stage_05();

  -- case block 1006: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1006 VARCHAR(10);
    DECLARE v_amt_1006 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1006 FROM erp_order;
    SET v_band_1006 = CASE
        WHEN v_amt_1006 >= 10000 THEN 'HIGH'
        WHEN v_amt_1006 >= 1000  THEN 'MED'
        WHEN v_amt_1006 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1006, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1007: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1007 INT DEFAULT 0;
    DECLARE v_j_1007 INT DEFAULT 0;
    DECLARE v_rc_1007 INT DEFAULT 0;
    REPEAT
      SET v_i_1007 = v_i_1007 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1007'), v_i_1007)
        ON DUPLICATE KEY UPDATE tick = v_i_1007;
    UNTIL v_i_1007 >= 3 END REPEAT;
    WHILE v_j_1007 < 3 DO
      SET v_j_1007 = v_j_1007 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1007 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1007 + v_j_1007, 'ITER',
            CONCAT('i ', CAST(v_i_1007 AS CHAR), ' j ', CAST(v_j_1007 AS CHAR),
                   ' diag ', CAST(v_rc_1007 AS CHAR)));
  END;

  -- analytics block 1008: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1008 INT DEFAULT 0;
    DECLARE v_amt_1008 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1008 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1008 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1008, v_amt_1008, v_avg_1008, v_max_1008
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1008 = v_amt_1008 + erp_fn_tax_amount(v_amt_1008, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1008, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1008 AS CHAR), ' avg ', CAST(v_avg_1008 AS CHAR),
                   ' max ', CAST(v_max_1008 AS CHAR)));
  END;

  -- reconcile block 1009: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1009 INT DEFAULT 0;
    DECLARE v_pid_1009 INT;
    DECLARE v_oh_1009 DECIMAL(18,4);
    DECLARE v_av_1009 DECIMAL(18,4);
    DECLARE cur_1009 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1009 = 1;
    OPEN cur_1009;
    rl_1009: LOOP
      FETCH cur_1009 INTO v_pid_1009, v_oh_1009;
      IF v_fin_1009 = 1 THEN LEAVE rl_1009; END IF;
      SET v_av_1009 = erp_fn_available_qty(v_pid_1009, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1009, 1, 'RECON', CAST(v_oh_1009 - v_av_1009 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1009 AS CHAR));
    END LOOP;
    CLOSE cur_1009;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1009,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1009,0) AS CHAR)));
  END;

  -- dynamic-sql block 1010: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1010 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1010 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1010 = CONCAT('SELECT COUNT(*) INTO @dcnt_1010 FROM ', v_tbl_1010,
                          ' WHERE ', v_col_1010, ' = ?');
    SET @dparm_1010 = 'NEW';
    PREPARE pst_1010 FROM @dsql_1010;
    EXECUTE pst_1010 USING @dparm_1010;
    DEALLOCATE PREPARE pst_1010;
    SET @dupd_1010 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1010 = 100;
    PREPARE pud_1010 FROM @dupd_1010;
    EXECUTE pud_1010 USING @doid_1010;
    DEALLOCATE PREPARE pud_1010;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1010,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1010, ' col ', v_col_1010));
  END;

  -- recursive block 1011: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1011 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1011 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1011;
  END;

  -- reprice block 1012: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1012 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1012;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1012, 'UPDATE', CONCAT('rows ', CAST(v_rows_1012 AS CHAR)));
  END;

  -- validation block 1013: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1013 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1013
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1013 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1013, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1013 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1013, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1014: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1014 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1014 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1014 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1014 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1014 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1014 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1014 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1014 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1014 AS CHAR), ' cr ', CAST(v_cr_1014 AS CHAR),
                   ' dr ', CAST(v_dr_1014 AS CHAR), ' tot ', CAST(v_tot_1014 AS CHAR)));
  END;

  -- invoice rollup block 1015: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1015 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1015 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1015
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1015
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1015 AS CHAR), ' paid ', CAST(v_paid_1015 AS CHAR)));
  END;

  -- gl reconciliation block 1016: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1016 INT DEFAULT 0;
    DECLARE v_acct_1016 INT;
    DECLARE v_dr_1016 DECIMAL(18,2);
    DECLARE v_cr_1016 DECIMAL(18,2);
    DECLARE gcur_1016 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1016 = 1;
    OPEN gcur_1016;
    gl_1016: LOOP
      FETCH gcur_1016 INTO v_acct_1016, v_dr_1016, v_cr_1016;
      IF v_gfin_1016 = 1 THEN LEAVE gl_1016; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1016, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1016 - v_cr_1016 AS CHAR)));
    END LOOP;
    CLOSE gcur_1016;
  END;

  -- transaction block 1017: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1017;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1017;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1017, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1018: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1018;
    CREATE TEMPORARY TABLE tmp_agg_1018 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1018 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1018 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1018;
  END;

  -- upsert block 1019: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1019 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1019, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1019, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1019 AS CHAR)));
  END;

  -- json block 1020: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1020 JSON;
    DECLARE v_sku_1020 VARCHAR(40);
    DECLARE v_tag_1020 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1020, v_sku_1020, v_tag_1020
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1020,''), ' tag ', IFNULL(v_tag_1020,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1020, 'tag', v_tag_1020) AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_05  [procedure]
CREATE PROCEDURE erp_usp_stage_05()
BEGIN
  DECLARE v_amt_s05 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s05 INT DEFAULT 0;
  DECLARE v_fx_s05  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s05 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s05 VARCHAR(60);
  DECLARE v_av_s05  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s05  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 5, 'ERROR', 'stage 05 failed');
  END;
  START TRANSACTION;
  SET v_fx_s05  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s05 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s05 = erp_fn_json_tag(1);
  SET v_av_s05  = erp_fn_available_qty(1, 1);
  SET v_cr_s05  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s05, v_amt_s05 FROM erp_order;
  SET v_amt_s05 = v_amt_s05 + erp_fn_tax_amount(v_amt_s05, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_05', v_cnt_s05)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s05;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s05 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 5, 'CREDIT', 'stage 05 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 5, 'OK', CONCAT('stage 05 tag ', IFNULL(v_tag_s05,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s05, 'RUN_05',
       CONCAT('fx ', CAST(v_fx_s05 AS CHAR), ' mar ', CAST(v_mar_s05 AS CHAR)));
  CALL erp_usp_stage_06();

  -- cte block 1021: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1021 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1021 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1021 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1021 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1022: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1022 VARCHAR(10);
    DECLARE v_amt_1022 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1022 FROM erp_order;
    SET v_band_1022 = CASE
        WHEN v_amt_1022 >= 10000 THEN 'HIGH'
        WHEN v_amt_1022 >= 1000  THEN 'MED'
        WHEN v_amt_1022 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1022, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1023: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1023 INT DEFAULT 0;
    DECLARE v_j_1023 INT DEFAULT 0;
    DECLARE v_rc_1023 INT DEFAULT 0;
    REPEAT
      SET v_i_1023 = v_i_1023 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1023'), v_i_1023)
        ON DUPLICATE KEY UPDATE tick = v_i_1023;
    UNTIL v_i_1023 >= 3 END REPEAT;
    WHILE v_j_1023 < 3 DO
      SET v_j_1023 = v_j_1023 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1023 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1023 + v_j_1023, 'ITER',
            CONCAT('i ', CAST(v_i_1023 AS CHAR), ' j ', CAST(v_j_1023 AS CHAR),
                   ' diag ', CAST(v_rc_1023 AS CHAR)));
  END;

  -- analytics block 1024: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1024 INT DEFAULT 0;
    DECLARE v_amt_1024 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1024 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1024 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1024, v_amt_1024, v_avg_1024, v_max_1024
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1024 = v_amt_1024 + erp_fn_tax_amount(v_amt_1024, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1024, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1024 AS CHAR), ' avg ', CAST(v_avg_1024 AS CHAR),
                   ' max ', CAST(v_max_1024 AS CHAR)));
  END;

  -- reconcile block 1025: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1025 INT DEFAULT 0;
    DECLARE v_pid_1025 INT;
    DECLARE v_oh_1025 DECIMAL(18,4);
    DECLARE v_av_1025 DECIMAL(18,4);
    DECLARE cur_1025 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1025 = 1;
    OPEN cur_1025;
    rl_1025: LOOP
      FETCH cur_1025 INTO v_pid_1025, v_oh_1025;
      IF v_fin_1025 = 1 THEN LEAVE rl_1025; END IF;
      SET v_av_1025 = erp_fn_available_qty(v_pid_1025, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1025, 1, 'RECON', CAST(v_oh_1025 - v_av_1025 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1025 AS CHAR));
    END LOOP;
    CLOSE cur_1025;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1025,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1025,0) AS CHAR)));
  END;

  -- dynamic-sql block 1026: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1026 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1026 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1026 = CONCAT('SELECT COUNT(*) INTO @dcnt_1026 FROM ', v_tbl_1026,
                          ' WHERE ', v_col_1026, ' = ?');
    SET @dparm_1026 = 'NEW';
    PREPARE pst_1026 FROM @dsql_1026;
    EXECUTE pst_1026 USING @dparm_1026;
    DEALLOCATE PREPARE pst_1026;
    SET @dupd_1026 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1026 = 100;
    PREPARE pud_1026 FROM @dupd_1026;
    EXECUTE pud_1026 USING @doid_1026;
    DEALLOCATE PREPARE pud_1026;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1026,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1026, ' col ', v_col_1026));
  END;

  -- recursive block 1027: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1027 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1027 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1027;
  END;

  -- reprice block 1028: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1028 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1028;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1028, 'UPDATE', CONCAT('rows ', CAST(v_rows_1028 AS CHAR)));
  END;

  -- validation block 1029: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1029 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1029
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1029 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1029, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1029 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1029, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1030: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1030 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1030 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1030 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1030 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1030 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1030 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1030 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1030 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1030 AS CHAR), ' cr ', CAST(v_cr_1030 AS CHAR),
                   ' dr ', CAST(v_dr_1030 AS CHAR), ' tot ', CAST(v_tot_1030 AS CHAR)));
  END;

  -- invoice rollup block 1031: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1031 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1031 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1031
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1031
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1031 AS CHAR), ' paid ', CAST(v_paid_1031 AS CHAR)));
  END;

  -- gl reconciliation block 1032: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1032 INT DEFAULT 0;
    DECLARE v_acct_1032 INT;
    DECLARE v_dr_1032 DECIMAL(18,2);
    DECLARE v_cr_1032 DECIMAL(18,2);
    DECLARE gcur_1032 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1032 = 1;
    OPEN gcur_1032;
    gl_1032: LOOP
      FETCH gcur_1032 INTO v_acct_1032, v_dr_1032, v_cr_1032;
      IF v_gfin_1032 = 1 THEN LEAVE gl_1032; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1032, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1032 - v_cr_1032 AS CHAR)));
    END LOOP;
    CLOSE gcur_1032;
  END;

  -- transaction block 1033: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1033;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1033;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1033, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1034: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1034;
    CREATE TEMPORARY TABLE tmp_agg_1034 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1034 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1034 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1034;
  END;

  -- upsert block 1035: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1035 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1035, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1035, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1035 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_06  [procedure]
CREATE PROCEDURE erp_usp_stage_06()
BEGIN
  DECLARE v_amt_s06 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s06 INT DEFAULT 0;
  DECLARE v_fx_s06  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s06 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s06 VARCHAR(60);
  DECLARE v_av_s06  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s06  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 6, 'ERROR', 'stage 06 failed');
  END;
  START TRANSACTION;
  SET v_fx_s06  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s06 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s06 = erp_fn_json_tag(1);
  SET v_av_s06  = erp_fn_available_qty(1, 1);
  SET v_cr_s06  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s06, v_amt_s06 FROM erp_order;
  SET v_amt_s06 = v_amt_s06 + erp_fn_tax_amount(v_amt_s06, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_06', v_cnt_s06)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s06;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s06 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 6, 'CREDIT', 'stage 06 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 6, 'OK', CONCAT('stage 06 tag ', IFNULL(v_tag_s06,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s06, 'RUN_06',
       CONCAT('fx ', CAST(v_fx_s06 AS CHAR), ' mar ', CAST(v_mar_s06 AS CHAR)));
  CALL erp_usp_stage_07();

  -- json block 1036: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1036 JSON;
    DECLARE v_sku_1036 VARCHAR(40);
    DECLARE v_tag_1036 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1036, v_sku_1036, v_tag_1036
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1036,''), ' tag ', IFNULL(v_tag_1036,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1036, 'tag', v_tag_1036) AS CHAR)));
  END;

  -- cte block 1037: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1037 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1037 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1037 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1037 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1038: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1038 VARCHAR(10);
    DECLARE v_amt_1038 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1038 FROM erp_order;
    SET v_band_1038 = CASE
        WHEN v_amt_1038 >= 10000 THEN 'HIGH'
        WHEN v_amt_1038 >= 1000  THEN 'MED'
        WHEN v_amt_1038 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1038, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1039: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1039 INT DEFAULT 0;
    DECLARE v_j_1039 INT DEFAULT 0;
    DECLARE v_rc_1039 INT DEFAULT 0;
    REPEAT
      SET v_i_1039 = v_i_1039 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1039'), v_i_1039)
        ON DUPLICATE KEY UPDATE tick = v_i_1039;
    UNTIL v_i_1039 >= 3 END REPEAT;
    WHILE v_j_1039 < 3 DO
      SET v_j_1039 = v_j_1039 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1039 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1039 + v_j_1039, 'ITER',
            CONCAT('i ', CAST(v_i_1039 AS CHAR), ' j ', CAST(v_j_1039 AS CHAR),
                   ' diag ', CAST(v_rc_1039 AS CHAR)));
  END;

  -- analytics block 1040: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1040 INT DEFAULT 0;
    DECLARE v_amt_1040 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1040 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1040 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1040, v_amt_1040, v_avg_1040, v_max_1040
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1040 = v_amt_1040 + erp_fn_tax_amount(v_amt_1040, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1040, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1040 AS CHAR), ' avg ', CAST(v_avg_1040 AS CHAR),
                   ' max ', CAST(v_max_1040 AS CHAR)));
  END;

  -- reconcile block 1041: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1041 INT DEFAULT 0;
    DECLARE v_pid_1041 INT;
    DECLARE v_oh_1041 DECIMAL(18,4);
    DECLARE v_av_1041 DECIMAL(18,4);
    DECLARE cur_1041 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1041 = 1;
    OPEN cur_1041;
    rl_1041: LOOP
      FETCH cur_1041 INTO v_pid_1041, v_oh_1041;
      IF v_fin_1041 = 1 THEN LEAVE rl_1041; END IF;
      SET v_av_1041 = erp_fn_available_qty(v_pid_1041, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1041, 1, 'RECON', CAST(v_oh_1041 - v_av_1041 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1041 AS CHAR));
    END LOOP;
    CLOSE cur_1041;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1041,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1041,0) AS CHAR)));
  END;

  -- dynamic-sql block 1042: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1042 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1042 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1042 = CONCAT('SELECT COUNT(*) INTO @dcnt_1042 FROM ', v_tbl_1042,
                          ' WHERE ', v_col_1042, ' = ?');
    SET @dparm_1042 = 'NEW';
    PREPARE pst_1042 FROM @dsql_1042;
    EXECUTE pst_1042 USING @dparm_1042;
    DEALLOCATE PREPARE pst_1042;
    SET @dupd_1042 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1042 = 100;
    PREPARE pud_1042 FROM @dupd_1042;
    EXECUTE pud_1042 USING @doid_1042;
    DEALLOCATE PREPARE pud_1042;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1042,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1042, ' col ', v_col_1042));
  END;

  -- recursive block 1043: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1043 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1043 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1043;
  END;

  -- reprice block 1044: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1044 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1044;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1044, 'UPDATE', CONCAT('rows ', CAST(v_rows_1044 AS CHAR)));
  END;

  -- validation block 1045: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1045 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1045
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1045 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1045, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1045 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1045, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1046: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1046 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1046 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1046 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1046 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1046 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1046 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1046 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1046 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1046 AS CHAR), ' cr ', CAST(v_cr_1046 AS CHAR),
                   ' dr ', CAST(v_dr_1046 AS CHAR), ' tot ', CAST(v_tot_1046 AS CHAR)));
  END;

  -- invoice rollup block 1047: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1047 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1047 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1047
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1047
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1047 AS CHAR), ' paid ', CAST(v_paid_1047 AS CHAR)));
  END;

  -- gl reconciliation block 1048: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1048 INT DEFAULT 0;
    DECLARE v_acct_1048 INT;
    DECLARE v_dr_1048 DECIMAL(18,2);
    DECLARE v_cr_1048 DECIMAL(18,2);
    DECLARE gcur_1048 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1048 = 1;
    OPEN gcur_1048;
    gl_1048: LOOP
      FETCH gcur_1048 INTO v_acct_1048, v_dr_1048, v_cr_1048;
      IF v_gfin_1048 = 1 THEN LEAVE gl_1048; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1048, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1048 - v_cr_1048 AS CHAR)));
    END LOOP;
    CLOSE gcur_1048;
  END;

  -- transaction block 1049: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1049;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1049;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1049, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1050: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1050;
    CREATE TEMPORARY TABLE tmp_agg_1050 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1050 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1050 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1050;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_07  [procedure]
CREATE PROCEDURE erp_usp_stage_07()
BEGIN
  DECLARE v_amt_s07 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s07 INT DEFAULT 0;
  DECLARE v_fx_s07  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s07 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s07 VARCHAR(60);
  DECLARE v_av_s07  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s07  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 7, 'ERROR', 'stage 07 failed');
  END;
  START TRANSACTION;
  SET v_fx_s07  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s07 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s07 = erp_fn_json_tag(1);
  SET v_av_s07  = erp_fn_available_qty(1, 1);
  SET v_cr_s07  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s07, v_amt_s07 FROM erp_order;
  SET v_amt_s07 = v_amt_s07 + erp_fn_tax_amount(v_amt_s07, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_07', v_cnt_s07)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s07;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s07 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 7, 'CREDIT', 'stage 07 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 7, 'OK', CONCAT('stage 07 tag ', IFNULL(v_tag_s07,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s07, 'RUN_07',
       CONCAT('fx ', CAST(v_fx_s07 AS CHAR), ' mar ', CAST(v_mar_s07 AS CHAR)));
  CALL erp_usp_stage_08();

  -- upsert block 1051: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1051 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1051, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1051, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1051 AS CHAR)));
  END;

  -- json block 1052: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1052 JSON;
    DECLARE v_sku_1052 VARCHAR(40);
    DECLARE v_tag_1052 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1052, v_sku_1052, v_tag_1052
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1052,''), ' tag ', IFNULL(v_tag_1052,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1052, 'tag', v_tag_1052) AS CHAR)));
  END;

  -- cte block 1053: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1053 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1053 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1053 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1053 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1054: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1054 VARCHAR(10);
    DECLARE v_amt_1054 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1054 FROM erp_order;
    SET v_band_1054 = CASE
        WHEN v_amt_1054 >= 10000 THEN 'HIGH'
        WHEN v_amt_1054 >= 1000  THEN 'MED'
        WHEN v_amt_1054 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1054, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1055: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1055 INT DEFAULT 0;
    DECLARE v_j_1055 INT DEFAULT 0;
    DECLARE v_rc_1055 INT DEFAULT 0;
    REPEAT
      SET v_i_1055 = v_i_1055 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1055'), v_i_1055)
        ON DUPLICATE KEY UPDATE tick = v_i_1055;
    UNTIL v_i_1055 >= 3 END REPEAT;
    WHILE v_j_1055 < 3 DO
      SET v_j_1055 = v_j_1055 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1055 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1055 + v_j_1055, 'ITER',
            CONCAT('i ', CAST(v_i_1055 AS CHAR), ' j ', CAST(v_j_1055 AS CHAR),
                   ' diag ', CAST(v_rc_1055 AS CHAR)));
  END;

  -- analytics block 1056: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1056 INT DEFAULT 0;
    DECLARE v_amt_1056 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1056 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1056 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1056, v_amt_1056, v_avg_1056, v_max_1056
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1056 = v_amt_1056 + erp_fn_tax_amount(v_amt_1056, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1056, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1056 AS CHAR), ' avg ', CAST(v_avg_1056 AS CHAR),
                   ' max ', CAST(v_max_1056 AS CHAR)));
  END;

  -- reconcile block 1057: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1057 INT DEFAULT 0;
    DECLARE v_pid_1057 INT;
    DECLARE v_oh_1057 DECIMAL(18,4);
    DECLARE v_av_1057 DECIMAL(18,4);
    DECLARE cur_1057 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1057 = 1;
    OPEN cur_1057;
    rl_1057: LOOP
      FETCH cur_1057 INTO v_pid_1057, v_oh_1057;
      IF v_fin_1057 = 1 THEN LEAVE rl_1057; END IF;
      SET v_av_1057 = erp_fn_available_qty(v_pid_1057, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1057, 1, 'RECON', CAST(v_oh_1057 - v_av_1057 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1057 AS CHAR));
    END LOOP;
    CLOSE cur_1057;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1057,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1057,0) AS CHAR)));
  END;

  -- dynamic-sql block 1058: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1058 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1058 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1058 = CONCAT('SELECT COUNT(*) INTO @dcnt_1058 FROM ', v_tbl_1058,
                          ' WHERE ', v_col_1058, ' = ?');
    SET @dparm_1058 = 'NEW';
    PREPARE pst_1058 FROM @dsql_1058;
    EXECUTE pst_1058 USING @dparm_1058;
    DEALLOCATE PREPARE pst_1058;
    SET @dupd_1058 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1058 = 100;
    PREPARE pud_1058 FROM @dupd_1058;
    EXECUTE pud_1058 USING @doid_1058;
    DEALLOCATE PREPARE pud_1058;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1058,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1058, ' col ', v_col_1058));
  END;

  -- recursive block 1059: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1059 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1059 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1059;
  END;

  -- reprice block 1060: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1060 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1060;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1060, 'UPDATE', CONCAT('rows ', CAST(v_rows_1060 AS CHAR)));
  END;

  -- validation block 1061: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1061 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1061
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1061 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1061, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1061 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1061, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1062: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1062 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1062 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1062 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1062 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1062 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1062 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1062 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1062 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1062 AS CHAR), ' cr ', CAST(v_cr_1062 AS CHAR),
                   ' dr ', CAST(v_dr_1062 AS CHAR), ' tot ', CAST(v_tot_1062 AS CHAR)));
  END;

  -- invoice rollup block 1063: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1063 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1063 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1063
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1063
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1063 AS CHAR), ' paid ', CAST(v_paid_1063 AS CHAR)));
  END;

  -- gl reconciliation block 1064: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1064 INT DEFAULT 0;
    DECLARE v_acct_1064 INT;
    DECLARE v_dr_1064 DECIMAL(18,2);
    DECLARE v_cr_1064 DECIMAL(18,2);
    DECLARE gcur_1064 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1064 = 1;
    OPEN gcur_1064;
    gl_1064: LOOP
      FETCH gcur_1064 INTO v_acct_1064, v_dr_1064, v_cr_1064;
      IF v_gfin_1064 = 1 THEN LEAVE gl_1064; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1064, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1064 - v_cr_1064 AS CHAR)));
    END LOOP;
    CLOSE gcur_1064;
  END;

  -- transaction block 1065: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1065;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1065;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1065, 'COMMIT', 'savepoint block committed');
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_08  [procedure]
CREATE PROCEDURE erp_usp_stage_08()
BEGIN
  DECLARE v_amt_s08 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s08 INT DEFAULT 0;
  DECLARE v_fx_s08  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s08 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s08 VARCHAR(60);
  DECLARE v_av_s08  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s08  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 8, 'ERROR', 'stage 08 failed');
  END;
  START TRANSACTION;
  SET v_fx_s08  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s08 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s08 = erp_fn_json_tag(1);
  SET v_av_s08  = erp_fn_available_qty(1, 1);
  SET v_cr_s08  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s08, v_amt_s08 FROM erp_order;
  SET v_amt_s08 = v_amt_s08 + erp_fn_tax_amount(v_amt_s08, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_08', v_cnt_s08)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s08;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s08 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 8, 'CREDIT', 'stage 08 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 8, 'OK', CONCAT('stage 08 tag ', IFNULL(v_tag_s08,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s08, 'RUN_08',
       CONCAT('fx ', CAST(v_fx_s08 AS CHAR), ' mar ', CAST(v_mar_s08 AS CHAR)));
  CALL erp_usp_stage_09();

  -- temp-table block 1066: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1066;
    CREATE TEMPORARY TABLE tmp_agg_1066 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1066 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1066 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1066;
  END;

  -- upsert block 1067: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1067 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1067, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1067, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1067 AS CHAR)));
  END;

  -- json block 1068: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1068 JSON;
    DECLARE v_sku_1068 VARCHAR(40);
    DECLARE v_tag_1068 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1068, v_sku_1068, v_tag_1068
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1068,''), ' tag ', IFNULL(v_tag_1068,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1068, 'tag', v_tag_1068) AS CHAR)));
  END;

  -- cte block 1069: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1069 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1069 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1069 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1069 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1070: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1070 VARCHAR(10);
    DECLARE v_amt_1070 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1070 FROM erp_order;
    SET v_band_1070 = CASE
        WHEN v_amt_1070 >= 10000 THEN 'HIGH'
        WHEN v_amt_1070 >= 1000  THEN 'MED'
        WHEN v_amt_1070 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1070, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1071: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1071 INT DEFAULT 0;
    DECLARE v_j_1071 INT DEFAULT 0;
    DECLARE v_rc_1071 INT DEFAULT 0;
    REPEAT
      SET v_i_1071 = v_i_1071 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1071'), v_i_1071)
        ON DUPLICATE KEY UPDATE tick = v_i_1071;
    UNTIL v_i_1071 >= 3 END REPEAT;
    WHILE v_j_1071 < 3 DO
      SET v_j_1071 = v_j_1071 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1071 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1071 + v_j_1071, 'ITER',
            CONCAT('i ', CAST(v_i_1071 AS CHAR), ' j ', CAST(v_j_1071 AS CHAR),
                   ' diag ', CAST(v_rc_1071 AS CHAR)));
  END;

  -- analytics block 1072: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1072 INT DEFAULT 0;
    DECLARE v_amt_1072 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1072 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1072 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1072, v_amt_1072, v_avg_1072, v_max_1072
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1072 = v_amt_1072 + erp_fn_tax_amount(v_amt_1072, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1072, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1072 AS CHAR), ' avg ', CAST(v_avg_1072 AS CHAR),
                   ' max ', CAST(v_max_1072 AS CHAR)));
  END;

  -- reconcile block 1073: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1073 INT DEFAULT 0;
    DECLARE v_pid_1073 INT;
    DECLARE v_oh_1073 DECIMAL(18,4);
    DECLARE v_av_1073 DECIMAL(18,4);
    DECLARE cur_1073 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1073 = 1;
    OPEN cur_1073;
    rl_1073: LOOP
      FETCH cur_1073 INTO v_pid_1073, v_oh_1073;
      IF v_fin_1073 = 1 THEN LEAVE rl_1073; END IF;
      SET v_av_1073 = erp_fn_available_qty(v_pid_1073, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1073, 1, 'RECON', CAST(v_oh_1073 - v_av_1073 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1073 AS CHAR));
    END LOOP;
    CLOSE cur_1073;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1073,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1073,0) AS CHAR)));
  END;

  -- dynamic-sql block 1074: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1074 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1074 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1074 = CONCAT('SELECT COUNT(*) INTO @dcnt_1074 FROM ', v_tbl_1074,
                          ' WHERE ', v_col_1074, ' = ?');
    SET @dparm_1074 = 'NEW';
    PREPARE pst_1074 FROM @dsql_1074;
    EXECUTE pst_1074 USING @dparm_1074;
    DEALLOCATE PREPARE pst_1074;
    SET @dupd_1074 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1074 = 100;
    PREPARE pud_1074 FROM @dupd_1074;
    EXECUTE pud_1074 USING @doid_1074;
    DEALLOCATE PREPARE pud_1074;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1074,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1074, ' col ', v_col_1074));
  END;

  -- recursive block 1075: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1075 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1075 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1075;
  END;

  -- reprice block 1076: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1076 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1076;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1076, 'UPDATE', CONCAT('rows ', CAST(v_rows_1076 AS CHAR)));
  END;

  -- validation block 1077: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1077 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1077
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1077 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1077, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1077 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1077, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1078: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1078 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1078 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1078 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1078 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1078 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1078 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1078 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1078 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1078 AS CHAR), ' cr ', CAST(v_cr_1078 AS CHAR),
                   ' dr ', CAST(v_dr_1078 AS CHAR), ' tot ', CAST(v_tot_1078 AS CHAR)));
  END;

  -- invoice rollup block 1079: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1079 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1079 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1079
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1079
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1079 AS CHAR), ' paid ', CAST(v_paid_1079 AS CHAR)));
  END;

  -- gl reconciliation block 1080: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1080 INT DEFAULT 0;
    DECLARE v_acct_1080 INT;
    DECLARE v_dr_1080 DECIMAL(18,2);
    DECLARE v_cr_1080 DECIMAL(18,2);
    DECLARE gcur_1080 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1080 = 1;
    OPEN gcur_1080;
    gl_1080: LOOP
      FETCH gcur_1080 INTO v_acct_1080, v_dr_1080, v_cr_1080;
      IF v_gfin_1080 = 1 THEN LEAVE gl_1080; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1080, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1080 - v_cr_1080 AS CHAR)));
    END LOOP;
    CLOSE gcur_1080;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_09  [procedure]
CREATE PROCEDURE erp_usp_stage_09()
BEGIN
  DECLARE v_amt_s09 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s09 INT DEFAULT 0;
  DECLARE v_fx_s09  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s09 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s09 VARCHAR(60);
  DECLARE v_av_s09  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s09  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 9, 'ERROR', 'stage 09 failed');
  END;
  START TRANSACTION;
  SET v_fx_s09  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s09 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s09 = erp_fn_json_tag(1);
  SET v_av_s09  = erp_fn_available_qty(1, 1);
  SET v_cr_s09  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s09, v_amt_s09 FROM erp_order;
  SET v_amt_s09 = v_amt_s09 + erp_fn_tax_amount(v_amt_s09, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_09', v_cnt_s09)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s09;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s09 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 9, 'CREDIT', 'stage 09 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 9, 'OK', CONCAT('stage 09 tag ', IFNULL(v_tag_s09,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s09, 'RUN_09',
       CONCAT('fx ', CAST(v_fx_s09 AS CHAR), ' mar ', CAST(v_mar_s09 AS CHAR)));
  CALL erp_usp_stage_10();

  -- transaction block 1081: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1081;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1081;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1081, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1082: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1082;
    CREATE TEMPORARY TABLE tmp_agg_1082 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1082 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1082 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1082;
  END;

  -- upsert block 1083: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1083 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1083, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1083, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1083 AS CHAR)));
  END;

  -- json block 1084: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1084 JSON;
    DECLARE v_sku_1084 VARCHAR(40);
    DECLARE v_tag_1084 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1084, v_sku_1084, v_tag_1084
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1084,''), ' tag ', IFNULL(v_tag_1084,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1084, 'tag', v_tag_1084) AS CHAR)));
  END;

  -- cte block 1085: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1085 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1085 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1085 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1085 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1086: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1086 VARCHAR(10);
    DECLARE v_amt_1086 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1086 FROM erp_order;
    SET v_band_1086 = CASE
        WHEN v_amt_1086 >= 10000 THEN 'HIGH'
        WHEN v_amt_1086 >= 1000  THEN 'MED'
        WHEN v_amt_1086 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1086, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1087: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1087 INT DEFAULT 0;
    DECLARE v_j_1087 INT DEFAULT 0;
    DECLARE v_rc_1087 INT DEFAULT 0;
    REPEAT
      SET v_i_1087 = v_i_1087 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1087'), v_i_1087)
        ON DUPLICATE KEY UPDATE tick = v_i_1087;
    UNTIL v_i_1087 >= 3 END REPEAT;
    WHILE v_j_1087 < 3 DO
      SET v_j_1087 = v_j_1087 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1087 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1087 + v_j_1087, 'ITER',
            CONCAT('i ', CAST(v_i_1087 AS CHAR), ' j ', CAST(v_j_1087 AS CHAR),
                   ' diag ', CAST(v_rc_1087 AS CHAR)));
  END;

  -- analytics block 1088: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1088 INT DEFAULT 0;
    DECLARE v_amt_1088 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1088 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1088 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1088, v_amt_1088, v_avg_1088, v_max_1088
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1088 = v_amt_1088 + erp_fn_tax_amount(v_amt_1088, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1088, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1088 AS CHAR), ' avg ', CAST(v_avg_1088 AS CHAR),
                   ' max ', CAST(v_max_1088 AS CHAR)));
  END;

  -- reconcile block 1089: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1089 INT DEFAULT 0;
    DECLARE v_pid_1089 INT;
    DECLARE v_oh_1089 DECIMAL(18,4);
    DECLARE v_av_1089 DECIMAL(18,4);
    DECLARE cur_1089 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1089 = 1;
    OPEN cur_1089;
    rl_1089: LOOP
      FETCH cur_1089 INTO v_pid_1089, v_oh_1089;
      IF v_fin_1089 = 1 THEN LEAVE rl_1089; END IF;
      SET v_av_1089 = erp_fn_available_qty(v_pid_1089, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1089, 1, 'RECON', CAST(v_oh_1089 - v_av_1089 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1089 AS CHAR));
    END LOOP;
    CLOSE cur_1089;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1089,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1089,0) AS CHAR)));
  END;

  -- dynamic-sql block 1090: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1090 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1090 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1090 = CONCAT('SELECT COUNT(*) INTO @dcnt_1090 FROM ', v_tbl_1090,
                          ' WHERE ', v_col_1090, ' = ?');
    SET @dparm_1090 = 'NEW';
    PREPARE pst_1090 FROM @dsql_1090;
    EXECUTE pst_1090 USING @dparm_1090;
    DEALLOCATE PREPARE pst_1090;
    SET @dupd_1090 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1090 = 100;
    PREPARE pud_1090 FROM @dupd_1090;
    EXECUTE pud_1090 USING @doid_1090;
    DEALLOCATE PREPARE pud_1090;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1090,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1090, ' col ', v_col_1090));
  END;

  -- recursive block 1091: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1091 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1091 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1091;
  END;

  -- reprice block 1092: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1092 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1092;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1092, 'UPDATE', CONCAT('rows ', CAST(v_rows_1092 AS CHAR)));
  END;

  -- validation block 1093: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1093 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1093
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1093 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1093, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1093 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1093, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1094: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1094 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1094 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1094 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1094 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1094 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1094 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1094 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1094 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1094 AS CHAR), ' cr ', CAST(v_cr_1094 AS CHAR),
                   ' dr ', CAST(v_dr_1094 AS CHAR), ' tot ', CAST(v_tot_1094 AS CHAR)));
  END;

  -- invoice rollup block 1095: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1095 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1095 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1095
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1095
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1095 AS CHAR), ' paid ', CAST(v_paid_1095 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_10  [procedure]
CREATE PROCEDURE erp_usp_stage_10()
BEGIN
  DECLARE v_amt_s10 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s10 INT DEFAULT 0;
  DECLARE v_fx_s10  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s10 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s10 VARCHAR(60);
  DECLARE v_av_s10  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s10  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 10, 'ERROR', 'stage 10 failed');
  END;
  START TRANSACTION;
  SET v_fx_s10  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s10 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s10 = erp_fn_json_tag(1);
  SET v_av_s10  = erp_fn_available_qty(1, 1);
  SET v_cr_s10  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s10, v_amt_s10 FROM erp_order;
  SET v_amt_s10 = v_amt_s10 + erp_fn_tax_amount(v_amt_s10, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_10', v_cnt_s10)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s10;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s10 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 10, 'CREDIT', 'stage 10 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 10, 'OK', CONCAT('stage 10 tag ', IFNULL(v_tag_s10,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s10, 'RUN_10',
       CONCAT('fx ', CAST(v_fx_s10 AS CHAR), ' mar ', CAST(v_mar_s10 AS CHAR)));
  CALL erp_usp_stage_11();

  -- gl reconciliation block 1096: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1096 INT DEFAULT 0;
    DECLARE v_acct_1096 INT;
    DECLARE v_dr_1096 DECIMAL(18,2);
    DECLARE v_cr_1096 DECIMAL(18,2);
    DECLARE gcur_1096 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1096 = 1;
    OPEN gcur_1096;
    gl_1096: LOOP
      FETCH gcur_1096 INTO v_acct_1096, v_dr_1096, v_cr_1096;
      IF v_gfin_1096 = 1 THEN LEAVE gl_1096; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1096, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1096 - v_cr_1096 AS CHAR)));
    END LOOP;
    CLOSE gcur_1096;
  END;

  -- transaction block 1097: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1097;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1097;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1097, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1098: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1098;
    CREATE TEMPORARY TABLE tmp_agg_1098 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1098 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1098 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1098;
  END;

  -- upsert block 1099: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1099 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1099, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1099, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1099 AS CHAR)));
  END;

  -- json block 1100: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1100 JSON;
    DECLARE v_sku_1100 VARCHAR(40);
    DECLARE v_tag_1100 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1100, v_sku_1100, v_tag_1100
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1100,''), ' tag ', IFNULL(v_tag_1100,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1100, 'tag', v_tag_1100) AS CHAR)));
  END;

  -- cte block 1101: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1101 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1101 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1101 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1101 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1102: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1102 VARCHAR(10);
    DECLARE v_amt_1102 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1102 FROM erp_order;
    SET v_band_1102 = CASE
        WHEN v_amt_1102 >= 10000 THEN 'HIGH'
        WHEN v_amt_1102 >= 1000  THEN 'MED'
        WHEN v_amt_1102 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1102, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1103: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1103 INT DEFAULT 0;
    DECLARE v_j_1103 INT DEFAULT 0;
    DECLARE v_rc_1103 INT DEFAULT 0;
    REPEAT
      SET v_i_1103 = v_i_1103 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1103'), v_i_1103)
        ON DUPLICATE KEY UPDATE tick = v_i_1103;
    UNTIL v_i_1103 >= 3 END REPEAT;
    WHILE v_j_1103 < 3 DO
      SET v_j_1103 = v_j_1103 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1103 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1103 + v_j_1103, 'ITER',
            CONCAT('i ', CAST(v_i_1103 AS CHAR), ' j ', CAST(v_j_1103 AS CHAR),
                   ' diag ', CAST(v_rc_1103 AS CHAR)));
  END;

  -- analytics block 1104: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1104 INT DEFAULT 0;
    DECLARE v_amt_1104 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1104 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1104 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1104, v_amt_1104, v_avg_1104, v_max_1104
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1104 = v_amt_1104 + erp_fn_tax_amount(v_amt_1104, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1104, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1104 AS CHAR), ' avg ', CAST(v_avg_1104 AS CHAR),
                   ' max ', CAST(v_max_1104 AS CHAR)));
  END;

  -- reconcile block 1105: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1105 INT DEFAULT 0;
    DECLARE v_pid_1105 INT;
    DECLARE v_oh_1105 DECIMAL(18,4);
    DECLARE v_av_1105 DECIMAL(18,4);
    DECLARE cur_1105 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1105 = 1;
    OPEN cur_1105;
    rl_1105: LOOP
      FETCH cur_1105 INTO v_pid_1105, v_oh_1105;
      IF v_fin_1105 = 1 THEN LEAVE rl_1105; END IF;
      SET v_av_1105 = erp_fn_available_qty(v_pid_1105, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1105, 1, 'RECON', CAST(v_oh_1105 - v_av_1105 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1105 AS CHAR));
    END LOOP;
    CLOSE cur_1105;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1105,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1105,0) AS CHAR)));
  END;

  -- dynamic-sql block 1106: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1106 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1106 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1106 = CONCAT('SELECT COUNT(*) INTO @dcnt_1106 FROM ', v_tbl_1106,
                          ' WHERE ', v_col_1106, ' = ?');
    SET @dparm_1106 = 'NEW';
    PREPARE pst_1106 FROM @dsql_1106;
    EXECUTE pst_1106 USING @dparm_1106;
    DEALLOCATE PREPARE pst_1106;
    SET @dupd_1106 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1106 = 100;
    PREPARE pud_1106 FROM @dupd_1106;
    EXECUTE pud_1106 USING @doid_1106;
    DEALLOCATE PREPARE pud_1106;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1106,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1106, ' col ', v_col_1106));
  END;

  -- recursive block 1107: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1107 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1107 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1107;
  END;

  -- reprice block 1108: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1108 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1108;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1108, 'UPDATE', CONCAT('rows ', CAST(v_rows_1108 AS CHAR)));
  END;

  -- validation block 1109: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1109 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1109
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1109 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1109, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1109 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1109, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1110: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1110 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1110 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1110 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1110 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1110 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1110 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1110 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1110 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1110 AS CHAR), ' cr ', CAST(v_cr_1110 AS CHAR),
                   ' dr ', CAST(v_dr_1110 AS CHAR), ' tot ', CAST(v_tot_1110 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_11  [procedure]
CREATE PROCEDURE erp_usp_stage_11()
BEGIN
  DECLARE v_amt_s11 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s11 INT DEFAULT 0;
  DECLARE v_fx_s11  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s11 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s11 VARCHAR(60);
  DECLARE v_av_s11  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s11  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 11, 'ERROR', 'stage 11 failed');
  END;
  START TRANSACTION;
  SET v_fx_s11  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s11 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s11 = erp_fn_json_tag(1);
  SET v_av_s11  = erp_fn_available_qty(1, 1);
  SET v_cr_s11  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s11, v_amt_s11 FROM erp_order;
  SET v_amt_s11 = v_amt_s11 + erp_fn_tax_amount(v_amt_s11, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_11', v_cnt_s11)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s11;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s11 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 11, 'CREDIT', 'stage 11 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 11, 'OK', CONCAT('stage 11 tag ', IFNULL(v_tag_s11,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s11, 'RUN_11',
       CONCAT('fx ', CAST(v_fx_s11 AS CHAR), ' mar ', CAST(v_mar_s11 AS CHAR)));
  CALL erp_usp_stage_12();

  -- invoice rollup block 1111: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1111 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1111 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1111
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1111
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1111 AS CHAR), ' paid ', CAST(v_paid_1111 AS CHAR)));
  END;

  -- gl reconciliation block 1112: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1112 INT DEFAULT 0;
    DECLARE v_acct_1112 INT;
    DECLARE v_dr_1112 DECIMAL(18,2);
    DECLARE v_cr_1112 DECIMAL(18,2);
    DECLARE gcur_1112 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1112 = 1;
    OPEN gcur_1112;
    gl_1112: LOOP
      FETCH gcur_1112 INTO v_acct_1112, v_dr_1112, v_cr_1112;
      IF v_gfin_1112 = 1 THEN LEAVE gl_1112; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1112, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1112 - v_cr_1112 AS CHAR)));
    END LOOP;
    CLOSE gcur_1112;
  END;

  -- transaction block 1113: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1113;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1113;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1113, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1114: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1114;
    CREATE TEMPORARY TABLE tmp_agg_1114 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1114 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1114 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1114;
  END;

  -- upsert block 1115: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1115 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1115, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1115, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1115 AS CHAR)));
  END;

  -- json block 1116: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1116 JSON;
    DECLARE v_sku_1116 VARCHAR(40);
    DECLARE v_tag_1116 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1116, v_sku_1116, v_tag_1116
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1116,''), ' tag ', IFNULL(v_tag_1116,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1116, 'tag', v_tag_1116) AS CHAR)));
  END;

  -- cte block 1117: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1117 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1117 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1117 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1117 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1118: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1118 VARCHAR(10);
    DECLARE v_amt_1118 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1118 FROM erp_order;
    SET v_band_1118 = CASE
        WHEN v_amt_1118 >= 10000 THEN 'HIGH'
        WHEN v_amt_1118 >= 1000  THEN 'MED'
        WHEN v_amt_1118 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1118, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1119: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1119 INT DEFAULT 0;
    DECLARE v_j_1119 INT DEFAULT 0;
    DECLARE v_rc_1119 INT DEFAULT 0;
    REPEAT
      SET v_i_1119 = v_i_1119 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1119'), v_i_1119)
        ON DUPLICATE KEY UPDATE tick = v_i_1119;
    UNTIL v_i_1119 >= 3 END REPEAT;
    WHILE v_j_1119 < 3 DO
      SET v_j_1119 = v_j_1119 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1119 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1119 + v_j_1119, 'ITER',
            CONCAT('i ', CAST(v_i_1119 AS CHAR), ' j ', CAST(v_j_1119 AS CHAR),
                   ' diag ', CAST(v_rc_1119 AS CHAR)));
  END;

  -- analytics block 1120: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1120 INT DEFAULT 0;
    DECLARE v_amt_1120 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1120 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1120 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1120, v_amt_1120, v_avg_1120, v_max_1120
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1120 = v_amt_1120 + erp_fn_tax_amount(v_amt_1120, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1120, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1120 AS CHAR), ' avg ', CAST(v_avg_1120 AS CHAR),
                   ' max ', CAST(v_max_1120 AS CHAR)));
  END;

  -- reconcile block 1121: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1121 INT DEFAULT 0;
    DECLARE v_pid_1121 INT;
    DECLARE v_oh_1121 DECIMAL(18,4);
    DECLARE v_av_1121 DECIMAL(18,4);
    DECLARE cur_1121 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1121 = 1;
    OPEN cur_1121;
    rl_1121: LOOP
      FETCH cur_1121 INTO v_pid_1121, v_oh_1121;
      IF v_fin_1121 = 1 THEN LEAVE rl_1121; END IF;
      SET v_av_1121 = erp_fn_available_qty(v_pid_1121, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1121, 1, 'RECON', CAST(v_oh_1121 - v_av_1121 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1121 AS CHAR));
    END LOOP;
    CLOSE cur_1121;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1121,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1121,0) AS CHAR)));
  END;

  -- dynamic-sql block 1122: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1122 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1122 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1122 = CONCAT('SELECT COUNT(*) INTO @dcnt_1122 FROM ', v_tbl_1122,
                          ' WHERE ', v_col_1122, ' = ?');
    SET @dparm_1122 = 'NEW';
    PREPARE pst_1122 FROM @dsql_1122;
    EXECUTE pst_1122 USING @dparm_1122;
    DEALLOCATE PREPARE pst_1122;
    SET @dupd_1122 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1122 = 100;
    PREPARE pud_1122 FROM @dupd_1122;
    EXECUTE pud_1122 USING @doid_1122;
    DEALLOCATE PREPARE pud_1122;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1122,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1122, ' col ', v_col_1122));
  END;

  -- recursive block 1123: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1123 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1123 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1123;
  END;

  -- reprice block 1124: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1124 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1124;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1124, 'UPDATE', CONCAT('rows ', CAST(v_rows_1124 AS CHAR)));
  END;

  -- validation block 1125: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1125 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1125
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1125 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1125, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1125 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1125, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_12  [procedure]
CREATE PROCEDURE erp_usp_stage_12()
BEGIN
  DECLARE v_amt_s12 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s12 INT DEFAULT 0;
  DECLARE v_fx_s12  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s12 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s12 VARCHAR(60);
  DECLARE v_av_s12  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s12  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 12, 'ERROR', 'stage 12 failed');
  END;
  START TRANSACTION;
  SET v_fx_s12  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s12 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s12 = erp_fn_json_tag(1);
  SET v_av_s12  = erp_fn_available_qty(1, 1);
  SET v_cr_s12  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s12, v_amt_s12 FROM erp_order;
  SET v_amt_s12 = v_amt_s12 + erp_fn_tax_amount(v_amt_s12, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_12', v_cnt_s12)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s12;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s12 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 12, 'CREDIT', 'stage 12 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 12, 'OK', CONCAT('stage 12 tag ', IFNULL(v_tag_s12,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s12, 'RUN_12',
       CONCAT('fx ', CAST(v_fx_s12 AS CHAR), ' mar ', CAST(v_mar_s12 AS CHAR)));
  CALL erp_usp_stage_13();

  -- fx/credit block 1126: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1126 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1126 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1126 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1126 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1126 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1126 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1126 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1126 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1126 AS CHAR), ' cr ', CAST(v_cr_1126 AS CHAR),
                   ' dr ', CAST(v_dr_1126 AS CHAR), ' tot ', CAST(v_tot_1126 AS CHAR)));
  END;

  -- invoice rollup block 1127: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1127 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1127 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1127
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1127
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1127 AS CHAR), ' paid ', CAST(v_paid_1127 AS CHAR)));
  END;

  -- gl reconciliation block 1128: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1128 INT DEFAULT 0;
    DECLARE v_acct_1128 INT;
    DECLARE v_dr_1128 DECIMAL(18,2);
    DECLARE v_cr_1128 DECIMAL(18,2);
    DECLARE gcur_1128 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1128 = 1;
    OPEN gcur_1128;
    gl_1128: LOOP
      FETCH gcur_1128 INTO v_acct_1128, v_dr_1128, v_cr_1128;
      IF v_gfin_1128 = 1 THEN LEAVE gl_1128; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1128, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1128 - v_cr_1128 AS CHAR)));
    END LOOP;
    CLOSE gcur_1128;
  END;

  -- transaction block 1129: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1129;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1129;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1129, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1130: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1130;
    CREATE TEMPORARY TABLE tmp_agg_1130 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1130 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1130 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1130;
  END;

  -- upsert block 1131: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1131 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1131, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1131, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1131 AS CHAR)));
  END;

  -- json block 1132: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1132 JSON;
    DECLARE v_sku_1132 VARCHAR(40);
    DECLARE v_tag_1132 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1132, v_sku_1132, v_tag_1132
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1132,''), ' tag ', IFNULL(v_tag_1132,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1132, 'tag', v_tag_1132) AS CHAR)));
  END;

  -- cte block 1133: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1133 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1133 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1133 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1133 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1134: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1134 VARCHAR(10);
    DECLARE v_amt_1134 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1134 FROM erp_order;
    SET v_band_1134 = CASE
        WHEN v_amt_1134 >= 10000 THEN 'HIGH'
        WHEN v_amt_1134 >= 1000  THEN 'MED'
        WHEN v_amt_1134 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1134, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1135: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1135 INT DEFAULT 0;
    DECLARE v_j_1135 INT DEFAULT 0;
    DECLARE v_rc_1135 INT DEFAULT 0;
    REPEAT
      SET v_i_1135 = v_i_1135 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1135'), v_i_1135)
        ON DUPLICATE KEY UPDATE tick = v_i_1135;
    UNTIL v_i_1135 >= 3 END REPEAT;
    WHILE v_j_1135 < 3 DO
      SET v_j_1135 = v_j_1135 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1135 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1135 + v_j_1135, 'ITER',
            CONCAT('i ', CAST(v_i_1135 AS CHAR), ' j ', CAST(v_j_1135 AS CHAR),
                   ' diag ', CAST(v_rc_1135 AS CHAR)));
  END;

  -- analytics block 1136: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1136 INT DEFAULT 0;
    DECLARE v_amt_1136 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1136 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1136 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1136, v_amt_1136, v_avg_1136, v_max_1136
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1136 = v_amt_1136 + erp_fn_tax_amount(v_amt_1136, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1136, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1136 AS CHAR), ' avg ', CAST(v_avg_1136 AS CHAR),
                   ' max ', CAST(v_max_1136 AS CHAR)));
  END;

  -- reconcile block 1137: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1137 INT DEFAULT 0;
    DECLARE v_pid_1137 INT;
    DECLARE v_oh_1137 DECIMAL(18,4);
    DECLARE v_av_1137 DECIMAL(18,4);
    DECLARE cur_1137 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1137 = 1;
    OPEN cur_1137;
    rl_1137: LOOP
      FETCH cur_1137 INTO v_pid_1137, v_oh_1137;
      IF v_fin_1137 = 1 THEN LEAVE rl_1137; END IF;
      SET v_av_1137 = erp_fn_available_qty(v_pid_1137, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1137, 1, 'RECON', CAST(v_oh_1137 - v_av_1137 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1137 AS CHAR));
    END LOOP;
    CLOSE cur_1137;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1137,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1137,0) AS CHAR)));
  END;

  -- dynamic-sql block 1138: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1138 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1138 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1138 = CONCAT('SELECT COUNT(*) INTO @dcnt_1138 FROM ', v_tbl_1138,
                          ' WHERE ', v_col_1138, ' = ?');
    SET @dparm_1138 = 'NEW';
    PREPARE pst_1138 FROM @dsql_1138;
    EXECUTE pst_1138 USING @dparm_1138;
    DEALLOCATE PREPARE pst_1138;
    SET @dupd_1138 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1138 = 100;
    PREPARE pud_1138 FROM @dupd_1138;
    EXECUTE pud_1138 USING @doid_1138;
    DEALLOCATE PREPARE pud_1138;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1138,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1138, ' col ', v_col_1138));
  END;

  -- recursive block 1139: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1139 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1139 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1139;
  END;

  -- reprice block 1140: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1140 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1140;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1140, 'UPDATE', CONCAT('rows ', CAST(v_rows_1140 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_13  [procedure]
CREATE PROCEDURE erp_usp_stage_13()
BEGIN
  DECLARE v_amt_s13 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s13 INT DEFAULT 0;
  DECLARE v_fx_s13  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s13 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s13 VARCHAR(60);
  DECLARE v_av_s13  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s13  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 13, 'ERROR', 'stage 13 failed');
  END;
  START TRANSACTION;
  SET v_fx_s13  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s13 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s13 = erp_fn_json_tag(1);
  SET v_av_s13  = erp_fn_available_qty(1, 1);
  SET v_cr_s13  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s13, v_amt_s13 FROM erp_order;
  SET v_amt_s13 = v_amt_s13 + erp_fn_tax_amount(v_amt_s13, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_13', v_cnt_s13)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s13;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s13 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 13, 'CREDIT', 'stage 13 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 13, 'OK', CONCAT('stage 13 tag ', IFNULL(v_tag_s13,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s13, 'RUN_13',
       CONCAT('fx ', CAST(v_fx_s13 AS CHAR), ' mar ', CAST(v_mar_s13 AS CHAR)));
  CALL erp_usp_stage_14();

  -- validation block 1141: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1141 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1141
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1141 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1141, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1141 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1141, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1142: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1142 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1142 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1142 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1142 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1142 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1142 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1142 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1142 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1142 AS CHAR), ' cr ', CAST(v_cr_1142 AS CHAR),
                   ' dr ', CAST(v_dr_1142 AS CHAR), ' tot ', CAST(v_tot_1142 AS CHAR)));
  END;

  -- invoice rollup block 1143: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1143 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1143 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1143
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1143
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1143 AS CHAR), ' paid ', CAST(v_paid_1143 AS CHAR)));
  END;

  -- gl reconciliation block 1144: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1144 INT DEFAULT 0;
    DECLARE v_acct_1144 INT;
    DECLARE v_dr_1144 DECIMAL(18,2);
    DECLARE v_cr_1144 DECIMAL(18,2);
    DECLARE gcur_1144 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1144 = 1;
    OPEN gcur_1144;
    gl_1144: LOOP
      FETCH gcur_1144 INTO v_acct_1144, v_dr_1144, v_cr_1144;
      IF v_gfin_1144 = 1 THEN LEAVE gl_1144; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1144, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1144 - v_cr_1144 AS CHAR)));
    END LOOP;
    CLOSE gcur_1144;
  END;

  -- transaction block 1145: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1145;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1145;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1145, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1146: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1146;
    CREATE TEMPORARY TABLE tmp_agg_1146 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1146 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1146 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1146;
  END;

  -- upsert block 1147: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1147 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1147, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1147, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1147 AS CHAR)));
  END;

  -- json block 1148: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1148 JSON;
    DECLARE v_sku_1148 VARCHAR(40);
    DECLARE v_tag_1148 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1148, v_sku_1148, v_tag_1148
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1148,''), ' tag ', IFNULL(v_tag_1148,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1148, 'tag', v_tag_1148) AS CHAR)));
  END;

  -- cte block 1149: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1149 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1149 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1149 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1149 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1150: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1150 VARCHAR(10);
    DECLARE v_amt_1150 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1150 FROM erp_order;
    SET v_band_1150 = CASE
        WHEN v_amt_1150 >= 10000 THEN 'HIGH'
        WHEN v_amt_1150 >= 1000  THEN 'MED'
        WHEN v_amt_1150 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1150, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1151: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1151 INT DEFAULT 0;
    DECLARE v_j_1151 INT DEFAULT 0;
    DECLARE v_rc_1151 INT DEFAULT 0;
    REPEAT
      SET v_i_1151 = v_i_1151 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1151'), v_i_1151)
        ON DUPLICATE KEY UPDATE tick = v_i_1151;
    UNTIL v_i_1151 >= 3 END REPEAT;
    WHILE v_j_1151 < 3 DO
      SET v_j_1151 = v_j_1151 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1151 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1151 + v_j_1151, 'ITER',
            CONCAT('i ', CAST(v_i_1151 AS CHAR), ' j ', CAST(v_j_1151 AS CHAR),
                   ' diag ', CAST(v_rc_1151 AS CHAR)));
  END;

  -- analytics block 1152: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1152 INT DEFAULT 0;
    DECLARE v_amt_1152 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1152 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1152 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1152, v_amt_1152, v_avg_1152, v_max_1152
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1152 = v_amt_1152 + erp_fn_tax_amount(v_amt_1152, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1152, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1152 AS CHAR), ' avg ', CAST(v_avg_1152 AS CHAR),
                   ' max ', CAST(v_max_1152 AS CHAR)));
  END;

  -- reconcile block 1153: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1153 INT DEFAULT 0;
    DECLARE v_pid_1153 INT;
    DECLARE v_oh_1153 DECIMAL(18,4);
    DECLARE v_av_1153 DECIMAL(18,4);
    DECLARE cur_1153 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1153 = 1;
    OPEN cur_1153;
    rl_1153: LOOP
      FETCH cur_1153 INTO v_pid_1153, v_oh_1153;
      IF v_fin_1153 = 1 THEN LEAVE rl_1153; END IF;
      SET v_av_1153 = erp_fn_available_qty(v_pid_1153, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1153, 1, 'RECON', CAST(v_oh_1153 - v_av_1153 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1153 AS CHAR));
    END LOOP;
    CLOSE cur_1153;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1153,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1153,0) AS CHAR)));
  END;

  -- dynamic-sql block 1154: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1154 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1154 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1154 = CONCAT('SELECT COUNT(*) INTO @dcnt_1154 FROM ', v_tbl_1154,
                          ' WHERE ', v_col_1154, ' = ?');
    SET @dparm_1154 = 'NEW';
    PREPARE pst_1154 FROM @dsql_1154;
    EXECUTE pst_1154 USING @dparm_1154;
    DEALLOCATE PREPARE pst_1154;
    SET @dupd_1154 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1154 = 100;
    PREPARE pud_1154 FROM @dupd_1154;
    EXECUTE pud_1154 USING @doid_1154;
    DEALLOCATE PREPARE pud_1154;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1154,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1154, ' col ', v_col_1154));
  END;

  -- recursive block 1155: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1155 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1155 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1155;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_14  [procedure]
CREATE PROCEDURE erp_usp_stage_14()
BEGIN
  DECLARE v_amt_s14 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s14 INT DEFAULT 0;
  DECLARE v_fx_s14  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s14 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s14 VARCHAR(60);
  DECLARE v_av_s14  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s14  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 14, 'ERROR', 'stage 14 failed');
  END;
  START TRANSACTION;
  SET v_fx_s14  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s14 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s14 = erp_fn_json_tag(1);
  SET v_av_s14  = erp_fn_available_qty(1, 1);
  SET v_cr_s14  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s14, v_amt_s14 FROM erp_order;
  SET v_amt_s14 = v_amt_s14 + erp_fn_tax_amount(v_amt_s14, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_14', v_cnt_s14)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s14;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s14 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 14, 'CREDIT', 'stage 14 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 14, 'OK', CONCAT('stage 14 tag ', IFNULL(v_tag_s14,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s14, 'RUN_14',
       CONCAT('fx ', CAST(v_fx_s14 AS CHAR), ' mar ', CAST(v_mar_s14 AS CHAR)));
  CALL erp_usp_stage_15();

  -- reprice block 1156: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1156 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1156;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1156, 'UPDATE', CONCAT('rows ', CAST(v_rows_1156 AS CHAR)));
  END;

  -- validation block 1157: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1157 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1157
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1157 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1157, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1157 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1157, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1158: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1158 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1158 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1158 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1158 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1158 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1158 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1158 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1158 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1158 AS CHAR), ' cr ', CAST(v_cr_1158 AS CHAR),
                   ' dr ', CAST(v_dr_1158 AS CHAR), ' tot ', CAST(v_tot_1158 AS CHAR)));
  END;

  -- invoice rollup block 1159: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1159 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1159 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1159
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1159
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1159 AS CHAR), ' paid ', CAST(v_paid_1159 AS CHAR)));
  END;

  -- gl reconciliation block 1160: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1160 INT DEFAULT 0;
    DECLARE v_acct_1160 INT;
    DECLARE v_dr_1160 DECIMAL(18,2);
    DECLARE v_cr_1160 DECIMAL(18,2);
    DECLARE gcur_1160 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1160 = 1;
    OPEN gcur_1160;
    gl_1160: LOOP
      FETCH gcur_1160 INTO v_acct_1160, v_dr_1160, v_cr_1160;
      IF v_gfin_1160 = 1 THEN LEAVE gl_1160; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1160, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1160 - v_cr_1160 AS CHAR)));
    END LOOP;
    CLOSE gcur_1160;
  END;

  -- transaction block 1161: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1161;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1161;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1161, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1162: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1162;
    CREATE TEMPORARY TABLE tmp_agg_1162 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1162 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1162 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1162;
  END;

  -- upsert block 1163: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1163 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1163, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1163, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1163 AS CHAR)));
  END;

  -- json block 1164: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1164 JSON;
    DECLARE v_sku_1164 VARCHAR(40);
    DECLARE v_tag_1164 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1164, v_sku_1164, v_tag_1164
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1164,''), ' tag ', IFNULL(v_tag_1164,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1164, 'tag', v_tag_1164) AS CHAR)));
  END;

  -- cte block 1165: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1165 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1165 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1165 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1165 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1166: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1166 VARCHAR(10);
    DECLARE v_amt_1166 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1166 FROM erp_order;
    SET v_band_1166 = CASE
        WHEN v_amt_1166 >= 10000 THEN 'HIGH'
        WHEN v_amt_1166 >= 1000  THEN 'MED'
        WHEN v_amt_1166 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1166, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1167: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1167 INT DEFAULT 0;
    DECLARE v_j_1167 INT DEFAULT 0;
    DECLARE v_rc_1167 INT DEFAULT 0;
    REPEAT
      SET v_i_1167 = v_i_1167 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1167'), v_i_1167)
        ON DUPLICATE KEY UPDATE tick = v_i_1167;
    UNTIL v_i_1167 >= 3 END REPEAT;
    WHILE v_j_1167 < 3 DO
      SET v_j_1167 = v_j_1167 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1167 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1167 + v_j_1167, 'ITER',
            CONCAT('i ', CAST(v_i_1167 AS CHAR), ' j ', CAST(v_j_1167 AS CHAR),
                   ' diag ', CAST(v_rc_1167 AS CHAR)));
  END;

  -- analytics block 1168: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1168 INT DEFAULT 0;
    DECLARE v_amt_1168 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1168 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1168 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1168, v_amt_1168, v_avg_1168, v_max_1168
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1168 = v_amt_1168 + erp_fn_tax_amount(v_amt_1168, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1168, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1168 AS CHAR), ' avg ', CAST(v_avg_1168 AS CHAR),
                   ' max ', CAST(v_max_1168 AS CHAR)));
  END;

  -- reconcile block 1169: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1169 INT DEFAULT 0;
    DECLARE v_pid_1169 INT;
    DECLARE v_oh_1169 DECIMAL(18,4);
    DECLARE v_av_1169 DECIMAL(18,4);
    DECLARE cur_1169 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1169 = 1;
    OPEN cur_1169;
    rl_1169: LOOP
      FETCH cur_1169 INTO v_pid_1169, v_oh_1169;
      IF v_fin_1169 = 1 THEN LEAVE rl_1169; END IF;
      SET v_av_1169 = erp_fn_available_qty(v_pid_1169, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1169, 1, 'RECON', CAST(v_oh_1169 - v_av_1169 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1169 AS CHAR));
    END LOOP;
    CLOSE cur_1169;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1169,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1169,0) AS CHAR)));
  END;

  -- dynamic-sql block 1170: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1170 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1170 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1170 = CONCAT('SELECT COUNT(*) INTO @dcnt_1170 FROM ', v_tbl_1170,
                          ' WHERE ', v_col_1170, ' = ?');
    SET @dparm_1170 = 'NEW';
    PREPARE pst_1170 FROM @dsql_1170;
    EXECUTE pst_1170 USING @dparm_1170;
    DEALLOCATE PREPARE pst_1170;
    SET @dupd_1170 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1170 = 100;
    PREPARE pud_1170 FROM @dupd_1170;
    EXECUTE pud_1170 USING @doid_1170;
    DEALLOCATE PREPARE pud_1170;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1170,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1170, ' col ', v_col_1170));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_15  [procedure]
CREATE PROCEDURE erp_usp_stage_15()
BEGIN
  DECLARE v_amt_s15 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s15 INT DEFAULT 0;
  DECLARE v_fx_s15  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s15 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s15 VARCHAR(60);
  DECLARE v_av_s15  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s15  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 15, 'ERROR', 'stage 15 failed');
  END;
  START TRANSACTION;
  SET v_fx_s15  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s15 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s15 = erp_fn_json_tag(1);
  SET v_av_s15  = erp_fn_available_qty(1, 1);
  SET v_cr_s15  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s15, v_amt_s15 FROM erp_order;
  SET v_amt_s15 = v_amt_s15 + erp_fn_tax_amount(v_amt_s15, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_15', v_cnt_s15)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s15;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s15 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 15, 'CREDIT', 'stage 15 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 15, 'OK', CONCAT('stage 15 tag ', IFNULL(v_tag_s15,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s15, 'RUN_15',
       CONCAT('fx ', CAST(v_fx_s15 AS CHAR), ' mar ', CAST(v_mar_s15 AS CHAR)));
  CALL erp_usp_stage_16();

  -- recursive block 1171: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1171 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1171 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1171;
  END;

  -- reprice block 1172: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1172 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1172;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1172, 'UPDATE', CONCAT('rows ', CAST(v_rows_1172 AS CHAR)));
  END;

  -- validation block 1173: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1173 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1173
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1173 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1173, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1173 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1173, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1174: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1174 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1174 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1174 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1174 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1174 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1174 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1174 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1174 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1174 AS CHAR), ' cr ', CAST(v_cr_1174 AS CHAR),
                   ' dr ', CAST(v_dr_1174 AS CHAR), ' tot ', CAST(v_tot_1174 AS CHAR)));
  END;

  -- invoice rollup block 1175: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1175 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1175 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1175
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1175
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1175 AS CHAR), ' paid ', CAST(v_paid_1175 AS CHAR)));
  END;

  -- gl reconciliation block 1176: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1176 INT DEFAULT 0;
    DECLARE v_acct_1176 INT;
    DECLARE v_dr_1176 DECIMAL(18,2);
    DECLARE v_cr_1176 DECIMAL(18,2);
    DECLARE gcur_1176 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1176 = 1;
    OPEN gcur_1176;
    gl_1176: LOOP
      FETCH gcur_1176 INTO v_acct_1176, v_dr_1176, v_cr_1176;
      IF v_gfin_1176 = 1 THEN LEAVE gl_1176; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1176, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1176 - v_cr_1176 AS CHAR)));
    END LOOP;
    CLOSE gcur_1176;
  END;

  -- transaction block 1177: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1177;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1177;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1177, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1178: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1178;
    CREATE TEMPORARY TABLE tmp_agg_1178 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1178 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1178 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1178;
  END;

  -- upsert block 1179: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1179 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1179, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1179, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1179 AS CHAR)));
  END;

  -- json block 1180: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1180 JSON;
    DECLARE v_sku_1180 VARCHAR(40);
    DECLARE v_tag_1180 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1180, v_sku_1180, v_tag_1180
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1180,''), ' tag ', IFNULL(v_tag_1180,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1180, 'tag', v_tag_1180) AS CHAR)));
  END;

  -- cte block 1181: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1181 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1181 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1181 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1181 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1182: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1182 VARCHAR(10);
    DECLARE v_amt_1182 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1182 FROM erp_order;
    SET v_band_1182 = CASE
        WHEN v_amt_1182 >= 10000 THEN 'HIGH'
        WHEN v_amt_1182 >= 1000  THEN 'MED'
        WHEN v_amt_1182 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1182, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1183: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1183 INT DEFAULT 0;
    DECLARE v_j_1183 INT DEFAULT 0;
    DECLARE v_rc_1183 INT DEFAULT 0;
    REPEAT
      SET v_i_1183 = v_i_1183 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1183'), v_i_1183)
        ON DUPLICATE KEY UPDATE tick = v_i_1183;
    UNTIL v_i_1183 >= 3 END REPEAT;
    WHILE v_j_1183 < 3 DO
      SET v_j_1183 = v_j_1183 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1183 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1183 + v_j_1183, 'ITER',
            CONCAT('i ', CAST(v_i_1183 AS CHAR), ' j ', CAST(v_j_1183 AS CHAR),
                   ' diag ', CAST(v_rc_1183 AS CHAR)));
  END;

  -- analytics block 1184: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1184 INT DEFAULT 0;
    DECLARE v_amt_1184 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1184 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1184 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1184, v_amt_1184, v_avg_1184, v_max_1184
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1184 = v_amt_1184 + erp_fn_tax_amount(v_amt_1184, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1184, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1184 AS CHAR), ' avg ', CAST(v_avg_1184 AS CHAR),
                   ' max ', CAST(v_max_1184 AS CHAR)));
  END;

  -- reconcile block 1185: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1185 INT DEFAULT 0;
    DECLARE v_pid_1185 INT;
    DECLARE v_oh_1185 DECIMAL(18,4);
    DECLARE v_av_1185 DECIMAL(18,4);
    DECLARE cur_1185 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1185 = 1;
    OPEN cur_1185;
    rl_1185: LOOP
      FETCH cur_1185 INTO v_pid_1185, v_oh_1185;
      IF v_fin_1185 = 1 THEN LEAVE rl_1185; END IF;
      SET v_av_1185 = erp_fn_available_qty(v_pid_1185, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1185, 1, 'RECON', CAST(v_oh_1185 - v_av_1185 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1185 AS CHAR));
    END LOOP;
    CLOSE cur_1185;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1185,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1185,0) AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_16  [procedure]
CREATE PROCEDURE erp_usp_stage_16()
BEGIN
  DECLARE v_amt_s16 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s16 INT DEFAULT 0;
  DECLARE v_fx_s16  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s16 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s16 VARCHAR(60);
  DECLARE v_av_s16  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s16  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 16, 'ERROR', 'stage 16 failed');
  END;
  START TRANSACTION;
  SET v_fx_s16  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s16 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s16 = erp_fn_json_tag(1);
  SET v_av_s16  = erp_fn_available_qty(1, 1);
  SET v_cr_s16  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s16, v_amt_s16 FROM erp_order;
  SET v_amt_s16 = v_amt_s16 + erp_fn_tax_amount(v_amt_s16, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_16', v_cnt_s16)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s16;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s16 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 16, 'CREDIT', 'stage 16 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 16, 'OK', CONCAT('stage 16 tag ', IFNULL(v_tag_s16,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s16, 'RUN_16',
       CONCAT('fx ', CAST(v_fx_s16 AS CHAR), ' mar ', CAST(v_mar_s16 AS CHAR)));
  CALL erp_usp_stage_17();

  -- dynamic-sql block 1186: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1186 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1186 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1186 = CONCAT('SELECT COUNT(*) INTO @dcnt_1186 FROM ', v_tbl_1186,
                          ' WHERE ', v_col_1186, ' = ?');
    SET @dparm_1186 = 'NEW';
    PREPARE pst_1186 FROM @dsql_1186;
    EXECUTE pst_1186 USING @dparm_1186;
    DEALLOCATE PREPARE pst_1186;
    SET @dupd_1186 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1186 = 100;
    PREPARE pud_1186 FROM @dupd_1186;
    EXECUTE pud_1186 USING @doid_1186;
    DEALLOCATE PREPARE pud_1186;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1186,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1186, ' col ', v_col_1186));
  END;

  -- recursive block 1187: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1187 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1187 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1187;
  END;

  -- reprice block 1188: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1188 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1188;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1188, 'UPDATE', CONCAT('rows ', CAST(v_rows_1188 AS CHAR)));
  END;

  -- validation block 1189: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1189 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1189
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1189 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1189, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1189 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1189, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1190: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1190 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1190 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1190 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1190 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1190 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1190 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1190 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1190 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1190 AS CHAR), ' cr ', CAST(v_cr_1190 AS CHAR),
                   ' dr ', CAST(v_dr_1190 AS CHAR), ' tot ', CAST(v_tot_1190 AS CHAR)));
  END;

  -- invoice rollup block 1191: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1191 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1191 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1191
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1191
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1191 AS CHAR), ' paid ', CAST(v_paid_1191 AS CHAR)));
  END;

  -- gl reconciliation block 1192: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1192 INT DEFAULT 0;
    DECLARE v_acct_1192 INT;
    DECLARE v_dr_1192 DECIMAL(18,2);
    DECLARE v_cr_1192 DECIMAL(18,2);
    DECLARE gcur_1192 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1192 = 1;
    OPEN gcur_1192;
    gl_1192: LOOP
      FETCH gcur_1192 INTO v_acct_1192, v_dr_1192, v_cr_1192;
      IF v_gfin_1192 = 1 THEN LEAVE gl_1192; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1192, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1192 - v_cr_1192 AS CHAR)));
    END LOOP;
    CLOSE gcur_1192;
  END;

  -- transaction block 1193: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1193;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1193;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1193, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1194: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1194;
    CREATE TEMPORARY TABLE tmp_agg_1194 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1194 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1194 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1194;
  END;

  -- upsert block 1195: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1195 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1195, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1195, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1195 AS CHAR)));
  END;

  -- json block 1196: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1196 JSON;
    DECLARE v_sku_1196 VARCHAR(40);
    DECLARE v_tag_1196 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1196, v_sku_1196, v_tag_1196
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1196,''), ' tag ', IFNULL(v_tag_1196,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1196, 'tag', v_tag_1196) AS CHAR)));
  END;

  -- cte block 1197: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1197 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1197 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1197 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1197 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1198: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1198 VARCHAR(10);
    DECLARE v_amt_1198 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1198 FROM erp_order;
    SET v_band_1198 = CASE
        WHEN v_amt_1198 >= 10000 THEN 'HIGH'
        WHEN v_amt_1198 >= 1000  THEN 'MED'
        WHEN v_amt_1198 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1198, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1199: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1199 INT DEFAULT 0;
    DECLARE v_j_1199 INT DEFAULT 0;
    DECLARE v_rc_1199 INT DEFAULT 0;
    REPEAT
      SET v_i_1199 = v_i_1199 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1199'), v_i_1199)
        ON DUPLICATE KEY UPDATE tick = v_i_1199;
    UNTIL v_i_1199 >= 3 END REPEAT;
    WHILE v_j_1199 < 3 DO
      SET v_j_1199 = v_j_1199 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1199 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1199 + v_j_1199, 'ITER',
            CONCAT('i ', CAST(v_i_1199 AS CHAR), ' j ', CAST(v_j_1199 AS CHAR),
                   ' diag ', CAST(v_rc_1199 AS CHAR)));
  END;

  -- analytics block 1200: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1200 INT DEFAULT 0;
    DECLARE v_amt_1200 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1200 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1200 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1200, v_amt_1200, v_avg_1200, v_max_1200
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1200 = v_amt_1200 + erp_fn_tax_amount(v_amt_1200, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1200, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1200 AS CHAR), ' avg ', CAST(v_avg_1200 AS CHAR),
                   ' max ', CAST(v_max_1200 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_17  [procedure]
CREATE PROCEDURE erp_usp_stage_17()
BEGIN
  DECLARE v_amt_s17 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s17 INT DEFAULT 0;
  DECLARE v_fx_s17  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s17 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s17 VARCHAR(60);
  DECLARE v_av_s17  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s17  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 17, 'ERROR', 'stage 17 failed');
  END;
  START TRANSACTION;
  SET v_fx_s17  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s17 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s17 = erp_fn_json_tag(1);
  SET v_av_s17  = erp_fn_available_qty(1, 1);
  SET v_cr_s17  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s17, v_amt_s17 FROM erp_order;
  SET v_amt_s17 = v_amt_s17 + erp_fn_tax_amount(v_amt_s17, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_17', v_cnt_s17)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s17;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s17 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 17, 'CREDIT', 'stage 17 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 17, 'OK', CONCAT('stage 17 tag ', IFNULL(v_tag_s17,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s17, 'RUN_17',
       CONCAT('fx ', CAST(v_fx_s17 AS CHAR), ' mar ', CAST(v_mar_s17 AS CHAR)));
  CALL erp_usp_stage_18();

  -- reconcile block 1201: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1201 INT DEFAULT 0;
    DECLARE v_pid_1201 INT;
    DECLARE v_oh_1201 DECIMAL(18,4);
    DECLARE v_av_1201 DECIMAL(18,4);
    DECLARE cur_1201 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1201 = 1;
    OPEN cur_1201;
    rl_1201: LOOP
      FETCH cur_1201 INTO v_pid_1201, v_oh_1201;
      IF v_fin_1201 = 1 THEN LEAVE rl_1201; END IF;
      SET v_av_1201 = erp_fn_available_qty(v_pid_1201, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1201, 1, 'RECON', CAST(v_oh_1201 - v_av_1201 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1201 AS CHAR));
    END LOOP;
    CLOSE cur_1201;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1201,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1201,0) AS CHAR)));
  END;

  -- dynamic-sql block 1202: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1202 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1202 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1202 = CONCAT('SELECT COUNT(*) INTO @dcnt_1202 FROM ', v_tbl_1202,
                          ' WHERE ', v_col_1202, ' = ?');
    SET @dparm_1202 = 'NEW';
    PREPARE pst_1202 FROM @dsql_1202;
    EXECUTE pst_1202 USING @dparm_1202;
    DEALLOCATE PREPARE pst_1202;
    SET @dupd_1202 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1202 = 100;
    PREPARE pud_1202 FROM @dupd_1202;
    EXECUTE pud_1202 USING @doid_1202;
    DEALLOCATE PREPARE pud_1202;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1202,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1202, ' col ', v_col_1202));
  END;

  -- recursive block 1203: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1203 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1203 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1203;
  END;

  -- reprice block 1204: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1204 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1204;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1204, 'UPDATE', CONCAT('rows ', CAST(v_rows_1204 AS CHAR)));
  END;

  -- validation block 1205: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1205 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1205
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1205 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1205, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1205 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1205, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1206: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1206 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1206 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1206 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1206 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1206 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1206 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1206 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1206 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1206 AS CHAR), ' cr ', CAST(v_cr_1206 AS CHAR),
                   ' dr ', CAST(v_dr_1206 AS CHAR), ' tot ', CAST(v_tot_1206 AS CHAR)));
  END;

  -- invoice rollup block 1207: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1207 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1207 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1207
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1207
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1207 AS CHAR), ' paid ', CAST(v_paid_1207 AS CHAR)));
  END;

  -- gl reconciliation block 1208: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1208 INT DEFAULT 0;
    DECLARE v_acct_1208 INT;
    DECLARE v_dr_1208 DECIMAL(18,2);
    DECLARE v_cr_1208 DECIMAL(18,2);
    DECLARE gcur_1208 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1208 = 1;
    OPEN gcur_1208;
    gl_1208: LOOP
      FETCH gcur_1208 INTO v_acct_1208, v_dr_1208, v_cr_1208;
      IF v_gfin_1208 = 1 THEN LEAVE gl_1208; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1208, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1208 - v_cr_1208 AS CHAR)));
    END LOOP;
    CLOSE gcur_1208;
  END;

  -- transaction block 1209: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1209;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1209;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1209, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1210: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1210;
    CREATE TEMPORARY TABLE tmp_agg_1210 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1210 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1210 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1210;
  END;

  -- upsert block 1211: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1211 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1211, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1211, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1211 AS CHAR)));
  END;

  -- json block 1212: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1212 JSON;
    DECLARE v_sku_1212 VARCHAR(40);
    DECLARE v_tag_1212 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1212, v_sku_1212, v_tag_1212
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1212,''), ' tag ', IFNULL(v_tag_1212,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1212, 'tag', v_tag_1212) AS CHAR)));
  END;

  -- cte block 1213: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1213 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1213 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1213 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1213 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1214: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1214 VARCHAR(10);
    DECLARE v_amt_1214 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1214 FROM erp_order;
    SET v_band_1214 = CASE
        WHEN v_amt_1214 >= 10000 THEN 'HIGH'
        WHEN v_amt_1214 >= 1000  THEN 'MED'
        WHEN v_amt_1214 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1214, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1215: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1215 INT DEFAULT 0;
    DECLARE v_j_1215 INT DEFAULT 0;
    DECLARE v_rc_1215 INT DEFAULT 0;
    REPEAT
      SET v_i_1215 = v_i_1215 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1215'), v_i_1215)
        ON DUPLICATE KEY UPDATE tick = v_i_1215;
    UNTIL v_i_1215 >= 3 END REPEAT;
    WHILE v_j_1215 < 3 DO
      SET v_j_1215 = v_j_1215 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1215 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1215 + v_j_1215, 'ITER',
            CONCAT('i ', CAST(v_i_1215 AS CHAR), ' j ', CAST(v_j_1215 AS CHAR),
                   ' diag ', CAST(v_rc_1215 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_18  [procedure]
CREATE PROCEDURE erp_usp_stage_18()
BEGIN
  DECLARE v_amt_s18 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s18 INT DEFAULT 0;
  DECLARE v_fx_s18  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s18 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s18 VARCHAR(60);
  DECLARE v_av_s18  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s18  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 18, 'ERROR', 'stage 18 failed');
  END;
  START TRANSACTION;
  SET v_fx_s18  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s18 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s18 = erp_fn_json_tag(1);
  SET v_av_s18  = erp_fn_available_qty(1, 1);
  SET v_cr_s18  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s18, v_amt_s18 FROM erp_order;
  SET v_amt_s18 = v_amt_s18 + erp_fn_tax_amount(v_amt_s18, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_18', v_cnt_s18)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s18;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s18 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 18, 'CREDIT', 'stage 18 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 18, 'OK', CONCAT('stage 18 tag ', IFNULL(v_tag_s18,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s18, 'RUN_18',
       CONCAT('fx ', CAST(v_fx_s18 AS CHAR), ' mar ', CAST(v_mar_s18 AS CHAR)));
  CALL erp_usp_stage_19();

  -- analytics block 1216: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1216 INT DEFAULT 0;
    DECLARE v_amt_1216 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1216 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1216 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1216, v_amt_1216, v_avg_1216, v_max_1216
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1216 = v_amt_1216 + erp_fn_tax_amount(v_amt_1216, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1216, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1216 AS CHAR), ' avg ', CAST(v_avg_1216 AS CHAR),
                   ' max ', CAST(v_max_1216 AS CHAR)));
  END;

  -- reconcile block 1217: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1217 INT DEFAULT 0;
    DECLARE v_pid_1217 INT;
    DECLARE v_oh_1217 DECIMAL(18,4);
    DECLARE v_av_1217 DECIMAL(18,4);
    DECLARE cur_1217 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1217 = 1;
    OPEN cur_1217;
    rl_1217: LOOP
      FETCH cur_1217 INTO v_pid_1217, v_oh_1217;
      IF v_fin_1217 = 1 THEN LEAVE rl_1217; END IF;
      SET v_av_1217 = erp_fn_available_qty(v_pid_1217, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1217, 1, 'RECON', CAST(v_oh_1217 - v_av_1217 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1217 AS CHAR));
    END LOOP;
    CLOSE cur_1217;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1217,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1217,0) AS CHAR)));
  END;

  -- dynamic-sql block 1218: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1218 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1218 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1218 = CONCAT('SELECT COUNT(*) INTO @dcnt_1218 FROM ', v_tbl_1218,
                          ' WHERE ', v_col_1218, ' = ?');
    SET @dparm_1218 = 'NEW';
    PREPARE pst_1218 FROM @dsql_1218;
    EXECUTE pst_1218 USING @dparm_1218;
    DEALLOCATE PREPARE pst_1218;
    SET @dupd_1218 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1218 = 100;
    PREPARE pud_1218 FROM @dupd_1218;
    EXECUTE pud_1218 USING @doid_1218;
    DEALLOCATE PREPARE pud_1218;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1218,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1218, ' col ', v_col_1218));
  END;

  -- recursive block 1219: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1219 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1219 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1219;
  END;

  -- reprice block 1220: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1220 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1220;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1220, 'UPDATE', CONCAT('rows ', CAST(v_rows_1220 AS CHAR)));
  END;

  -- validation block 1221: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1221 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1221
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1221 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1221, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1221 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1221, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1222: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1222 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1222 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1222 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1222 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1222 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1222 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1222 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1222 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1222 AS CHAR), ' cr ', CAST(v_cr_1222 AS CHAR),
                   ' dr ', CAST(v_dr_1222 AS CHAR), ' tot ', CAST(v_tot_1222 AS CHAR)));
  END;

  -- invoice rollup block 1223: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1223 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1223 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1223
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1223
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1223 AS CHAR), ' paid ', CAST(v_paid_1223 AS CHAR)));
  END;

  -- gl reconciliation block 1224: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1224 INT DEFAULT 0;
    DECLARE v_acct_1224 INT;
    DECLARE v_dr_1224 DECIMAL(18,2);
    DECLARE v_cr_1224 DECIMAL(18,2);
    DECLARE gcur_1224 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1224 = 1;
    OPEN gcur_1224;
    gl_1224: LOOP
      FETCH gcur_1224 INTO v_acct_1224, v_dr_1224, v_cr_1224;
      IF v_gfin_1224 = 1 THEN LEAVE gl_1224; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1224, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1224 - v_cr_1224 AS CHAR)));
    END LOOP;
    CLOSE gcur_1224;
  END;

  -- transaction block 1225: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1225;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1225;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1225, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1226: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1226;
    CREATE TEMPORARY TABLE tmp_agg_1226 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1226 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1226 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1226;
  END;

  -- upsert block 1227: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1227 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1227, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1227, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1227 AS CHAR)));
  END;

  -- json block 1228: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1228 JSON;
    DECLARE v_sku_1228 VARCHAR(40);
    DECLARE v_tag_1228 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1228, v_sku_1228, v_tag_1228
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1228,''), ' tag ', IFNULL(v_tag_1228,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1228, 'tag', v_tag_1228) AS CHAR)));
  END;

  -- cte block 1229: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1229 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1229 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1229 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1229 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1230: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1230 VARCHAR(10);
    DECLARE v_amt_1230 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1230 FROM erp_order;
    SET v_band_1230 = CASE
        WHEN v_amt_1230 >= 10000 THEN 'HIGH'
        WHEN v_amt_1230 >= 1000  THEN 'MED'
        WHEN v_amt_1230 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1230, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_19  [procedure]
CREATE PROCEDURE erp_usp_stage_19()
BEGIN
  DECLARE v_amt_s19 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s19 INT DEFAULT 0;
  DECLARE v_fx_s19  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s19 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s19 VARCHAR(60);
  DECLARE v_av_s19  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s19  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 19, 'ERROR', 'stage 19 failed');
  END;
  START TRANSACTION;
  SET v_fx_s19  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s19 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s19 = erp_fn_json_tag(1);
  SET v_av_s19  = erp_fn_available_qty(1, 1);
  SET v_cr_s19  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s19, v_amt_s19 FROM erp_order;
  SET v_amt_s19 = v_amt_s19 + erp_fn_tax_amount(v_amt_s19, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_19', v_cnt_s19)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s19;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s19 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 19, 'CREDIT', 'stage 19 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 19, 'OK', CONCAT('stage 19 tag ', IFNULL(v_tag_s19,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s19, 'RUN_19',
       CONCAT('fx ', CAST(v_fx_s19 AS CHAR), ' mar ', CAST(v_mar_s19 AS CHAR)));
  CALL erp_usp_stage_20();

  -- repeat/while block 1231: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1231 INT DEFAULT 0;
    DECLARE v_j_1231 INT DEFAULT 0;
    DECLARE v_rc_1231 INT DEFAULT 0;
    REPEAT
      SET v_i_1231 = v_i_1231 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1231'), v_i_1231)
        ON DUPLICATE KEY UPDATE tick = v_i_1231;
    UNTIL v_i_1231 >= 3 END REPEAT;
    WHILE v_j_1231 < 3 DO
      SET v_j_1231 = v_j_1231 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1231 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1231 + v_j_1231, 'ITER',
            CONCAT('i ', CAST(v_i_1231 AS CHAR), ' j ', CAST(v_j_1231 AS CHAR),
                   ' diag ', CAST(v_rc_1231 AS CHAR)));
  END;

  -- analytics block 1232: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1232 INT DEFAULT 0;
    DECLARE v_amt_1232 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1232 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1232 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1232, v_amt_1232, v_avg_1232, v_max_1232
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1232 = v_amt_1232 + erp_fn_tax_amount(v_amt_1232, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1232, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1232 AS CHAR), ' avg ', CAST(v_avg_1232 AS CHAR),
                   ' max ', CAST(v_max_1232 AS CHAR)));
  END;

  -- reconcile block 1233: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1233 INT DEFAULT 0;
    DECLARE v_pid_1233 INT;
    DECLARE v_oh_1233 DECIMAL(18,4);
    DECLARE v_av_1233 DECIMAL(18,4);
    DECLARE cur_1233 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1233 = 1;
    OPEN cur_1233;
    rl_1233: LOOP
      FETCH cur_1233 INTO v_pid_1233, v_oh_1233;
      IF v_fin_1233 = 1 THEN LEAVE rl_1233; END IF;
      SET v_av_1233 = erp_fn_available_qty(v_pid_1233, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1233, 1, 'RECON', CAST(v_oh_1233 - v_av_1233 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1233 AS CHAR));
    END LOOP;
    CLOSE cur_1233;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1233,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1233,0) AS CHAR)));
  END;

  -- dynamic-sql block 1234: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1234 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1234 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1234 = CONCAT('SELECT COUNT(*) INTO @dcnt_1234 FROM ', v_tbl_1234,
                          ' WHERE ', v_col_1234, ' = ?');
    SET @dparm_1234 = 'NEW';
    PREPARE pst_1234 FROM @dsql_1234;
    EXECUTE pst_1234 USING @dparm_1234;
    DEALLOCATE PREPARE pst_1234;
    SET @dupd_1234 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1234 = 100;
    PREPARE pud_1234 FROM @dupd_1234;
    EXECUTE pud_1234 USING @doid_1234;
    DEALLOCATE PREPARE pud_1234;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1234,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1234, ' col ', v_col_1234));
  END;

  -- recursive block 1235: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1235 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1235 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1235;
  END;

  -- reprice block 1236: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1236 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1236;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1236, 'UPDATE', CONCAT('rows ', CAST(v_rows_1236 AS CHAR)));
  END;

  -- validation block 1237: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1237 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1237
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1237 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1237, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1237 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1237, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1238: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1238 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1238 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1238 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1238 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1238 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1238 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1238 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1238 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1238 AS CHAR), ' cr ', CAST(v_cr_1238 AS CHAR),
                   ' dr ', CAST(v_dr_1238 AS CHAR), ' tot ', CAST(v_tot_1238 AS CHAR)));
  END;

  -- invoice rollup block 1239: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1239 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1239 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1239
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1239
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1239 AS CHAR), ' paid ', CAST(v_paid_1239 AS CHAR)));
  END;

  -- gl reconciliation block 1240: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1240 INT DEFAULT 0;
    DECLARE v_acct_1240 INT;
    DECLARE v_dr_1240 DECIMAL(18,2);
    DECLARE v_cr_1240 DECIMAL(18,2);
    DECLARE gcur_1240 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1240 = 1;
    OPEN gcur_1240;
    gl_1240: LOOP
      FETCH gcur_1240 INTO v_acct_1240, v_dr_1240, v_cr_1240;
      IF v_gfin_1240 = 1 THEN LEAVE gl_1240; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1240, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1240 - v_cr_1240 AS CHAR)));
    END LOOP;
    CLOSE gcur_1240;
  END;

  -- transaction block 1241: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1241;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1241;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1241, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1242: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1242;
    CREATE TEMPORARY TABLE tmp_agg_1242 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1242 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1242 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1242;
  END;

  -- upsert block 1243: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1243 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1243, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1243, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1243 AS CHAR)));
  END;

  -- json block 1244: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1244 JSON;
    DECLARE v_sku_1244 VARCHAR(40);
    DECLARE v_tag_1244 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1244, v_sku_1244, v_tag_1244
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1244,''), ' tag ', IFNULL(v_tag_1244,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1244, 'tag', v_tag_1244) AS CHAR)));
  END;

  -- cte block 1245: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1245 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1245 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1245 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1245 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_20  [procedure]
CREATE PROCEDURE erp_usp_stage_20()
BEGIN
  DECLARE v_amt_s20 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s20 INT DEFAULT 0;
  DECLARE v_fx_s20  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s20 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s20 VARCHAR(60);
  DECLARE v_av_s20  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s20  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 20, 'ERROR', 'stage 20 failed');
  END;
  START TRANSACTION;
  SET v_fx_s20  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s20 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s20 = erp_fn_json_tag(1);
  SET v_av_s20  = erp_fn_available_qty(1, 1);
  SET v_cr_s20  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s20, v_amt_s20 FROM erp_order;
  SET v_amt_s20 = v_amt_s20 + erp_fn_tax_amount(v_amt_s20, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_20', v_cnt_s20)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s20;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s20 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 20, 'CREDIT', 'stage 20 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 20, 'OK', CONCAT('stage 20 tag ', IFNULL(v_tag_s20,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s20, 'RUN_20',
       CONCAT('fx ', CAST(v_fx_s20 AS CHAR), ' mar ', CAST(v_mar_s20 AS CHAR)));
  CALL erp_usp_stage_21();

  -- case block 1246: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1246 VARCHAR(10);
    DECLARE v_amt_1246 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1246 FROM erp_order;
    SET v_band_1246 = CASE
        WHEN v_amt_1246 >= 10000 THEN 'HIGH'
        WHEN v_amt_1246 >= 1000  THEN 'MED'
        WHEN v_amt_1246 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1246, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1247: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1247 INT DEFAULT 0;
    DECLARE v_j_1247 INT DEFAULT 0;
    DECLARE v_rc_1247 INT DEFAULT 0;
    REPEAT
      SET v_i_1247 = v_i_1247 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1247'), v_i_1247)
        ON DUPLICATE KEY UPDATE tick = v_i_1247;
    UNTIL v_i_1247 >= 3 END REPEAT;
    WHILE v_j_1247 < 3 DO
      SET v_j_1247 = v_j_1247 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1247 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1247 + v_j_1247, 'ITER',
            CONCAT('i ', CAST(v_i_1247 AS CHAR), ' j ', CAST(v_j_1247 AS CHAR),
                   ' diag ', CAST(v_rc_1247 AS CHAR)));
  END;

  -- analytics block 1248: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1248 INT DEFAULT 0;
    DECLARE v_amt_1248 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1248 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1248 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1248, v_amt_1248, v_avg_1248, v_max_1248
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1248 = v_amt_1248 + erp_fn_tax_amount(v_amt_1248, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1248, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1248 AS CHAR), ' avg ', CAST(v_avg_1248 AS CHAR),
                   ' max ', CAST(v_max_1248 AS CHAR)));
  END;

  -- reconcile block 1249: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1249 INT DEFAULT 0;
    DECLARE v_pid_1249 INT;
    DECLARE v_oh_1249 DECIMAL(18,4);
    DECLARE v_av_1249 DECIMAL(18,4);
    DECLARE cur_1249 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1249 = 1;
    OPEN cur_1249;
    rl_1249: LOOP
      FETCH cur_1249 INTO v_pid_1249, v_oh_1249;
      IF v_fin_1249 = 1 THEN LEAVE rl_1249; END IF;
      SET v_av_1249 = erp_fn_available_qty(v_pid_1249, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1249, 1, 'RECON', CAST(v_oh_1249 - v_av_1249 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1249 AS CHAR));
    END LOOP;
    CLOSE cur_1249;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1249,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1249,0) AS CHAR)));
  END;

  -- dynamic-sql block 1250: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1250 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1250 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1250 = CONCAT('SELECT COUNT(*) INTO @dcnt_1250 FROM ', v_tbl_1250,
                          ' WHERE ', v_col_1250, ' = ?');
    SET @dparm_1250 = 'NEW';
    PREPARE pst_1250 FROM @dsql_1250;
    EXECUTE pst_1250 USING @dparm_1250;
    DEALLOCATE PREPARE pst_1250;
    SET @dupd_1250 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1250 = 100;
    PREPARE pud_1250 FROM @dupd_1250;
    EXECUTE pud_1250 USING @doid_1250;
    DEALLOCATE PREPARE pud_1250;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1250,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1250, ' col ', v_col_1250));
  END;

  -- recursive block 1251: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1251 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1251 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1251;
  END;

  -- reprice block 1252: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1252 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1252;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1252, 'UPDATE', CONCAT('rows ', CAST(v_rows_1252 AS CHAR)));
  END;

  -- validation block 1253: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1253 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1253
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1253 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1253, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1253 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1253, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1254: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1254 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1254 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1254 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1254 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1254 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1254 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1254 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1254 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1254 AS CHAR), ' cr ', CAST(v_cr_1254 AS CHAR),
                   ' dr ', CAST(v_dr_1254 AS CHAR), ' tot ', CAST(v_tot_1254 AS CHAR)));
  END;

  -- invoice rollup block 1255: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1255 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1255 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1255
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1255
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1255 AS CHAR), ' paid ', CAST(v_paid_1255 AS CHAR)));
  END;

  -- gl reconciliation block 1256: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1256 INT DEFAULT 0;
    DECLARE v_acct_1256 INT;
    DECLARE v_dr_1256 DECIMAL(18,2);
    DECLARE v_cr_1256 DECIMAL(18,2);
    DECLARE gcur_1256 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1256 = 1;
    OPEN gcur_1256;
    gl_1256: LOOP
      FETCH gcur_1256 INTO v_acct_1256, v_dr_1256, v_cr_1256;
      IF v_gfin_1256 = 1 THEN LEAVE gl_1256; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1256, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1256 - v_cr_1256 AS CHAR)));
    END LOOP;
    CLOSE gcur_1256;
  END;

  -- transaction block 1257: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1257;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1257;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1257, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1258: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1258;
    CREATE TEMPORARY TABLE tmp_agg_1258 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1258 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1258 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1258;
  END;

  -- upsert block 1259: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1259 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1259, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1259, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1259 AS CHAR)));
  END;

  -- json block 1260: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1260 JSON;
    DECLARE v_sku_1260 VARCHAR(40);
    DECLARE v_tag_1260 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1260, v_sku_1260, v_tag_1260
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1260,''), ' tag ', IFNULL(v_tag_1260,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1260, 'tag', v_tag_1260) AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_21  [procedure]
CREATE PROCEDURE erp_usp_stage_21()
BEGIN
  DECLARE v_amt_s21 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s21 INT DEFAULT 0;
  DECLARE v_fx_s21  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s21 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s21 VARCHAR(60);
  DECLARE v_av_s21  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s21  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 21, 'ERROR', 'stage 21 failed');
  END;
  START TRANSACTION;
  SET v_fx_s21  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s21 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s21 = erp_fn_json_tag(1);
  SET v_av_s21  = erp_fn_available_qty(1, 1);
  SET v_cr_s21  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s21, v_amt_s21 FROM erp_order;
  SET v_amt_s21 = v_amt_s21 + erp_fn_tax_amount(v_amt_s21, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_21', v_cnt_s21)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s21;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s21 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 21, 'CREDIT', 'stage 21 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 21, 'OK', CONCAT('stage 21 tag ', IFNULL(v_tag_s21,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s21, 'RUN_21',
       CONCAT('fx ', CAST(v_fx_s21 AS CHAR), ' mar ', CAST(v_mar_s21 AS CHAR)));
  CALL erp_usp_stage_22();

  -- cte block 1261: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1261 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1261 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1261 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1261 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1262: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1262 VARCHAR(10);
    DECLARE v_amt_1262 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1262 FROM erp_order;
    SET v_band_1262 = CASE
        WHEN v_amt_1262 >= 10000 THEN 'HIGH'
        WHEN v_amt_1262 >= 1000  THEN 'MED'
        WHEN v_amt_1262 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1262, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1263: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1263 INT DEFAULT 0;
    DECLARE v_j_1263 INT DEFAULT 0;
    DECLARE v_rc_1263 INT DEFAULT 0;
    REPEAT
      SET v_i_1263 = v_i_1263 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1263'), v_i_1263)
        ON DUPLICATE KEY UPDATE tick = v_i_1263;
    UNTIL v_i_1263 >= 3 END REPEAT;
    WHILE v_j_1263 < 3 DO
      SET v_j_1263 = v_j_1263 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1263 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1263 + v_j_1263, 'ITER',
            CONCAT('i ', CAST(v_i_1263 AS CHAR), ' j ', CAST(v_j_1263 AS CHAR),
                   ' diag ', CAST(v_rc_1263 AS CHAR)));
  END;

  -- analytics block 1264: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1264 INT DEFAULT 0;
    DECLARE v_amt_1264 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1264 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1264 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1264, v_amt_1264, v_avg_1264, v_max_1264
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1264 = v_amt_1264 + erp_fn_tax_amount(v_amt_1264, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1264, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1264 AS CHAR), ' avg ', CAST(v_avg_1264 AS CHAR),
                   ' max ', CAST(v_max_1264 AS CHAR)));
  END;

  -- reconcile block 1265: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1265 INT DEFAULT 0;
    DECLARE v_pid_1265 INT;
    DECLARE v_oh_1265 DECIMAL(18,4);
    DECLARE v_av_1265 DECIMAL(18,4);
    DECLARE cur_1265 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1265 = 1;
    OPEN cur_1265;
    rl_1265: LOOP
      FETCH cur_1265 INTO v_pid_1265, v_oh_1265;
      IF v_fin_1265 = 1 THEN LEAVE rl_1265; END IF;
      SET v_av_1265 = erp_fn_available_qty(v_pid_1265, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1265, 1, 'RECON', CAST(v_oh_1265 - v_av_1265 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1265 AS CHAR));
    END LOOP;
    CLOSE cur_1265;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1265,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1265,0) AS CHAR)));
  END;

  -- dynamic-sql block 1266: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1266 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1266 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1266 = CONCAT('SELECT COUNT(*) INTO @dcnt_1266 FROM ', v_tbl_1266,
                          ' WHERE ', v_col_1266, ' = ?');
    SET @dparm_1266 = 'NEW';
    PREPARE pst_1266 FROM @dsql_1266;
    EXECUTE pst_1266 USING @dparm_1266;
    DEALLOCATE PREPARE pst_1266;
    SET @dupd_1266 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1266 = 100;
    PREPARE pud_1266 FROM @dupd_1266;
    EXECUTE pud_1266 USING @doid_1266;
    DEALLOCATE PREPARE pud_1266;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1266,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1266, ' col ', v_col_1266));
  END;

  -- recursive block 1267: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1267 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1267 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1267;
  END;

  -- reprice block 1268: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1268 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1268;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1268, 'UPDATE', CONCAT('rows ', CAST(v_rows_1268 AS CHAR)));
  END;

  -- validation block 1269: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1269 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1269
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1269 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1269, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1269 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1269, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1270: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1270 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1270 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1270 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1270 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1270 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1270 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1270 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1270 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1270 AS CHAR), ' cr ', CAST(v_cr_1270 AS CHAR),
                   ' dr ', CAST(v_dr_1270 AS CHAR), ' tot ', CAST(v_tot_1270 AS CHAR)));
  END;

  -- invoice rollup block 1271: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1271 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1271 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1271
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1271
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1271 AS CHAR), ' paid ', CAST(v_paid_1271 AS CHAR)));
  END;

  -- gl reconciliation block 1272: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1272 INT DEFAULT 0;
    DECLARE v_acct_1272 INT;
    DECLARE v_dr_1272 DECIMAL(18,2);
    DECLARE v_cr_1272 DECIMAL(18,2);
    DECLARE gcur_1272 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1272 = 1;
    OPEN gcur_1272;
    gl_1272: LOOP
      FETCH gcur_1272 INTO v_acct_1272, v_dr_1272, v_cr_1272;
      IF v_gfin_1272 = 1 THEN LEAVE gl_1272; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1272, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1272 - v_cr_1272 AS CHAR)));
    END LOOP;
    CLOSE gcur_1272;
  END;

  -- transaction block 1273: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1273;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1273;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1273, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1274: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1274;
    CREATE TEMPORARY TABLE tmp_agg_1274 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1274 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1274 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1274;
  END;

  -- upsert block 1275: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1275 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1275, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1275, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1275 AS CHAR)));
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_22  [procedure]
CREATE PROCEDURE erp_usp_stage_22()
BEGIN
  DECLARE v_amt_s22 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s22 INT DEFAULT 0;
  DECLARE v_fx_s22  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s22 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s22 VARCHAR(60);
  DECLARE v_av_s22  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s22  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 22, 'ERROR', 'stage 22 failed');
  END;
  START TRANSACTION;
  SET v_fx_s22  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s22 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s22 = erp_fn_json_tag(1);
  SET v_av_s22  = erp_fn_available_qty(1, 1);
  SET v_cr_s22  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s22, v_amt_s22 FROM erp_order;
  SET v_amt_s22 = v_amt_s22 + erp_fn_tax_amount(v_amt_s22, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_22', v_cnt_s22)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s22;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s22 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 22, 'CREDIT', 'stage 22 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 22, 'OK', CONCAT('stage 22 tag ', IFNULL(v_tag_s22,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s22, 'RUN_22',
       CONCAT('fx ', CAST(v_fx_s22 AS CHAR), ' mar ', CAST(v_mar_s22 AS CHAR)));
  CALL erp_usp_stage_23();

  -- json block 1276: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1276 JSON;
    DECLARE v_sku_1276 VARCHAR(40);
    DECLARE v_tag_1276 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1276, v_sku_1276, v_tag_1276
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1276,''), ' tag ', IFNULL(v_tag_1276,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1276, 'tag', v_tag_1276) AS CHAR)));
  END;

  -- cte block 1277: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1277 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1277 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1277 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1277 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1278: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1278 VARCHAR(10);
    DECLARE v_amt_1278 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1278 FROM erp_order;
    SET v_band_1278 = CASE
        WHEN v_amt_1278 >= 10000 THEN 'HIGH'
        WHEN v_amt_1278 >= 1000  THEN 'MED'
        WHEN v_amt_1278 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1278, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1279: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1279 INT DEFAULT 0;
    DECLARE v_j_1279 INT DEFAULT 0;
    DECLARE v_rc_1279 INT DEFAULT 0;
    REPEAT
      SET v_i_1279 = v_i_1279 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1279'), v_i_1279)
        ON DUPLICATE KEY UPDATE tick = v_i_1279;
    UNTIL v_i_1279 >= 3 END REPEAT;
    WHILE v_j_1279 < 3 DO
      SET v_j_1279 = v_j_1279 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1279 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1279 + v_j_1279, 'ITER',
            CONCAT('i ', CAST(v_i_1279 AS CHAR), ' j ', CAST(v_j_1279 AS CHAR),
                   ' diag ', CAST(v_rc_1279 AS CHAR)));
  END;

  -- analytics block 1280: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1280 INT DEFAULT 0;
    DECLARE v_amt_1280 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1280 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1280 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1280, v_amt_1280, v_avg_1280, v_max_1280
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1280 = v_amt_1280 + erp_fn_tax_amount(v_amt_1280, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1280, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1280 AS CHAR), ' avg ', CAST(v_avg_1280 AS CHAR),
                   ' max ', CAST(v_max_1280 AS CHAR)));
  END;

  -- reconcile block 1281: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1281 INT DEFAULT 0;
    DECLARE v_pid_1281 INT;
    DECLARE v_oh_1281 DECIMAL(18,4);
    DECLARE v_av_1281 DECIMAL(18,4);
    DECLARE cur_1281 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1281 = 1;
    OPEN cur_1281;
    rl_1281: LOOP
      FETCH cur_1281 INTO v_pid_1281, v_oh_1281;
      IF v_fin_1281 = 1 THEN LEAVE rl_1281; END IF;
      SET v_av_1281 = erp_fn_available_qty(v_pid_1281, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1281, 1, 'RECON', CAST(v_oh_1281 - v_av_1281 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1281 AS CHAR));
    END LOOP;
    CLOSE cur_1281;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1281,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1281,0) AS CHAR)));
  END;

  -- dynamic-sql block 1282: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1282 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1282 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1282 = CONCAT('SELECT COUNT(*) INTO @dcnt_1282 FROM ', v_tbl_1282,
                          ' WHERE ', v_col_1282, ' = ?');
    SET @dparm_1282 = 'NEW';
    PREPARE pst_1282 FROM @dsql_1282;
    EXECUTE pst_1282 USING @dparm_1282;
    DEALLOCATE PREPARE pst_1282;
    SET @dupd_1282 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1282 = 100;
    PREPARE pud_1282 FROM @dupd_1282;
    EXECUTE pud_1282 USING @doid_1282;
    DEALLOCATE PREPARE pud_1282;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1282,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1282, ' col ', v_col_1282));
  END;

  -- recursive block 1283: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1283 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1283 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1283;
  END;

  -- reprice block 1284: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1284 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1284;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1284, 'UPDATE', CONCAT('rows ', CAST(v_rows_1284 AS CHAR)));
  END;

  -- validation block 1285: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1285 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1285
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1285 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1285, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1285 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1285, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1286: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1286 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1286 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1286 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1286 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1286 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1286 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1286 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1286 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1286 AS CHAR), ' cr ', CAST(v_cr_1286 AS CHAR),
                   ' dr ', CAST(v_dr_1286 AS CHAR), ' tot ', CAST(v_tot_1286 AS CHAR)));
  END;

  -- invoice rollup block 1287: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1287 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1287 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1287
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1287
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1287 AS CHAR), ' paid ', CAST(v_paid_1287 AS CHAR)));
  END;

  -- gl reconciliation block 1288: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1288 INT DEFAULT 0;
    DECLARE v_acct_1288 INT;
    DECLARE v_dr_1288 DECIMAL(18,2);
    DECLARE v_cr_1288 DECIMAL(18,2);
    DECLARE gcur_1288 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1288 = 1;
    OPEN gcur_1288;
    gl_1288: LOOP
      FETCH gcur_1288 INTO v_acct_1288, v_dr_1288, v_cr_1288;
      IF v_gfin_1288 = 1 THEN LEAVE gl_1288; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1288, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1288 - v_cr_1288 AS CHAR)));
    END LOOP;
    CLOSE gcur_1288;
  END;

  -- transaction block 1289: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1289;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1289;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1289, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1290: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1290;
    CREATE TEMPORARY TABLE tmp_agg_1290 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1290 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1290 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1290;
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_23  [procedure]
CREATE PROCEDURE erp_usp_stage_23()
BEGIN
  DECLARE v_amt_s23 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s23 INT DEFAULT 0;
  DECLARE v_fx_s23  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s23 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s23 VARCHAR(60);
  DECLARE v_av_s23  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s23  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 23, 'ERROR', 'stage 23 failed');
  END;
  START TRANSACTION;
  SET v_fx_s23  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s23 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s23 = erp_fn_json_tag(1);
  SET v_av_s23  = erp_fn_available_qty(1, 1);
  SET v_cr_s23  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s23, v_amt_s23 FROM erp_order;
  SET v_amt_s23 = v_amt_s23 + erp_fn_tax_amount(v_amt_s23, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_23', v_cnt_s23)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s23;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s23 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 23, 'CREDIT', 'stage 23 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 23, 'OK', CONCAT('stage 23 tag ', IFNULL(v_tag_s23,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s23, 'RUN_23',
       CONCAT('fx ', CAST(v_fx_s23 AS CHAR), ' mar ', CAST(v_mar_s23 AS CHAR)));
  CALL erp_usp_stage_24();

  -- upsert block 1291: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1291 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1291, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1291, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1291 AS CHAR)));
  END;

  -- json block 1292: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1292 JSON;
    DECLARE v_sku_1292 VARCHAR(40);
    DECLARE v_tag_1292 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1292, v_sku_1292, v_tag_1292
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1292,''), ' tag ', IFNULL(v_tag_1292,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1292, 'tag', v_tag_1292) AS CHAR)));
  END;

  -- cte block 1293: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1293 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1293 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1293 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1293 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1294: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1294 VARCHAR(10);
    DECLARE v_amt_1294 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1294 FROM erp_order;
    SET v_band_1294 = CASE
        WHEN v_amt_1294 >= 10000 THEN 'HIGH'
        WHEN v_amt_1294 >= 1000  THEN 'MED'
        WHEN v_amt_1294 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1294, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1295: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1295 INT DEFAULT 0;
    DECLARE v_j_1295 INT DEFAULT 0;
    DECLARE v_rc_1295 INT DEFAULT 0;
    REPEAT
      SET v_i_1295 = v_i_1295 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1295'), v_i_1295)
        ON DUPLICATE KEY UPDATE tick = v_i_1295;
    UNTIL v_i_1295 >= 3 END REPEAT;
    WHILE v_j_1295 < 3 DO
      SET v_j_1295 = v_j_1295 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1295 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1295 + v_j_1295, 'ITER',
            CONCAT('i ', CAST(v_i_1295 AS CHAR), ' j ', CAST(v_j_1295 AS CHAR),
                   ' diag ', CAST(v_rc_1295 AS CHAR)));
  END;

  -- analytics block 1296: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1296 INT DEFAULT 0;
    DECLARE v_amt_1296 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1296 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1296 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1296, v_amt_1296, v_avg_1296, v_max_1296
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1296 = v_amt_1296 + erp_fn_tax_amount(v_amt_1296, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1296, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1296 AS CHAR), ' avg ', CAST(v_avg_1296 AS CHAR),
                   ' max ', CAST(v_max_1296 AS CHAR)));
  END;

  -- reconcile block 1297: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1297 INT DEFAULT 0;
    DECLARE v_pid_1297 INT;
    DECLARE v_oh_1297 DECIMAL(18,4);
    DECLARE v_av_1297 DECIMAL(18,4);
    DECLARE cur_1297 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1297 = 1;
    OPEN cur_1297;
    rl_1297: LOOP
      FETCH cur_1297 INTO v_pid_1297, v_oh_1297;
      IF v_fin_1297 = 1 THEN LEAVE rl_1297; END IF;
      SET v_av_1297 = erp_fn_available_qty(v_pid_1297, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1297, 1, 'RECON', CAST(v_oh_1297 - v_av_1297 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1297 AS CHAR));
    END LOOP;
    CLOSE cur_1297;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1297,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1297,0) AS CHAR)));
  END;

  -- dynamic-sql block 1298: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1298 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1298 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1298 = CONCAT('SELECT COUNT(*) INTO @dcnt_1298 FROM ', v_tbl_1298,
                          ' WHERE ', v_col_1298, ' = ?');
    SET @dparm_1298 = 'NEW';
    PREPARE pst_1298 FROM @dsql_1298;
    EXECUTE pst_1298 USING @dparm_1298;
    DEALLOCATE PREPARE pst_1298;
    SET @dupd_1298 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1298 = 100;
    PREPARE pud_1298 FROM @dupd_1298;
    EXECUTE pud_1298 USING @doid_1298;
    DEALLOCATE PREPARE pud_1298;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1298,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1298, ' col ', v_col_1298));
  END;

  -- recursive block 1299: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1299 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1299 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1299;
  END;

  -- reprice block 1300: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1300 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1300;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1300, 'UPDATE', CONCAT('rows ', CAST(v_rows_1300 AS CHAR)));
  END;

  -- validation block 1301: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1301 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1301
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1301 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1301, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1301 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1301, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1302: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1302 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1302 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1302 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1302 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1302 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1302 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1302 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1302 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1302 AS CHAR), ' cr ', CAST(v_cr_1302 AS CHAR),
                   ' dr ', CAST(v_dr_1302 AS CHAR), ' tot ', CAST(v_tot_1302 AS CHAR)));
  END;

  -- invoice rollup block 1303: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1303 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1303 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1303
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1303
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1303 AS CHAR), ' paid ', CAST(v_paid_1303 AS CHAR)));
  END;

  -- gl reconciliation block 1304: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1304 INT DEFAULT 0;
    DECLARE v_acct_1304 INT;
    DECLARE v_dr_1304 DECIMAL(18,2);
    DECLARE v_cr_1304 DECIMAL(18,2);
    DECLARE gcur_1304 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1304 = 1;
    OPEN gcur_1304;
    gl_1304: LOOP
      FETCH gcur_1304 INTO v_acct_1304, v_dr_1304, v_cr_1304;
      IF v_gfin_1304 = 1 THEN LEAVE gl_1304; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1304, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1304 - v_cr_1304 AS CHAR)));
    END LOOP;
    CLOSE gcur_1304;
  END;

  -- transaction block 1305: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1305;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1305;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1305, 'COMMIT', 'savepoint block committed');
  END;
END$$

-- ---------------------------------------------------------------- erp_usp_stage_24  [procedure]
CREATE PROCEDURE erp_usp_stage_24()
BEGIN
  DECLARE v_amt_s24 DECIMAL(18,2) DEFAULT 0;
  DECLARE v_cnt_s24 INT DEFAULT 0;
  DECLARE v_fx_s24  DECIMAL(18,8) DEFAULT 1;
  DECLARE v_mar_s24 DECIMAL(18,4) DEFAULT 0;
  DECLARE v_tag_s24 VARCHAR(60);
  DECLARE v_av_s24  DECIMAL(18,4) DEFAULT 0;
  DECLARE v_cr_s24  DECIMAL(18,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    CALL erp_usp_audit_log('STAGE', 24, 'ERROR', 'stage 24 failed');
  END;
  START TRANSACTION;
  SET v_fx_s24  = erp_fn_fx_rate('EUR','USD');
  SET v_mar_s24 = erp_fn_margin(18.00, 10.00);
  SET v_tag_s24 = erp_fn_json_tag(1);
  SET v_av_s24  = erp_fn_available_qty(1, 1);
  SET v_cr_s24  = erp_fn_customer_credit(1);
  SELECT COUNT(*), IFNULL(SUM(total_amount),0) INTO v_cnt_s24, v_amt_s24 FROM erp_order;
  SET v_amt_s24 = v_amt_s24 + erp_fn_tax_amount(v_amt_s24, 'US');
  INSERT INTO erp_stats (stat_key, stat_value) VALUES ('stage_24', v_cnt_s24)
    ON DUPLICATE KEY UPDATE stat_value = v_cnt_s24;
  UPDATE erp_order_line SET line_amount = erp_fn_line_amount(qty, unit_price)
   WHERE line_amount = 0;
  IF v_cr_s24 < 0 THEN
    CALL erp_usp_audit_log('STAGE', 24, 'CREDIT', 'stage 24 over credit');
  ELSE
    CALL erp_usp_audit_log('STAGE', 24, 'OK', CONCAT('stage 24 tag ', IFNULL(v_tag_s24,'')));
  END IF;
  COMMIT;
  CALL erp_usp_audit_log('STAGE', v_cnt_s24, 'RUN_24',
       CONCAT('fx ', CAST(v_fx_s24 AS CHAR), ' mar ', CAST(v_mar_s24 AS CHAR)));

  -- temp-table block 1306: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1306;
    CREATE TEMPORARY TABLE tmp_agg_1306 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1306 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1306 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1306;
  END;

  -- upsert block 1307: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1307 INT DEFAULT 3;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1307, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1307, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1307 AS CHAR)));
  END;

  -- json block 1308: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1308 JSON;
    DECLARE v_sku_1308 VARCHAR(40);
    DECLARE v_tag_1308 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1308, v_sku_1308, v_tag_1308
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1308,''), ' tag ', IFNULL(v_tag_1308,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1308, 'tag', v_tag_1308) AS CHAR)));
  END;

  -- cte block 1309: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1309 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1309 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1309 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1309 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1310: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1310 VARCHAR(10);
    DECLARE v_amt_1310 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1310 FROM erp_order;
    SET v_band_1310 = CASE
        WHEN v_amt_1310 >= 10000 THEN 'HIGH'
        WHEN v_amt_1310 >= 1000  THEN 'MED'
        WHEN v_amt_1310 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1310, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1311: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1311 INT DEFAULT 0;
    DECLARE v_j_1311 INT DEFAULT 0;
    DECLARE v_rc_1311 INT DEFAULT 0;
    REPEAT
      SET v_i_1311 = v_i_1311 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1311'), v_i_1311)
        ON DUPLICATE KEY UPDATE tick = v_i_1311;
    UNTIL v_i_1311 >= 3 END REPEAT;
    WHILE v_j_1311 < 3 DO
      SET v_j_1311 = v_j_1311 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1311 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1311 + v_j_1311, 'ITER',
            CONCAT('i ', CAST(v_i_1311 AS CHAR), ' j ', CAST(v_j_1311 AS CHAR),
                   ' diag ', CAST(v_rc_1311 AS CHAR)));
  END;

  -- analytics block 1312: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1312 INT DEFAULT 0;
    DECLARE v_amt_1312 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1312 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1312 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1312, v_amt_1312, v_avg_1312, v_max_1312
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1312 = v_amt_1312 + erp_fn_tax_amount(v_amt_1312, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1312, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1312 AS CHAR), ' avg ', CAST(v_avg_1312 AS CHAR),
                   ' max ', CAST(v_max_1312 AS CHAR)));
  END;

  -- reconcile block 1313: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1313 INT DEFAULT 0;
    DECLARE v_pid_1313 INT;
    DECLARE v_oh_1313 DECIMAL(18,4);
    DECLARE v_av_1313 DECIMAL(18,4);
    DECLARE cur_1313 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1313 = 1;
    OPEN cur_1313;
    rl_1313: LOOP
      FETCH cur_1313 INTO v_pid_1313, v_oh_1313;
      IF v_fin_1313 = 1 THEN LEAVE rl_1313; END IF;
      SET v_av_1313 = erp_fn_available_qty(v_pid_1313, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1313, 1, 'RECON', CAST(v_oh_1313 - v_av_1313 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1313 AS CHAR));
    END LOOP;
    CLOSE cur_1313;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1313,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1313,0) AS CHAR)));
  END;

  -- dynamic-sql block 1314: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1314 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1314 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1314 = CONCAT('SELECT COUNT(*) INTO @dcnt_1314 FROM ', v_tbl_1314,
                          ' WHERE ', v_col_1314, ' = ?');
    SET @dparm_1314 = 'NEW';
    PREPARE pst_1314 FROM @dsql_1314;
    EXECUTE pst_1314 USING @dparm_1314;
    DEALLOCATE PREPARE pst_1314;
    SET @dupd_1314 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1314 = 100;
    PREPARE pud_1314 FROM @dupd_1314;
    EXECUTE pud_1314 USING @doid_1314;
    DEALLOCATE PREPARE pud_1314;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1314,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1314, ' col ', v_col_1314));
  END;

  -- recursive block 1315: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1315 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1315 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1315;
  END;

  -- reprice block 1316: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1316 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1316;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1316, 'UPDATE', CONCAT('rows ', CAST(v_rows_1316 AS CHAR)));
  END;

  -- validation block 1317: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1317 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1317
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1317 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1317, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1317 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1317, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1318: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1318 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1318 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1318 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1318 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1318 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1318 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1318 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1318 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1318 AS CHAR), ' cr ', CAST(v_cr_1318 AS CHAR),
                   ' dr ', CAST(v_dr_1318 AS CHAR), ' tot ', CAST(v_tot_1318 AS CHAR)));
  END;

  -- invoice rollup block 1319: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1319 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1319 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1319
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1319
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1319 AS CHAR), ' paid ', CAST(v_paid_1319 AS CHAR)));
  END;

  -- gl reconciliation block 1320: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1320 INT DEFAULT 0;
    DECLARE v_acct_1320 INT;
    DECLARE v_dr_1320 DECIMAL(18,2);
    DECLARE v_cr_1320 DECIMAL(18,2);
    DECLARE gcur_1320 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1320 = 1;
    OPEN gcur_1320;
    gl_1320: LOOP
      FETCH gcur_1320 INTO v_acct_1320, v_dr_1320, v_cr_1320;
      IF v_gfin_1320 = 1 THEN LEAVE gl_1320; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1320, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1320 - v_cr_1320 AS CHAR)));
    END LOOP;
    CLOSE gcur_1320;
  END;
END$$

-- ============================================================================
-- CROSS-SCHEMA (cross-database) test case
-- In MySQL a "schema" == a database, so cross-schema == cross-database refs.
-- A second database `analyzer_ref` holds a table/view/function/procedure/trigger.
-- The reachable proc analyzerdb.erp_usp_xschema_touch references them qualified
-- (analyzer_ref.*): cross-DB CALL, cross-DB reads, and a cross-DB INSERT that
-- fires the cross-DB AFTER INSERT trigger.
-- Idempotent: DROP DATABASE IF EXISTS analyzer_ref then recreate.
-- ============================================================================
DROP DATABASE IF EXISTS analyzer_ref$$
CREATE DATABASE IF NOT EXISTS analyzer_ref$$

CREATE TABLE analyzer_ref.ref_region (
  region_id   INT PRIMARY KEY,
  region_name VARCHAR(60) NOT NULL,
  active      TINYINT NOT NULL DEFAULT 1
)$$

CREATE TABLE analyzer_ref.ref_audit (
  audit_id   INT AUTO_INCREMENT PRIMARY KEY,
  entity     VARCHAR(40),
  entity_id  INT,
  action     VARCHAR(20),
  detail     VARCHAR(255),
  logged_ts  DATETIME DEFAULT CURRENT_TIMESTAMP
)$$

INSERT INTO analyzer_ref.ref_region (region_id, region_name, active) VALUES
  (1, 'NORTH', 1),
  (2, 'SOUTH', 1),
  (3, 'EAST',  1),
  (4, 'WEST',  0)$$

CREATE VIEW analyzer_ref.vw_region AS
  SELECT region_id, region_name, active
    FROM analyzer_ref.ref_region
   WHERE active = 1$$

CREATE FUNCTION analyzer_ref.fn_region_name(p_region_id INT) RETURNS VARCHAR(60)
READS SQL DATA DETERMINISTIC
BEGIN
  DECLARE v_name VARCHAR(60) DEFAULT NULL;
  SELECT region_name INTO v_name
    FROM analyzer_ref.ref_region
   WHERE region_id = p_region_id
   LIMIT 1;
  RETURN IFNULL(v_name, 'UNKNOWN');
END$$

CREATE PROCEDURE analyzer_ref.usp_ref_log(
  IN p_entity    VARCHAR(40),
  IN p_entity_id INT,
  IN p_action    VARCHAR(20),
  IN p_detail    VARCHAR(255))
BEGIN
  INSERT INTO analyzer_ref.ref_audit (entity, entity_id, action, detail)
  VALUES (p_entity, p_entity_id, p_action, p_detail);
END$$

CREATE TRIGGER analyzer_ref.trg_ref_region
AFTER INSERT ON analyzer_ref.ref_region
FOR EACH ROW
BEGIN
  INSERT INTO analyzer_ref.ref_audit (entity, entity_id, action, detail)
  VALUES ('REF_REGION', NEW.region_id, 'INSERT',
          CONCAT('region ', NEW.region_name));
END$$

-- Reachable proc created in analyzerdb; touches analyzer_ref objects cross-DB.
DROP PROCEDURE IF EXISTS analyzerdb.erp_usp_xschema_touch$$
CREATE PROCEDURE analyzerdb.erp_usp_xschema_touch()
BEGIN
  DECLARE v_cnt  INT DEFAULT 0;
  DECLARE v_vcnt INT DEFAULT 0;
  DECLARE v_name VARCHAR(60);

  -- (a) cross-DB CALL
  CALL analyzer_ref.usp_ref_log('XSCHEMA', 0, 'START', 'begin cross-schema touch');

  -- (b) cross-DB reads: base table, view, and function
  SELECT COUNT(*) INTO v_cnt  FROM analyzer_ref.ref_region;
  SELECT COUNT(*) INTO v_vcnt FROM analyzer_ref.vw_region;
  SET v_name = analyzer_ref.fn_region_name(1);
  CALL analyzer_ref.usp_ref_log('XSCHEMA', v_cnt, 'READ',
       CONCAT('regions ', CAST(v_cnt AS CHAR), ' active ', CAST(v_vcnt AS CHAR),
              ' first ', v_name));

  -- (c) cross-DB INSERT fires analyzer_ref.trg_ref_region
  INSERT INTO analyzer_ref.ref_region (region_id, region_name, active)
  VALUES (100, 'CENTRAL', 1)
  ON DUPLICATE KEY UPDATE region_name = VALUES(region_name);

  CALL analyzer_ref.usp_ref_log('XSCHEMA', 100, 'END', 'cross-schema touch done');
END$$

USE analyzerdb$$

-- ---------------------------------------------------------------- ERP_USP_RUN_CYCLE  [ENTRY PROCEDURE]
CREATE PROCEDURE erp_usp_touch_views()
BEGIN
  DECLARE v_n INT DEFAULT 0;
  SELECT COUNT(*) INTO v_n FROM erp_v_order_summary;
  CALL erp_usp_audit_log('TOUCH_VIEW', v_n, 'READ', 'erp_v_order_summary');
  SELECT COUNT(*) INTO v_n FROM erp_v_stock_status;
  CALL erp_usp_audit_log('TOUCH_VIEW', v_n, 'READ', 'erp_v_stock_status');
  SELECT COUNT(*) INTO v_n FROM erp_v_ar_aging;
  CALL erp_usp_audit_log('TOUCH_VIEW', v_n, 'READ', 'erp_v_ar_aging');
  SELECT COUNT(*) INTO v_n FROM erp_mv_customer_sales;
  CALL erp_usp_audit_log('TOUCH_VIEW', v_n, 'READ', 'erp_mv_customer_sales');
END$$

CREATE PROCEDURE ERP_USP_RUN_CYCLE()
BEGIN
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    CALL erp_usp_audit_log('CYCLE', 0, 'ERROR', 'run_cycle aborted');
    RESIGNAL;
  END;

  CALL erp_usp_audit_log('CYCLE', 0, 'START', 'begin order-to-cash cycle');
  CALL erp_usp_stage_01();
  CALL erp_usp_process_all_orders();
  CALL erp_usp_generate_invoice(100);
  CALL erp_usp_dynamic_report('erp_order', 'INVOICED', v_rows);
  CALL erp_usp_rebuild_stats();
  CALL erp_usp_refresh_mv();
  CALL erp_usp_touch_views();
  CALL erp_usp_xschema_touch();
  CALL erp_usp_close_period('2026-01');
  CALL erp_usp_edge_ops();
  CALL erp_usp_ping(6);
  CALL erp_usp_audit_log('CYCLE', v_rows, 'END', CONCAT('invoiced orders ', CAST(v_rows AS CHAR)));

  -- transaction block 1321: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1321;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1321;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1321, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1322: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1322;
    CREATE TEMPORARY TABLE tmp_agg_1322 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1322 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1322 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1322;
  END;

  -- upsert block 1323: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1323 INT DEFAULT 1;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1323, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1323, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1323 AS CHAR)));
  END;

  -- json block 1324: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1324 JSON;
    DECLARE v_sku_1324 VARCHAR(40);
    DECLARE v_tag_1324 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1324, v_sku_1324, v_tag_1324
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1324,''), ' tag ', IFNULL(v_tag_1324,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1324, 'tag', v_tag_1324) AS CHAR)));
  END;

  -- cte block 1325: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1325 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1325 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1325 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1325 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1326: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1326 VARCHAR(10);
    DECLARE v_amt_1326 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1326 FROM erp_order;
    SET v_band_1326 = CASE
        WHEN v_amt_1326 >= 10000 THEN 'HIGH'
        WHEN v_amt_1326 >= 1000  THEN 'MED'
        WHEN v_amt_1326 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1326, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1327: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1327 INT DEFAULT 0;
    DECLARE v_j_1327 INT DEFAULT 0;
    DECLARE v_rc_1327 INT DEFAULT 0;
    REPEAT
      SET v_i_1327 = v_i_1327 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1327'), v_i_1327)
        ON DUPLICATE KEY UPDATE tick = v_i_1327;
    UNTIL v_i_1327 >= 3 END REPEAT;
    WHILE v_j_1327 < 3 DO
      SET v_j_1327 = v_j_1327 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1327 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1327 + v_j_1327, 'ITER',
            CONCAT('i ', CAST(v_i_1327 AS CHAR), ' j ', CAST(v_j_1327 AS CHAR),
                   ' diag ', CAST(v_rc_1327 AS CHAR)));
  END;

  -- analytics block 1328: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1328 INT DEFAULT 0;
    DECLARE v_amt_1328 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1328 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1328 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1328, v_amt_1328, v_avg_1328, v_max_1328
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1328 = v_amt_1328 + erp_fn_tax_amount(v_amt_1328, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1328, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1328 AS CHAR), ' avg ', CAST(v_avg_1328 AS CHAR),
                   ' max ', CAST(v_max_1328 AS CHAR)));
  END;

  -- reconcile block 1329: stock reconciliation cursor (4-table join, NOT FOUND handler)
  BEGIN
    DECLARE v_fin_1329 INT DEFAULT 0;
    DECLARE v_pid_1329 INT;
    DECLARE v_oh_1329 DECIMAL(18,4);
    DECLARE v_av_1329 DECIMAL(18,4);
    DECLARE cur_1329 CURSOR FOR
      SELECT sl.product_id, sl.qty_on_hand
        FROM erp_stock_level sl
        JOIN erp_product p    ON p.product_id = sl.product_id
        JOIN erp_warehouse w  ON w.warehouse_id = sl.warehouse_id
        LEFT JOIN erp_bin b   ON b.bin_id = sl.bin_id
       WHERE p.active = 1
       ORDER BY sl.product_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_fin_1329 = 1;
    OPEN cur_1329;
    rl_1329: LOOP
      FETCH cur_1329 INTO v_pid_1329, v_oh_1329;
      IF v_fin_1329 = 1 THEN LEAVE rl_1329; END IF;
      SET v_av_1329 = erp_fn_available_qty(v_pid_1329, 1);
      INSERT INTO erp_stock_move (product_id, warehouse_id, move_type, qty, ref_doc)
      SELECT v_pid_1329, 1, 'RECON', CAST(v_oh_1329 - v_av_1329 AS DECIMAL(18,4)),
             CONCAT('RC-', CAST(v_pid_1329 AS CHAR));
    END LOOP;
    CLOSE cur_1329;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('RECON', IFNULL(v_pid_1329,0), 'DONE', CONCAT('scanned ', CAST(IFNULL(v_pid_1329,0) AS CHAR)));
  END;

  -- dynamic-sql block 1330: PREPARE / EXECUTE / DEALLOCATE with session vars
  BEGIN
    DECLARE v_tbl_1330 VARCHAR(64) DEFAULT 'erp_order';
    DECLARE v_col_1330 VARCHAR(64) DEFAULT 'status';
    SET @dsql_1330 = CONCAT('SELECT COUNT(*) INTO @dcnt_1330 FROM ', v_tbl_1330,
                          ' WHERE ', v_col_1330, ' = ?');
    SET @dparm_1330 = 'NEW';
    PREPARE pst_1330 FROM @dsql_1330;
    EXECUTE pst_1330 USING @dparm_1330;
    DEALLOCATE PREPARE pst_1330;
    SET @dupd_1330 = 'UPDATE erp_order SET total_amount = total_amount WHERE order_id = ?';
    SET @doid_1330 = 100;
    PREPARE pud_1330 FROM @dupd_1330;
    EXECUTE pud_1330 USING @doid_1330;
    DEALLOCATE PREPARE pud_1330;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('DYNSQL', IFNULL(@dcnt_1330,0), 'COUNT',
            CONCAT('tbl ', v_tbl_1330, ' col ', v_col_1330));
  END;

  -- recursive block 1331: org-chart level expansion (WITH RECURSIVE, depth-guarded)
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH RECURSIVE emp_1331 AS (
      SELECT employee_id, manager_id, 1 AS lvl, full_name
        FROM erp_employee WHERE manager_id IS NULL
      UNION ALL
      SELECT e.employee_id, e.manager_id, ek.lvl + 1, e.full_name
        FROM erp_employee e
        JOIN emp_1331 ek ON e.manager_id = ek.employee_id
       WHERE ek.lvl < 20
    )
    SELECT 'ORGCHART', employee_id, 'LEVEL',
           CONCAT(full_name, ' L', CAST(lvl AS CHAR))
      FROM emp_1331;
  END;

  -- reprice block 1332: recompute line amounts (UPDATE via IN-subquery, ROW_COUNT)
  BEGIN
    DECLARE v_rows_1332 INT DEFAULT 0;
    UPDATE erp_order_line
       SET line_amount = erp_fn_line_amount(qty, unit_price)
     WHERE order_id IN (
             SELECT o.order_id
               FROM erp_order o
               JOIN erp_customer c ON c.customer_id = o.customer_id
               JOIN erp_order_line ol2 ON ol2.order_id = o.order_id
               JOIN erp_product p ON p.product_id = ol2.product_id
              WHERE o.status IN ('NEW','PROCESSING') AND c.active = 1 AND p.active = 1);
    SELECT ROW_COUNT() INTO v_rows_1332;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('REPRICE', v_rows_1332, 'UPDATE', CONCAT('rows ', CAST(v_rows_1332 AS CHAR)));
  END;

  -- validation block 1333: guarded integrity check (IF/ELSEIF/ELSE + handler)
  BEGIN
    DECLARE v_bad_1333 INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'ERROR', 'integrity check failed');
    SELECT COUNT(*) INTO v_bad_1333
      FROM erp_invoice i
      JOIN erp_order o    ON o.order_id = i.order_id
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.gross_amount < 0 OR i.net_amount < 0;
    IF v_bad_1333 > 5 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1333, 'CRIT', 'many negative invoices');
    ELSEIF v_bad_1333 > 0 THEN
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', v_bad_1333, 'WARN', 'negative amount invoices detected');
    ELSE
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('VALIDATE', 0, 'OK', 'invoice integrity verified');
    END IF;
  END;

  -- fx/credit block 1334: currency + credit valuation (function-heavy, COALESCE)
  BEGIN
    DECLARE v_fx_1334 DECIMAL(18,8) DEFAULT 1;
    DECLARE v_cr_1334 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_dr_1334 DECIMAL(6,4) DEFAULT 0;
    DECLARE v_tot_1334 DECIMAL(18,2) DEFAULT 0;
    SET v_fx_1334 = erp_fn_fx_rate('EUR','USD');
    SET v_cr_1334 = COALESCE(erp_fn_customer_credit(1), 0);
    SET v_dr_1334 = IFNULL(erp_fn_discount_rate(25), 0);
    SET v_tot_1334 = erp_fn_order_total(100);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('FXVAL', 1, 'RATE',
            CONCAT('fx ', CAST(v_fx_1334 AS CHAR), ' cr ', CAST(v_cr_1334 AS CHAR),
                   ' dr ', CAST(v_dr_1334 AS CHAR), ' tot ', CAST(v_tot_1334 AS CHAR)));
  END;

  -- invoice rollup block 1335: AR aging via joins + correlated subquery
  BEGIN
    DECLARE v_open_1335 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid_1335 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(i.gross_amount),0) INTO v_open_1335
      FROM erp_invoice i
      JOIN erp_customer c ON c.customer_id = i.customer_id
     WHERE i.status = 'OPEN'
       AND i.gross_amount > (SELECT IFNULL(AVG(x.gross_amount),0)
                               FROM erp_invoice x WHERE x.customer_id = i.customer_id);
    SELECT IFNULL(SUM(pa.amount),0) INTO v_paid_1335
      FROM erp_payment_alloc pa
      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1335 AS CHAR), ' paid ', CAST(v_paid_1335 AS CHAR)));
  END;

  -- gl reconciliation block 1336: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1336 INT DEFAULT 0;
    DECLARE v_acct_1336 INT;
    DECLARE v_dr_1336 DECIMAL(18,2);
    DECLARE v_cr_1336 DECIMAL(18,2);
    DECLARE gcur_1336 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1336 = 1;
    OPEN gcur_1336;
    gl_1336: LOOP
      FETCH gcur_1336 INTO v_acct_1336, v_dr_1336, v_cr_1336;
      IF v_gfin_1336 = 1 THEN LEAVE gl_1336; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1336, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1336 - v_cr_1336 AS CHAR)));
    END LOOP;
    CLOSE gcur_1336;
  END;

  -- transaction block 1337: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1337;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1337;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1337, 'COMMIT', 'savepoint block committed');
  END;

  -- temp-table block 1338: CREATE TEMPORARY TABLE + aggregate + drop
  BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1338;
    CREATE TEMPORARY TABLE tmp_agg_1338 (
      customer_id INT PRIMARY KEY,
      order_cnt   INT,
      order_amt   DECIMAL(18,2)
    );
    INSERT INTO tmp_agg_1338 (customer_id, order_cnt, order_amt)
    SELECT o.customer_id, COUNT(*), IFNULL(SUM(o.total_amount),0)
      FROM erp_order o
     GROUP BY o.customer_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'TMPAGG', t.customer_id, 'AGG',
           CONCAT('cnt ', CAST(t.order_cnt AS CHAR), ' amt ', CAST(t.order_amt AS CHAR))
      FROM tmp_agg_1338 t;
    DROP TEMPORARY TABLE IF EXISTS tmp_agg_1338;
  END;

  -- upsert block 1339: INSERT ... ON DUPLICATE KEY UPDATE
  BEGIN
    DECLARE v_key_1339 INT DEFAULT 2;
    INSERT INTO erp_stock_level (product_id, warehouse_id, bin_id, qty_on_hand, qty_reserved)
    VALUES (v_key_1339, 1, 1, 100, 0)
    ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + VALUES(qty_on_hand);
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('UPSERT', v_key_1339, 'MERGE', CONCAT('stock topped for ', CAST(v_key_1339 AS CHAR)));
  END;

  -- json block 1340: JSON_OBJECT / JSON_EXTRACT + generated column reference
  BEGIN
    DECLARE v_doc_1340 JSON;
    DECLARE v_sku_1340 VARCHAR(40);
    DECLARE v_tag_1340 VARCHAR(40);
    SELECT attributes, sku, JSON_UNQUOTE(JSON_EXTRACT(attributes, '$.tag'))
      INTO v_doc_1340, v_sku_1340, v_tag_1340
      FROM erp_product WHERE product_id = 1 LIMIT 1;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('JSON', 1, 'DOC',
            CONCAT('sku ', IFNULL(v_sku_1340,''), ' tag ', IFNULL(v_tag_1340,''),
                   ' obj ', CAST(JSON_OBJECT('sku', v_sku_1340, 'tag', v_tag_1340) AS CHAR)));
  END;

  -- cte block 1341: non-recursive CTE + LEFT/RIGHT join, FULL emulated via UNION
  BEGIN
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    WITH cust_1341 AS (
      SELECT c.customer_id, c.name, COUNT(o.order_id) AS ocount
        FROM erp_customer c
        LEFT JOIN erp_order o ON o.customer_id = c.customer_id
       GROUP BY c.customer_id, c.name
    ),
    prod_1341 AS (
      SELECT p.product_id, p.sku
        FROM erp_product p
       WHERE p.active = 1
    )
    SELECT 'CTE', cu.customer_id, 'JOIN',
           CONCAT(cu.name, ' o=', CAST(cu.ocount AS CHAR))
      FROM cust_1341 cu
      LEFT JOIN erp_order o ON o.customer_id = cu.customer_id
     UNION
    SELECT 'CTE', o2.customer_id, 'JOIN',
           CONCAT('rightonly ', CAST(o2.order_id AS CHAR))
      FROM cust_1341 cu2
      RIGHT JOIN erp_order o2 ON o2.customer_id = cu2.customer_id
     WHERE cu2.customer_id IS NULL;
  END;

  -- case block 1342: searched CASE + CROSS JOIN + self-join
  BEGIN
    DECLARE v_band_1342 VARCHAR(10);
    DECLARE v_amt_1342 DECIMAL(18,2) DEFAULT 0;
    SELECT IFNULL(SUM(total_amount),0) INTO v_amt_1342 FROM erp_order;
    SET v_band_1342 = CASE
        WHEN v_amt_1342 >= 10000 THEN 'HIGH'
        WHEN v_amt_1342 >= 1000  THEN 'MED'
        WHEN v_amt_1342 > 0      THEN 'LOW'
        ELSE 'ZERO'
      END;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'SELFJOIN', a.order_id, 'PAIR',
           CONCAT('band ', v_band_1342, ' peer ', CAST(b.order_id AS CHAR))
      FROM erp_order a
      JOIN erp_order b ON a.customer_id = b.customer_id AND a.order_id < b.order_id
      CROSS JOIN (SELECT 1 AS one) k
     LIMIT 50;
  END;

  -- repeat/while block 1343: REPEAT ... UNTIL and WHILE loops, GET DIAGNOSTICS
  BEGIN
    DECLARE v_i_1343 INT DEFAULT 0;
    DECLARE v_j_1343 INT DEFAULT 0;
    DECLARE v_rc_1343 INT DEFAULT 0;
    REPEAT
      SET v_i_1343 = v_i_1343 + 1;
      INSERT INTO erp_counter (bucket, tick) VALUES (CONCAT('R1343'), v_i_1343)
        ON DUPLICATE KEY UPDATE tick = v_i_1343;
    UNTIL v_i_1343 >= 3 END REPEAT;
    WHILE v_j_1343 < 3 DO
      SET v_j_1343 = v_j_1343 + 1;
    END WHILE;
    GET DIAGNOSTICS v_rc_1343 = NUMBER;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('LOOP', v_i_1343 + v_j_1343, 'ITER',
            CONCAT('i ', CAST(v_i_1343 AS CHAR), ' j ', CAST(v_j_1343 AS CHAR),
                   ' diag ', CAST(v_rc_1343 AS CHAR)));
  END;

  -- analytics block 1344: order/customer/product rollup (5-table join + window fn)
  BEGIN
    DECLARE v_cnt_1344 INT DEFAULT 0;
    DECLARE v_amt_1344 DECIMAL(18,2) DEFAULT 0;
    DECLARE v_avg_1344 DECIMAL(18,4) DEFAULT 0;
    DECLARE v_max_1344 DECIMAL(18,4) DEFAULT 0;
    SELECT COUNT(*), IFNULL(SUM(ol.line_amount),0), IFNULL(AVG(ol.qty),0), IFNULL(MAX(ol.qty),0)
      INTO v_cnt_1344, v_amt_1344, v_avg_1344, v_max_1344
      FROM erp_order o
      JOIN erp_customer c    ON c.customer_id = o.customer_id
      JOIN erp_order_line ol ON ol.order_id = o.order_id
      JOIN erp_product p     ON p.product_id = ol.product_id
      LEFT JOIN erp_product_category pc ON pc.category_id = p.category_id
     WHERE c.active = 1 AND p.active = 1;
    SET v_amt_1344 = v_amt_1344 + erp_fn_tax_amount(v_amt_1344, 'US');
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    SELECT 'ANALYTICS', o.order_id, 'RANK',
           CONCAT('rn ', CAST(ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.total_amount DESC) AS CHAR),
                  ' rs ', CAST(SUM(ol.line_amount) OVER (PARTITION BY o.customer_id) AS CHAR))
      FROM erp_order o
      JOIN erp_order_line ol ON ol.order_id = o.order_id
     GROUP BY o.order_id, o.customer_id, o.total_amount, ol.line_amount;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ANALYTICS', v_cnt_1344, 'ROLLUP',
            CONCAT('amt ', CAST(v_amt_1344 AS CHAR), ' avg ', CAST(v_avg_1344 AS CHAR),
                   ' max ', CAST(v_max_1344 AS CHAR)));
  END;

