      JOIN erp_payment pm ON pm.payment_id = pa.payment_id
      JOIN erp_invoice i  ON i.invoice_id = pa.invoice_id;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('ARAGE', 0, 'ROLLUP',
            CONCAT('open ', CAST(v_open_1351 AS CHAR), ' paid ', CAST(v_paid_1351 AS CHAR)));
  END;

  -- gl reconciliation block 1352: trial balance by account (cursor + GROUP BY)
  BEGIN
    DECLARE v_gfin_1352 INT DEFAULT 0;
    DECLARE v_acct_1352 INT;
    DECLARE v_dr_1352 DECIMAL(18,2);
    DECLARE v_cr_1352 DECIMAL(18,2);
    DECLARE gcur_1352 CURSOR FOR
      SELECT ga.gl_account_id, IFNULL(SUM(ge.debit),0), IFNULL(SUM(ge.credit),0)
        FROM erp_gl_account ga
        LEFT JOIN erp_gl_entry ge   ON ge.gl_account_id = ga.gl_account_id
        LEFT JOIN erp_gl_journal gj ON gj.gl_journal_id = ge.gl_journal_id
       GROUP BY ga.gl_account_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_gfin_1352 = 1;
    OPEN gcur_1352;
    gl_1352: LOOP
      FETCH gcur_1352 INTO v_acct_1352, v_dr_1352, v_cr_1352;
      IF v_gfin_1352 = 1 THEN LEAVE gl_1352; END IF;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TRIALBAL', v_acct_1352, 'BALANCE',
              CONCAT('net ', CAST(v_dr_1352 - v_cr_1352 AS CHAR)));
    END LOOP;
    CLOSE gcur_1352;
  END;

  -- transaction block 1353: START TRANSACTION + SAVEPOINT + ROLLBACK TO
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      INSERT INTO erp_audit_log (entity, entity_id, action, detail)
      VALUES ('TXN', 0, 'ERROR', 'savepoint block rolled back');
    END;
    START TRANSACTION;
    UPDATE erp_order SET status = 'PROCESSING' WHERE status = 'NEW';
    SAVEPOINT sp_1353;
    UPDATE erp_order_line SET line_amount = line_amount + 0
     WHERE order_id IN (SELECT order_id FROM erp_order WHERE status = 'PROCESSING');
    IF (SELECT COUNT(*) FROM erp_order WHERE status = 'PROCESSING') = 0 THEN
      ROLLBACK TO SAVEPOINT sp_1353;
    END IF;
    COMMIT;
    INSERT INTO erp_audit_log (entity, entity_id, action, detail)
    VALUES ('TXN', 1353, 'COMMIT', 'savepoint block committed');
  END;
END$$

DELIMITER ;
